WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[41873] = { title = "The Mead Master", description = "The vyrkul meadery overlooks the coast in northern Stormheim. Meet me there when you are ready, <name>.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Apprentice Meldir in Stormheim." }
WordHunterWoW_QuestEN[41874] = { title = "Talked to Tyrande to Start Events", description = "", objectives = "" }
WordHunterWoW_QuestEN[41875] = { title = "Found First Clue", description = "", objectives = "" }
WordHunterWoW_QuestEN[41876] = { title = "Umbraxis Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[41877] = { title = "Lady Lunastre", description = "Our friend Ly'leth contacted me. She requested that you meet her atop the Grand Promenade as it overlooks the city.\n\nHave your disguise ready just in case, {name}.", objectives = "Seek out Ly'leth at the Grand Promenade.", progress = "Hm?", completion = "I hope you have prepared yourself to enter the City. It is time." }
WordHunterWoW_QuestEN[41878] = { title = "The Gondolier", description = "I need your help.\n\nThe wine you so graciously distributed to the needy was the last of my reserves. Without more, these people here will risk succumbing to their thirst, and eventually becoming withered.\n\nI am dedicated to preventing this for as long as possible.\n\nThere is a woman by the name of Deline who owns and operates a small delivery service out of her gondola.\n\nFind her, identify yourself as my messenger, and offer your aid in acquiring the next shipment.", objectives = "Make contact with the Gondolier.", progress = "Unless you want a ride, you should keep moving.", completion = "Let's get started, shall we?" }
WordHunterWoW_QuestEN[41879] = { title = "A Lack of Punctuality", description = "You will likely have noticed on your way here that there are some very... busy... Nightborne running about.\n\nNaturally, the nobles lack any sense of discretion: they are couriers. They carry important missives.\n\nI give you this blade to perform a necessary service to our intelligence gathering. Use it to silently and quickly dispatch the couriers.\n\nTake their missives and bring them to me.", objectives = "" }
WordHunterWoW_QuestEN[41880] = { title = "Den of Shadows", description = "Placeholder: Thalyssra sends you to find Arluin Shadowblade, a deft assassin once in her employ/social circle. (whichever fits) Indicate that he would be an invaluable asset to making progress in the City with covert operations.", objectives = "Make contact with Arluin Shadowblade." }
WordHunterWoW_QuestEN[41881] = { title = "Fight Night: Heliosus", description = "", objectives = "" }
WordHunterWoW_QuestEN[41882] = { title = "Whispers of the Darkness", description = "Before our arrival, many of our own came to neutralize the threat here. They did not know what they were walking into.\n\nOur people are now suffering from the whispers. The Old Gods seek to corrupt them and turn them against their own.\n\nWake them from their stupor. Free them from the whispers any way you can.", objectives = "Free 6 Highmountain Protectors.", completion = "Well done, <name>. If left unchecked, the whispers can turn even the best of friends against one another." }
WordHunterWoW_QuestEN[41883] = { title = "Whispers of the Darkness", description = "Our Stonedark ally, Navarrogg, has asked for your aid.\n\nIt would seem a band of drogbar cultists known as the Necrodark are searching for something in the Vault of Neltharion.\n\nHe asks for you since you have been there before and held your own against its defenses.\n\nNavarrogg awaits you at the Obsidian Overlook.", objectives = "" }
WordHunterWoW_QuestEN[41884] = { title = "Dark Tales", description = "Spiritwalker Ebonhorn is stable... for now.\n\nHe once told me of the wards he maintains against the Old Gods. He placed them at key locations around this mountain, but kept them hidden from mortal eyes--even my own.\n\nIncapacitated like this, his wards cannot hold back the evil ones. No doubt this is the reason for their attack.\n\nTo find the wards, we must enter the echoes of Ebonhorn's past and commune with the spirits we find there.\n\nMeet me in Riverbend, {name}. It is there our search begins.", objectives = "Meet Spiritwalker Graysky in Riverbend.", completion = "The spirits hold many truths, <name>.\n\nWalking in their footsteps may reveal the locations of Ebonhorn's wards." }
WordHunterWoW_QuestEN[41885] = { title = "Naralex Kneel Seen", description = "", objectives = "" }
WordHunterWoW_QuestEN[41886] = { title = "Fight Night: Rats!", description = "", objectives = "" }
WordHunterWoW_QuestEN[41888] = { title = "Allegiance of Flame", description = "My rivals lay dead and there are none within the Firelands who dare oppose my rule!\n\nAs promised, I will unite with the other Elemental Lords in the defense of Azeroth. The armies of the Firelands will scorch the battlefield with the corpses of our enemies!\n\nGo now, mortal. Tell your Earthen Ring that the Firelord himself stands with you!", objectives = "Speak with Farseer Nobundo in The Heart of Azeroth.", progress = "What news do you bring from the Firelands?", completion = "I did not think that I would live to see the day when the four great Elemental Lords would unite with the mortal races of Azeroth.\n\nYou have done what no other Farseer has done in the history of the Earthen Ring.\n\nThis is truly a day that will be remembered for generations!" }
WordHunterWoW_QuestEN[41889] = { title = "Dazed of the Past", description = "Let's begin crafting this mount armor, shall we?", objectives = "Construct a Stonehide Leather Barding.", progress = "I'm quite anxious to see how it turns out.", completion = "Is there anything we can't do? I'm starting to think not!\n\nI'll make sure this barding gets to Mei. You hold on to the pattern and maybe you can make some profit with it." }
WordHunterWoW_QuestEN[41890] = { title = "Dark Side of the Moon", description = "Xavius has been this way, but his destination is unclear. The Nightmare smothers my mind!\n\nThese refugees tell of an ancient Moonwell hidden in the ruins ahead.\n\nIf it is uncorrupted, it will give me the focus I need. By Elune's light, we will find my husband yet.\n\nMeet me at the Moonwell at once, {class}.", objectives = "Protect Tyrande while she holds her vigil at the Ancient Moonwell.", completion = "He is still alive, but the rest remains to be seen. For your sake, let us pray that he is unharmed." }
WordHunterWoW_QuestEN[41891] = { title = "Tainted Growth", description = "The blood red petals of the Nightmare Flower seethe with chaotic energy. The plant twitches every now and then, releasing puffs of pollen into the air. \n\nThe nearby satyrs and keepers can be seen harvesting similar plants for little crimson seeds.\n\nThese seeds must be destroyed.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 5 Corrupted Seedlings and return them to Tyrande." }
WordHunterWoW_QuestEN[41893] = { title = "Given to Corruption", description = "A final favor for an old friend, perhaps? My age-old companion, Varethos, has fallen to the nightmare's torment. We once worked in unison to protect this land. His close ties to the land brought him low in this dark hour.\n\nAs with all who suffer this fate, there is no restoring him.\n\nPlease, {name}, bring him peace.", objectives = "Slay Keeper Varethos.", progress = "Is it done, then?", completion = "My sight fades, but I am glad that he rests." }
WordHunterWoW_QuestEN[41895] = { title = "The Master of Pets", description = "", objectives = "" }
WordHunterWoW_QuestEN[41896] = { title = "Operation Murloc Freedom", description = "", objectives = "" }
WordHunterWoW_QuestEN[41897] = { title = "The Master's Plan", description = "The purpose of the Twilight's Hammer has always been the same. They seek to bring about the end of the world. Their schemes may change, but their wicked purpose remains constant.\n\nDefeating the Twilight's Hammer is not simply a matter of defeating them in battle. If we are to be successful, we will need to uncover their scheme and put an end to whatever terrible plans they have created.\n\nLet us start by searching the encampment for clues as to their true purpose here.", objectives = "Collect the excerpts from The Master's Journal.", progress = "What vile scheme have the Twilight's Hammer plotted against the world this time?", completion = "If The Master is not stopped, the Twilight's Hammer will have all the power they need to conquer Deepholm and enslave the elements!\n\nWe must not allow that to happen." }
WordHunterWoW_QuestEN[41898] = { title = "Unleashing the Elements", description = "According to The Master's journal, the Twilight's Hammer has discovered a method of harnessing the void to subjugate even the most powerful of elementals.\n\nThe journal specifically mentioned the children of Therazane as test subjects. Whether The Master was speaking literally or figuratively in this regard, I do not know. Regardless, we need to free these elementals and stop these dark rituals from continuing.\n\nIt appears that our journey here is going to take us deeper into the depths of darkness...", objectives = "Release the Servants of Therazane from Twilight Depths.", progress = "Dark rituals such as these must not be allowed to continue.", completion = "The servants of Therazane are free and the dark rituals of subjugation have been halted... for now." }
WordHunterWoW_QuestEN[41899] = { title = "Held Captive!", description = "There are prisoners here, Farseer {name}, that are enslaved by the Twilight's Hammer.\n\nThe cultists work them to death in the depths of the mine.\n\nI cannot abide such cruel mistreatment! Let us clear a path through the mine and rescue any Twilight's Hammer prisoners we find, so that they may return to their homes and families.\n\nThe Twilight's Hammer will pay for their crimes!", objectives = "Rescue 10 Twilight Slaves from the Twilight Depths.", progress = "Have the slaves been rescued?", completion = "The captives have been set free, but there is still much more to be done if we are to dismantle the Twilight's Hammer cult..." }
WordHunterWoW_QuestEN[41900] = { title = "A Promise of Earth", description = "Deepholm thanks you, shaman.\n\nThe Twilight's Hammer has always sought dominion over my kingdom, but this latest threat was far greater than their previous efforts.\n\nFor your service to the elements of earth, I will pledge my armies to the Earthen Ring in the defense of Azeroth.\n\nI have no love for the mortal races, but this world is not the Burning Legion's to destroy.\n\nTell your Earthen Ring that Therazane the Stonemother stands with them!", objectives = "Speak with Advisor Sevel in the Heart of Azeroth.", completion = "It is good to see you safely back, Farseer. With Therazane's allegiance, we now have three of the Elemental Lords united to our cause.\n\nHowever, one still remains..." }
WordHunterWoW_QuestEN[41901] = { title = "Oath of the Windlord", description = "You have my thanks, mortal for bringing about my rebirth. However, thanks alone would not be honorable.\n\nI know that the Earthen Ring seeks to save Azeroth from the Burning Legion.\n\nI will pledge my sword, and the armies of Skywall to the aid of Azeroth.\n\nWhen the time for battle arrives, and the Earthen Ring stands upon the battlefield against the Burning Legion, the Windlord shall stand with you.", objectives = "Speak with Advisor Sevel.", completion = "The Windlord has pledged to aid The Earthen Ring in the war against the Burning Legion?\n\nThis is fortuitous news indeed!\n\nStill, there is little time for celebration, much remains to be accomplished." }
WordHunterWoW_QuestEN[41903] = { title = "Gathering the Pieces", description = "Grand Master, the Mission Table is now at your disposal.\n\nThere are several strategic areas where we can focus our Order's efforts.\n\nFirst, we should check on the status of the other monk temples. It seems the Legion has a special focus on destroying us.\n\nSecond, we need to scour the seas near the Broken Shore. There are still many missing from the battle.\n\nFinally, there is the continued appearance of demonic forces at numerous points across the Broken Isles. They must be kept at bay.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Interact with the Mission Table and complete five Order Hall missions." }
WordHunterWoW_QuestEN[41905] = { title = "Report from Tian Monastery", description = "We have heard from all our temples on Pandaria, except for one.\n\nWe dispatched a message by bird to Tian Monastery, but no answer has yet arrived. This silence is quite unusual.\n\nGrandmaster, I recommend that we send our champion, Chen Stormstout, to scout the situation at once.", objectives = "Use the Scouting Map and complete the mission, \"Investigate Tian Monastery.\"", progress = "What have you discovered?", completion = "Your champion moved swiftly, <name>! This report clearly indicates that Tian Monastery is under attack!" }
WordHunterWoW_QuestEN[41907] = { title = "Appropriations", description = "I have come to lend my help to the Order of the Broken Temple.\n\nMy job is to create a solid base of operations around here. Right now, we have wounded to tend and bellies to feed. After this, we can worry about building our defenses.\n\nLao Shu is in charge of our supply inventory. Go and speak with him now in the inn.", objectives = "Speak to Lao Shu in The Laughing Crane inn.", completion = "Ah, yes yes yes! High Elder Cloudfall was right to send you to me." }
WordHunterWoW_QuestEN[41909] = { title = "Tracking the Tideskorn", description = "We have sent scouts to search for our kidnapped allies, and our efforts may have finally paid off.\n\nThey've tracked them to the vrykul homeland of Stormheim, but the unfamiliar territory has slowed our progress and we're in danger of losing the trail.\n\nI suggest that we send our champions immediately to assist with the tracking effort.", objectives = "Use the Scouting Map and complete the \"Tracking the Tideskorn\" missions.", progress = "Did we gather enough information about the Legion forces at the Gates of Valor?", completion = "Excellent. It will be extremely dangerous to infiltrate the Gates, but with this information, we will know exactly the enemy's location and numbers." }
WordHunterWoW_QuestEN[41910] = { title = "Freya's Spring", description = "First, we need water from Freya's Spring.\n\nOnce a year, on the first day of solstice, the sun hits the white-capped summit of the highest peak in Highmountain. The melting snow runs through a ravine and collects in a crystalline pool.\n\nSome say these waters grant eternal youth. Silly stories if you ask me, but we will need this rare, purified water for our brew.\n\nI suggest sending our champions to collect us a sample, for your skills will be needed elsewhere.", objectives = "Use the Scouting Map and complete five \"Freya's Spring\" missions.", completion = "This water is filtered from only the freshest fallen snow every winter, and is a vital ingredient to our brew!" }
WordHunterWoW_QuestEN[41911] = { title = "Amaranthine Hops", description = "The hops for our brew must be a very specific, and they will also be hard to acquire.\n\nAmaranthine Hops only grow in the realm known as the Emerald Dream, meaning we can only acquire this ingredient from a druid.\n\nThere is one such supplier from whom I receive this item, but she may ask for something in exchange.", objectives = "Speak to Fleuris Asterleaf in Val'sharah and trade 20 Stonehide Leather for 1 bag of Amaranthine Hops.", progress = "Did you find Fleuris?", completion = "Mmmm, just smell those hops! This will be a good batch, I just know it." }
WordHunterWoW_QuestEN[41914] = { title = "Clear the Catacombs", description = "", objectives = "" }
WordHunterWoW_QuestEN[41915] = { title = "The Master's Legacy", description = "You work for a murderer and a thief.\n\nThat design he wants? It is called the magistrix cut, and it was perfected by my husband. He was killed by Lespin for his secret.\n\nI had him entombed in a small cave north of the city, for we could not make the trip to Tel'anor. Buried with him is a tome that contains the secrets of the design.\n\nRetrieve the design and keep it out of his hands!", objectives = "Investigate the Gemcutter's Tomb.", progress = "Where is the master?", completion = "Well well, looks like that old fool finally met his match?\n\nIt looks like the Promenade is in need of a new jeweler, and I think I have learned all I could from my former master.\n\nHere is something for your efforts." }
WordHunterWoW_QuestEN[41916] = { title = "A Better Future", description = "We must move quickly, {name}. I must save as many of my people as I can before the attack begins.\n\nWord has gotten out in the city that there is a safe haven with us and some no longer fear exile.\n\nVenture into the Grand Promenade, champion. Find those willing to join us and let them know it is time they made their escape.", objectives = "Rescue 8 Shal'dorei Insurgents in the Grand Promenade.", progress = "Each shal'dorei rescued is both a potential enemy vanquished and a new hope for our people.", completion = "Our strength grows and our enemies wane. We will win this fight, <name>!" }
WordHunterWoW_QuestEN[41917] = { title = "Vignette: Bear Cub", description = "", objectives = "" }
WordHunterWoW_QuestEN[41918] = { title = "The Dreamer Returns", description = "Arch Druid Greathoof will be expecting word on the success of our mission, but I'm afraid I must ask you to return alone.\n\nI can't rest knowing that Xavius has Lord Ursoc in his clutches. Just the thought of it makes me shake with rage! I'll find where he has been taken if I have to search every corner of Azeroth!\n\nOur paths will cross again, {name}. Be sure of it.", objectives = "Return to Arch Druid Greathoof in the Dreamgrove. You may use Dreamwalk to travel via the Emerald Dreamway.", completion = "So, Xavius is behind this. A thousand deaths isn't enough of a punishment for that defiler!\n\nBut, you have returned with the claws, that is not an accomplishment that even I could have performed.\n\nYou are truly the hero we need to face the Legion." }
WordHunterWoW_QuestEN[41919] = { title = "The Shadows Reveal", description = "The Fangs of the Devourer are wielded by Akaari Shadowgore, one of Kil'Jaeden's personal assassins. Every attempt on her life ends the same... she's gone before we even arrive.\n\n<Valeera scrawls a few lines on a piece of paper, then hands it to you.>\n\nBut not this time. We've been working with these contacts to find Akaari so we can finally take the Fangs for our own purposes.\n\nGo to each contact and tell them \"The shadows reveal.\" See what they know.", objectives = "Speak to your contacts in Dalaran to acquire intel on Akaari Shadowgore's whereabouts.", progress = "Hmm?", completion = "<Valeera glances in your direction.>\n\nAny luck?" }
WordHunterWoW_QuestEN[41920] = { title = "A Matter of Finesse", description = "A rune of portals?! Who does Val'zuun think he is?\n\n<Valeera takes a deep breath.>\n\nIt's worth the price, but those runes aren't exactly easy to come by. Unless...\n\nArchmage Celindra, the Kirin Tor's portal master, has a study in the center of town. We rogues aren't particularly welcome there, nor would she simply hand a rune over even if we were...\n\n<Valeera smirks.>\n\nBut who said anything about asking?", objectives = "Borrow a Rune of Portals from Archmage Celindra.", progress = "They say the Fangs of the Devourer have no equal. If that's true, they're worth any price.", completion = "Val'zuun actually kept his end of the bargain... I'm impressed." }
WordHunterWoW_QuestEN[41921] = { title = "Closing In", description = "The Legerdemain Lounge isn't far from here. We have agents nearby who can secure the area.\n\nCome prepared for a fight. Akaari won't go down easily.", objectives = "Confront Akaari Shadowgore in the Legerdemain Lounge.", progress = "I can't believe it...", completion = "It was a ruse?!" }
WordHunterWoW_QuestEN[41922] = { title = "Traitor!", description = "That lying demon SCUM! I should have known.\n\nLet's show Val'zuun what happens to people who dare cross the Uncrowned.", objectives = "Join Valeera Sanguinar in the Underbelly Descent.", completion = "He's lying again, I know it... but he might be our only option." }
WordHunterWoW_QuestEN[41924] = { title = "Fangs of the Devourer", description = "If you spare me I can use the rune of portals you provided to open a gateway to Akaari's citadel in the Twisting Nether.\n\nOf course, killing the Legion's master assassin in her own domain will be no simple feat, but surely the Fangs of the Devourer are worth the risk, no?\n\n<Val'zuun smiles.>\n\nI will guide you through the citadel once you arrive, but you will have to defeat Akaari on your own.", objectives = "Obtain the Fangs of the Devourer from Akaari Shadowgore.", progress = "Any luck?", completion = "I knew you'd succeed, <name>. I'm glad you're on our side." }
