WordHunterWoW_QuestEN[41926] = { title = "Returning Champion", description = "", objectives = "" }
WordHunterWoW_QuestEN[41927] = { title = "Ruining the Runewood", description = "", objectives = "" }
WordHunterWoW_QuestEN[41929] = { title = "Tutorial Lockbox Looted", description = "", objectives = "" }
