WordHunterWoW_QuestEN[41933] = { title = "Legion Portal", description = "", objectives = "" }
WordHunterWoW_QuestEN[41934] = { title = "The Brand of Damnation", description = "I require a symbol of my dominion as Firelord. A weapon that will strike fear into the hearts of all who dare to oppose my rule!\n\nDeep within the den of the Cinderweb, there is an ancient spear born from within the heart of the Firelands. Emberscar is a living weapon whose wicked power is beyond mortal comprehension.\n\nProve your strength and claim Emberscar in my name! If you survive, perhaps I will aid the feeble races of humanity against the Burning Legion.", objectives = "Retrieve Emberscar, Brand of Damnation.", progress = "The Brand of Damnation will be mine!", completion = "I see that you have successfully awakened Emberscar, and that it has been well-fed.\n\nPerhaps you are stronger than I first thought..." }
WordHunterWoW_QuestEN[41935] = { title = "Beasts of Burden", description = "", objectives = "" }
WordHunterWoW_QuestEN[41936] = { title = "You Have Been Challenged", description = "", objectives = "" }
WordHunterWoW_QuestEN[41937] = { title = "Combat Training", description = "[PH] Description", objectives = "[PH] Log Description" }
WordHunterWoW_QuestEN[41938] = { title = "Brothers of Skovald", description = "", objectives = "" }
WordHunterWoW_QuestEN[41942] = { title = "Legion Portal", description = "", objectives = "" }
WordHunterWoW_QuestEN[41944] = { title = "Jarrun's Ladder", description = "", objectives = "" }
WordHunterWoW_QuestEN[41945] = { title = "Tianji of the Ox", description = "Greetings, Grandmaster. Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.\n\nThe first task is critical. Tianji, a renowned trainer in the ox school style of martial combat, was on her way to the Broken Isles when she was attacked.\n\nI suggest we send Chen Stormstout to help her. He will be uniquely suited to this task.", objectives = "Use the Scouting Map and complete the mission, \"Tianji Needs Help\".", progress = "How is the mission proceeding?", completion = "Most excellent, Grandmaster! The mission was a success. Our new teacher, Recruiter Tianji, is getting situated as we speak." }
WordHunterWoW_QuestEN[41946] = { title = "Building Our Troops", description = "Our champions acquired the talents of Recruiter Tianji, a famed monk skilled in the school of the ox.\n\nShe is known for her brewmaster techniques, and is a valuable addition to the temple. She is already beginning to train a new batch of pupils.\n\nSpeak to her now and train an initiate of the ox.", objectives = "Speak to Recruiter Tianji and train an Ox Initiate.", progress = "How did the training go?", completion = "Excellent. These troops will be invaluable in our defense of the Broken Isles. Deploy them on missions, just as you would with our champions." }
WordHunterWoW_QuestEN[41947] = { title = "Legion Portal", description = "", objectives = "" }
WordHunterWoW_QuestEN[41948] = { title = "All Pets Go to Heaven", description = "", objectives = "" }
WordHunterWoW_QuestEN[41949] = { title = "The Drekirjar Return", description = "", objectives = "" }
WordHunterWoW_QuestEN[41950] = { title = "Cry More Thunder!", description = "You have proven yourself an ally of the Thorignir and we will lend you our strength. I would ask one last favor of our new champion, though. \n\nThe dragon who guided you to me awaits his vengeance against the vrykul. Together I wish for you to show these Drekirjar what it means to cross the Thorignir. Their toll must be paid in blood.\n\nSpeak to Vethir when you are ready.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Fly with Vethir and kill 150 of the God-King's allies in Hrydshal." }
WordHunterWoW_QuestEN[41951] = { title = "Legion Portal", description = "", objectives = "" }
WordHunterWoW_QuestEN[41952] = { title = "Rescue Efforts", description = "", objectives = "" }
WordHunterWoW_QuestEN[41953] = { title = "Vis'ileth", description = "", objectives = "" }
WordHunterWoW_QuestEN[41954] = { title = "Rescue Efforts", description = "", objectives = "" }
WordHunterWoW_QuestEN[41955] = { title = "Bloodline of Stone", description = "", objectives = "" }
WordHunterWoW_QuestEN[41956] = { title = "Petrified Acolytes", description = "", objectives = "" }
WordHunterWoW_QuestEN[41957] = { title = "The Vindicator's Plea", description = "I've obtained a request from Vindicator Boros in Dalaran asking for our help.\n\nHe has recovered a soldier who escaped from the Legion! He was injured and his wounds are resisting every healing treatment available to them. Normally this would fall to an acolyte to handle, but the soldier mentioned T'uure in his delirium! I thought the holy gem was lost!\n\nYou are strong with the Light, perhaps you can succeed where they can't?\n\nIf you need it, Brother Larry can provide you with a flight to Dalaran.", objectives = "Meet with Vindicator Boros in front of First to Your Aid in Dalaran.", completion = "Thank you for arriving in such haste, Brother." }
WordHunterWoW_QuestEN[41958] = { title = "Oh, Ominitron", description = "", objectives = "" }
WordHunterWoW_QuestEN[41959] = { title = "Legion Portal", description = "", objectives = "" }
WordHunterWoW_QuestEN[41960] = { title = "Rescue Efforts", description = "", objectives = "" }
WordHunterWoW_QuestEN[41961] = { title = "Black Rook Holdings", description = "Inside the chest, hidden amongst various knickknacks, is a signet engraved with a unique crest.\n\nThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner's finger.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Take the Warden's Signet to Jarod Shadowsong." }
WordHunterWoW_QuestEN[41962] = { title = "Black Rook Guard", description = "Inside the chest, hidden amongst various knickknacks, is a signet engraved with a unique crest.\n\nThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner's finger.Upon completion of this quest you will gain:", objectives = "Take the Warden's Signet to Jarod Shadowsong." }
