WordHunterWoW_QuestEN[41965] = { title = "Lunarwing Liberation", description = "", objectives = "" }
WordHunterWoW_QuestEN[41966] = { title = "House Call", description = "I thought Barrem was lost to us after the tragedy at Broken Shore, Light knows we lost far too many good soldiers just like him there.\n\nI was shocked to see he was still alive when one of our patrols arrived carrying him. They found him floating in the sea with wounds that would kill any lesser draenei.\n\nThere is something about those wounds that resists everything we've done to treat them. Please, {class}, as a brother in the Light I ask you to do all that you can to help him to recover.", objectives = "Treat the wounds of Defender Barrem.", completion = "I... I owe you my life, brother, but that look on your face tells me you're here for something else.\n\n<You tell Barrem about his mentioning of T'uure in his sleep.>\n\nI must have been dreaming of Alora, she was my cell mate in that accursed world the demons took me to. She told me she saw the crystal but never said much else.\n\nI just hope she is still alive." }
WordHunterWoW_QuestEN[41967] = { title = "Out of the Darkness", description = "Alora and I were were able to escape through one of the Legion's portals back to Azeroth but that's about as far as our luck got us.\n\nThe portal put us on a small isle somewhere to the west of the Broken Shore. They saw us quickly and we made a run for the protection of the water. As I attempted to leap to safety, I was wounded. But Alora... she tripped and I watched them drag her back.\n\nRescue her, please! I'll mark where the camp is on your map, just don't let her go through that ordeal again.", objectives = "Travel to Darkstone Isle near the Broken Shore and search for Alora.", completion = "I felt my soul being ripped from my body. If you hadn't come when you did... I don't even want to think about it!\n\nIs there anything I can do to repay you? I owe you my life after all.\n\n<You mention to her Barrem's story.>\n\nBarrem still lives too? Oh thank the light! Yes, I'll gladly tell you everything I know." }
WordHunterWoW_QuestEN[41978] = { title = "A Strong Defense", description = "", objectives = "" }
WordHunterWoW_QuestEN[41979] = { title = "Rescue Efforts", description = "", objectives = "" }
WordHunterWoW_QuestEN[41980] = { title = "Temple Defense", description = "", objectives = "" }
WordHunterWoW_QuestEN[41981] = { title = "Traversing the Heavens", description = "If you are not opposed, {name}, I would accompany you on your journey through Skywall.\n\nThere are wonders here that my eyes have never before beheld, and it would be my great honor to join you.\n\nOur quest to resurrect the mighty Thunderaan and unite the four great elemental lords will be no easy task.\n\nLead the way, Farseer, and I shall follow.", objectives = "Escort Farseer Nobundo through the Vortex Pinnacle." }
WordHunterWoW_QuestEN[41982] = { title = "Book Read Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[41984] = { title = "The Creeping Mists", description = "", objectives = "" }
WordHunterWoW_QuestEN[41985] = { title = "DEPRECATED: Fevered Request", description = "I must be hallucinating because I swear I can see a giant statue talking to me right now.\n\nIt's a good thing I'm writing this down. And this. And that. Help?You will receive:", objectives = "Bring 3 Field Packs to the location marked on your map. Treat the Fevered Explorer when you arrive." }
WordHunterWoW_QuestEN[41986] = { title = "REUSE", description = "", objectives = "" }
WordHunterWoW_QuestEN[41987] = { title = "Garn", description = "", objectives = "" }
WordHunterWoW_QuestEN[41988] = { title = "A Strong Defense", description = "", objectives = "" }
WordHunterWoW_QuestEN[41989] = { title = "Blood of My Blood", description = "As my darling brother has demonstrated, Elisande's decision to bring down the shield has sown unrest among the nightborne.\n\nLoyalists and demons march together in the streets. Fear and distrust grip our hearts. Family turns against family.\n\nI will help Thalyssra stir a new rebellion, but first we must deal with Anarys.\n\nI do not wish to spill the blood of my blood - only to help him see reason.\n\nAnarys is likely brooding over our father's memorial. Bring him to me alive.", objectives = "Defeat Anarys Lunastre and deliver <him/her> to Ly'leth Lunastre.", progress = "Anarys could halt our efforts before they begin.", completion = "Thank you. Now our work can begin." }
WordHunterWoW_QuestEN[41990] = { title = "Chopped", description = "", objectives = "" }
WordHunterWoW_QuestEN[41991] = { title = "Rescue Efforts", description = "", objectives = "" }
WordHunterWoW_QuestEN[41992] = { title = "Twisted Ash", description = "", objectives = "" }
WordHunterWoW_QuestEN[41993] = { title = "Salvation From On High", description = "I was serving aboard the airship that crashed on the way to the Broken Shore. I must have blacked out as the next thing I remember was being jolted awake. I was on a broken land and above me stood a man'ari carrying a staff of darkened crystal. There is no mistaking it, that staff was T'uure!\n\nAll my life I've heard stories about how T'uure flowed with the healing power of the light. Somehow the crystal has been darkened by Man'ari. We must get it back and restore it to its pure form!", objectives = "Something unexpected has interrupted your discussion, deal with it!", completion = "You seek a demon with a staff of crystal? The Eredar that calls itself Lady Calindris has one that matches your description perfectly.\n\nShe's MY prey though! I've been chasing her minion all over the isles and I'm not about to let this opportunity pass.\n\nI could use someone to watch my back though. If you help me out I'd be willing to let you take this staff you seek. I don't care about her equipment, it's her soul that I'm after.\n\nWell, what do you say?" }
WordHunterWoW_QuestEN[41994] = { title = "Legion Portal", description = "", objectives = "" }
WordHunterWoW_QuestEN[41995] = { title = "Dark Corruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[41996] = { title = "Tangled Nightmare", description = "", objectives = "" }
WordHunterWoW_QuestEN[41997] = { title = "A Strong Defense", description = "", objectives = "" }
WordHunterWoW_QuestEN[42000] = { title = "Seeker of Truth", description = "You may be familiar with Orik Trueheart. He has devoted his time after the Northrend campaign to learning more about Tyr. \n\nOrik has evidence of a powerful shield crafted by Tyr long ago. With the help of the Sunwalkers, we may finally be able to seek it out.\n\nPlease speak to him immediately.", objectives = "Speak with Orik Trueheart in Dalaran.", progress = "I'm glad yer in. We've quite the journey ahead.", completion = "I'm glad yer coming. I've been wanting to pursue this for some time now. With help from the Seers, I think it can be done!" }
WordHunterWoW_QuestEN[42001] = { title = "Aluneth, Greatstaff of the Magna", description = "Aluneth... a powerful and dangerous weapon. If tales are to be believed, Aluneth is actually the name of a very old and very powerful arcane entity, somehow bound to a staff through ancient magic.\n\nWhen Aegwynn relinquished Aluneth many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away in secret. Only they would know exactly where it was taken.\n\nThe dragon Kalec may be our best chance. He now resides on the Council of Six.", objectives = "Meet Kalec at the Violet Citadel in Dalaran.", completion = "So you seek Aluneth? A dangerous weapon, to be sure.\n\nLong ago the Kirin Tor entrusted the blue dragonflight with its safekeeping. It was locked away in the only place that could contain its rampant power  - the Nexus Vault.\n\nI have not been there in some time, however. After the blue dragonflight was dissolved, the Nexus was all but abandoned. There is no knowing whether the Nexus Vault is still intact - or what may be waiting in the Nexus itself." }
WordHunterWoW_QuestEN[42002] = { title = "To Northrend", description = "Naturally I've done some legwork already. I believe this Gorvold is buried at Shield Hill in the Howling Fjord.\n\nTahu can help locate the grave, and with a short ritual we should have our answers!\n\nMeet us at Shield Hill in the Howling Fjord and we'll move on to the next step.", objectives = "Meet Orik Trueheart on Shield Hill in Howling Fjord.", completion = "I trust the journey wasn't too long or hard.\n\nLet's go find our dead adventurer, eh?" }
WordHunterWoW_QuestEN[42003] = { title = "Kept Secret, Kept Safe", description = "With the scrolls in hand, now you must set to the task of finding the staff.\n\nWhen Aegwynn relinquished it many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it.\n\nThe dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Meet Kalec at the Violet Citadel in Dalaran.With the scrolls in hand, now you must set to the task of finding the staff.\n\nWhen Aegwynn relinquished it many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it.\n\nThe dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[42004] = { title = "Ghostship", description = "", objectives = "" }
WordHunterWoW_QuestEN[42005] = { title = "The End of the Saga", description = "Ye should read the saga yerself, it's right here.\n\nWe're here to speak to the spirit of that vrykul I spoke of. Tahu Sagewind is a powerful Seer and he should be able to bring his spirit back. It will be up to us to convince him to speak.\n\nYou should speak with Tahu so we can get started.", objectives = "Get the end of the story from the spirit of the saga hero.", completion = "I think I already have a lead on that island. Word around the tavern was a great warrior had broken into a vrykul king's tomb on an island in Stormheim.\n\nThat's got to be the one we're looking for!" }
WordHunterWoW_QuestEN[42006] = { title = "A New Threat", description = "If you seek the Nexus, be wary. There are strange happenings in Coldarra, and it would be best to understand them before proceeding.\n\nDuring my last visit to Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was integral to Malygos' plans during the Nexus War, whatever is there may explain the current state of the Nexus.\n\nHere, take this image crystal. I must remain in Dalaran on Kirin Tor business, so we will speak through it. Good luck.", objectives = "Search the Azure Dragonshrine for clues regarding the current state of the Nexus.", progress = "The communication device is inactive.", completion = "This appears to be a communication device commonly utilized by the ethereals.\n\nPerhaps it could be the key to finding out who is behind the happenings at the Dragonshrine." }
WordHunterWoW_QuestEN[42007] = { title = "A Forgotten Enemy", description = "The device still hums with power. It must have been abandoned not long ago.\n\nThe nearby switch appears to activate it.", objectives = "Activate the Ethereal Communication Device at the Azure Dragonshrine." }
WordHunterWoW_QuestEN[42008] = { title = "Eyes of the Dragon", description = "You should travel at once to Coldarra in Borean Tundra, {name}. There, I would recommend you scout out a few key locations and report back to me. \n\nI know the area well, and should be able to tell you how to proceed.\n\nMake haste!", objectives = "Scout out the key locations in Coldarra." }
WordHunterWoW_QuestEN[42009] = { title = "Harnessing the Arcane", description = "The energy from Aluneth lashes out from within the weakened Nexus Vault.  We may be able to use this raw, chaotic energy to our advantage.\n\nIf we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.", objectives = "Empower yourself with Unstable Arcane Energy by defeating Arcane Aberrants or siphoning from Breaches of Arcane Energy around the foundation of the Nexus." }
WordHunterWoW_QuestEN[42010] = { title = "Arcane Unleashed", description = "You have the power you need to destroy the Surge Needles. \n\nAt the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Aluneth into these points. The reaction should cause an overload, destroying the Surge Needle above.\n\nYou must act quickly. The Ethereum won't sit idly by as you lay waste to their machinations.", objectives = "Use your built up Unstable Arcane Energy to destroy the Surge Needles in Coldarra." }
WordHunterWoW_QuestEN[42011] = { title = "The Nexus Vault", description = "If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. \n\nWe have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Aluneth, I ask that you also free my brother from their grip.\n\nWith the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, {name}.", objectives = "Defeat Nexus-Prince Bilaal and claim Aluneth, Greatstaff of the Magna.", completion = "You have my gratitude for saving Azuregos, <name>. I can rest easy knowing that the Nexus is under his care.\n\nAs for you, I can see you're full of surprises. Never in my time have I seen a <class> who can control the chaotic energies of Aluneth. \n\nThank you for what you have done for me and my kind today. You are truly the hero we need to face the Legion." }
WordHunterWoW_QuestEN[42012] = { title = "A Gift of Time", description = "You have done a great thing for the blue dragons today, <name>, as well as for my own peace of mind.\n\nNow, armed with Aluneth, I only ask that you fulfill your original goal, and take the fight to the Legion.\n\nI believe your comrades await your back in the Hall of the Guardian. Safe travels, friend.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Meet Meryl Felstorm in the Hall of the Guardian." }
WordHunterWoW_QuestEN[42013] = { title = "The Helmouth", description = "", objectives = "" }
WordHunterWoW_QuestEN[42014] = { title = "A Tainted Vintage", description = "", objectives = "" }
WordHunterWoW_QuestEN[42015] = { title = "Threads of Fate", description = "", objectives = "" }
WordHunterWoW_QuestEN[42017] = { title = "Shrine of the Truthguard", description = "We'll be flying straight to the island. My friend said that the warrior who came here before us never entered the shrine itself, since they were after one of the tombs.\n\nIf a vrykul hero couldn't enter the shrine, I bet it's still protected by Tyr's power. I'm thinkin' we have a good shot at this.\n\nMy pal Cato will meet us there. We might be needin' the talents of a good healer!", objectives = "Go to Shield's Rest in Stormheim and claim the Truthguard.", completion = "I am heartened that your quest was a success, <name>. We have been awaiting your return." }
WordHunterWoW_QuestEN[42018] = { title = "Those Beyond Redemption", description = "", objectives = "" }
WordHunterWoW_QuestEN[42019] = { title = "Tip the Scales", description = "", objectives = "" }
