WordHunterWoW_QuestEN[42029] = { title = "Rise, Champions [NYI]", description = "[Tutorial quest flow not yet implemented. Skip forward.]You will receive:", objectives = "[Tutorial quest flow not yet implemented. Skip forward.]You will receive:" }
WordHunterWoW_QuestEN[42030] = { title = "Building Our Troops [NYI]", description = "[Tutorial quest flow not yet implemented. Skip forward.]You will receive:", objectives = "[Tutorial quest flow not yet implemented. Skip forward.]You will receive:" }
WordHunterWoW_QuestEN[42031] = { title = "Dire Growth", description = "Naralex asks for you to join him. He is ready to analyze the sample that he brought back from Shaladrassil.", objectives = "Meet with Naralex, plant the Lasher Seed, and analyze its effects.", progress = "I have never seen anything like this...", completion = "You were just with Naralex? What were the results of the sampling?" }
WordHunterWoW_QuestEN[42032] = { title = "Sampling the Nightmare", description = "There is still so much that we don't know about the Nightmare.\n\nBefore we can fight it, we must understand how it spreads.\n\nLet us send our champions to the roots of Shaladrassil in Val'sharah, and ask them to bring back samples to study.", objectives = "Complete the mission, \"Sampling the Nightmare.\"", completion = "Our champions returned from Shaladrassil just moments ago, Archdruid. The journey was a great success!" }
WordHunterWoW_QuestEN[42033] = { title = "Malorne's Refuge", description = "I see... it is as we have always feared. The Emerald Nightmare has found our world.\n\nWe must call upon the ancient god, Malorne.\n\nTravel southeast to the shrine at Malorne's Refuge. There, we druids have kept a sacred relic for thousands of years, a gift from the white stag himself.\n\nI already sent Broll Bearmantle ahead to give word of your arrival.", objectives = "Speak to Broll Bearmantle at Malorne's Refuge in Val'sharah.", completion = "I'm glad you are here, <name>, but if only we had arrived earlier! This place was in chaos when I arrived.\n\nThe survivors claim they were attacked by satyr, but how can this be? No satyrs have roamed these woods since ancient times." }
WordHunterWoW_QuestEN[42034] = { title = "Grip of Nightmare", description = "Most of the druids were able to escape, but the shrine is still swarming with enemies.\n\nThe shrine's leader, Sylendra  Gladesong, stayed behind to recover Malorne's Idol. We must go back and help her.", objectives = "Kill 5 Darkfiend Raiders, rescue Sylendra Gladesong, and examine the Altar of Malorne.", completion = "The satyr have never been this bold, or powerful. They took us completely by surprise, and our magic could not withstand their attacks. Without you, I would not have survived.\n\nI have only one purpose now - to recover that idol." }
WordHunterWoW_QuestEN[42035] = { title = "Tracking the Enemy", description = "The Idol may be stolen, but there is still hope.\n\nWhile I was trapped at the shrine, I saw the satyr raiders make off with the relic. Their tracks will still be fresh.\n\nWith our heightened senses, we may still be able to pick up their trail.\n\nWe must follow their signs through the forest and recover the Idol!", objectives = "Use your Cat Form to follow the satyr's tracks.", completion = "Look what we dragged in." }
WordHunterWoW_QuestEN[42036] = { title = "Idol of the Wilds", description = "We were able to wrest a confession out of this one. We know that their leader took the idol into Moonclaw Vale, but he could be hiding anywhere.\n\nSurely one of these satyrs will know where it was taken.\n\nGet the information out of these satyrs, even if it's the last thing they do.", objectives = "Attack 6 Darkfiend Satyr and extract information about the Idol of the Wilds.", progress = "Did you recover the Idol of the Wilds?", completion = "The Idol... so relieved am I to see it in your hands, <name>.\n\nWe will keep it here at the Dreamgrove for safekeeping." }
WordHunterWoW_QuestEN[42037] = { title = "Gathering the Dreamweavers", description = "Now that you've recovered the Idol of the Wilds, it's time to put it to use to commune with Malorne. However, the ritual will need the combined power of many druids.\n\nSend your champions to gather the druids of our order, and tell them to meet us in Nordrassil. We will need to do this together.", objectives = "Retrieve druids by completing \"Gathering the Dreamweavers\" missions.", completion = "Good, the druids have gathered. Even now, they should be flocking to Nordrassil to prepare for the ritual." }
WordHunterWoW_QuestEN[42038] = { title = "Champion: Broll Bearmantle", description = "", objectives = "I have seen enough of the Nightmare to know that it is not an idle threat. Within its grasp, even the strongest become their own worst enemies.\n\nYou, however, have displayed courage and fortitude even in the face of this great danger. I feel faith that you will lead us to victory against our enemy.\n\n<name>, I wish to pledge my loyalty in service of you and the druidic order" }
WordHunterWoW_QuestEN[42039] = { title = "Champion: Sylendra Gladesong", description = "", objectives = "<name>, I owe you my life. Your actions gave me a second chance, and it is a chance I have no intention of squandering.\n\nWith your help, we were able to recover the Idol of the Wild. Such a sacred relic would have been a devastating loss had it fallen into the wrong hands.\n\nNow, I will see this journey through to its end.\n\nLet me fight for you. If there is anyone who can defeat the Nightmare, I believe it is you." }
WordHunterWoW_QuestEN[42040] = { title = "The Way to Nordrassil", description = "The time has come for us to use the Idol of the Wilds and commune with Malorne.\n\nThe ritual will require a great deal of power, so we have decided to convene at Nordrassil and draw upon the World Tree's essence.\n\nThere is no time to waste. The fastest path will be through the Emerald Dreamway. Go ahead, and we will follow.", objectives = "Speak to Archdruid Hamuul Runetotem in the Emerald Dreamway.", completion = "Something isn't right here, <name>. This isn't the Dream. Could Xavius' creatures have invaded our sanctuary? How did they get past our protective wards?" }
WordHunterWoW_QuestEN[42041] = { title = "Enduring the Nightmare", description = "We are under attack here, {name}!\n\nCreatures of the Nightmare are spilling into the Dreamway as we speak.\n\nDestroy them. They cannot be allowed to linger, or else the Nightmare will take root here, too!", objectives = "Kill 12 aberrations of Nightmare.", progress = "Is it done?", completion = "Good, I already feel the Nightmare's power waning." }
WordHunterWoW_QuestEN[42042] = { title = "Teensy Weensies!", description = "Oh {name}, I'm so very very happy to see you!\n\nThe woodland critters whispered there was trouble in the Dreamway so I came immediately!\n\nThere are so very many teensy weensy little creatures that live here in the Emerald Dream, and they're out there, all lost and alone!\n\nWould you go out there and gather them up? You can use my flute to call them to you.\n\nThank you, brave druid!", objectives = "Use Mylune's Flute to gather 15 Teensy Weensy Fae Dragons.", progress = "Ohhh, the teensy weensy fae dragons are so cute! Are they all right?", completion = "Yay, they're saved! Thank you!" }
WordHunterWoW_QuestEN[42043] = { title = "Cleaning Up", description = "When the Nightmare spreads, it consumes the life force of all that it touches.\n\nThe more it spreads, the weaker our magic becomes.\n\nIn its early stages, before the taint has taken hold, we can still cleanse the affected areas.\n\nI will bless you with Elune's grace. By channeling her power, you can reverse the Nightmare's spread.", objectives = "Cleanse 100 Nightmare Creep.", progress = "Did you restore the Dream?", completion = "Excellent work, <name>. I knew that Elune's power could purify the nightmare's taint. Her blessing is strong here." }
WordHunterWoW_QuestEN[42044] = { title = "A Dying Dream", description = "Deep in the heart of the swamp lies an ancient protector of the Dreamway, Witherheart.\n\nHe was among the first defenders to battle against the Nightmare, but he has fallen to total corruption.\n\nIt pains me to say it, but we must destroy him.", objectives = "Kill Witherheart.", progress = "No one is safe from the Nightmare.", completion = "Today I grieve for a fallen ally, one who has wandered these forests for eons.\n\nHe can now be at peace, knowing he gave his life to protect this sacred place." }
WordHunterWoW_QuestEN[42045] = { title = "Communing With Malorne", description = "Our work here is done, {name}. We have successfully defended the Dreamway. It will be only a matter of time before it is restored to its former state.\n\nBut we have more important matters at hand.\n\nTake the Idol of the Wilds and go onward to Nordrassil. With any luck, they have already gathered. We will meet you there.", objectives = "Speak to Remulos at Nordrassil.", progress = "I am glad to see you, <name>.", completion = "My grandfather, Malorne, the ancient god of the wilds himself... long have I wished for this day, only to find that he is in great peril.\n\nIf he is trapped in the Nightmare, then what hope remains for the rest of us?" }
WordHunterWoW_QuestEN[42046] = { title = "A New Beginning", description = "If Malorne is in danger, then things are even worse than I feared. It truly is up to us now.\n\nWe have very little time left. Let us reconvene in the Dreamgrove at once.", objectives = "Meet Archdruid Rensar Greathoof at the Dreamgrove in Val'sharah.", completion = "Thank you for all of your heroic efforts, great <class>. Without your help, we could not have recovered the Idol and spoken to Malorne himself.\n\nNow that we know he is trapped in the Nightmare, we can devise a plan." }
WordHunterWoW_QuestEN[42047] = { title = "Champion: Hamuul Runetotem", description = "", objectives = "I have served the wilds for as long as I can remember, mentoring young druids and watching them grow in knowledge and experience.\n\nThere are few who have ascended to the rank of archdruid, but I believe you can become one of our best.\n\nI would be honored to follow your leadership of the grove." }
WordHunterWoW_QuestEN[42048] = { title = "Champion: Mylune", description = "", objectives = "Oh, hi <name>! My woodland friends just couldn't stop talking about you after you left, and it was they who convinced me to come find you here!\n\nA noble <class> with your courage and kindness just doesn't come along every day.\n\nThis is going to be SO much fun, don't you think?" }
WordHunterWoW_QuestEN[42049] = { title = "Powering the Portal", description = "If Malorne is trapped in the Nightmare, we must try to save him. It may sound like a fool's errand, but we cannot sit by idly.\n\nThere is an abandoned portal within the Emerald Dreamway, one that we druids closed long ago because it leads to the Rift of Aln.\n\nTo infuse it with energy once again, we will need shards of Nightmare which can be found on satyr lieutenants.\n\nSend our champions to hunt and kill these enemies.", objectives = "Collect 10 Shards of Nightmare from \"Powering the Portal\" missions.", progress = "How many shards have we collected?", completion = "Excellent. These shards are positively surging with negative energy. Be careful when touching them, <name>." }
WordHunterWoW_QuestEN[42050] = { title = "Defenders of the Dream", description = "Never has our order faced such a difficult challenge. To succeed, we must rely on each other's strengths.\n\nHowever, we only have a few defenders to spare for the battle ahead.\n\nBroll, Sylendra, Zen'tabra, and Mylune have all volunteered to accompany you into the valley below, but I can only spare one.\n\nWhich one will you choose to aid you in battle?", objectives = "Choose an ally.", progress = "Have you chosen?", completion = "Well chosen. The others will aid me in defending here. We must hurry." }
WordHunterWoW_QuestEN[42051] = { title = "Enter Nightmare", description = "The portal to the nightmare is ready, {name}. Remulos and the others have already gone ahead.\n\nThere is no telling what horrors await on the other side, {name}. Good luck.", objectives = "Go through the Nightmare Portal in the Emerald Dreamway.", completion = "Do not be deceived, <name>. What appears to be the mountains of Hyjal, is in fact an illusion created by our enemy.\n\nThis is a re-creation of the darkest nightmare in Malorne's mind. This is the War of the Ancients, a battle that occurred thousands of years ago.\n\nIt was during this war that Azeroth was first threatened by the Burning Legion, and the War in which Malorne and the Wild Gods fell." }
WordHunterWoW_QuestEN[42052] = { title = "The Shade of Xavius", description = "Brightwing loves nice things - rainbows, unicorns, and flowers! But enemies, Brightwing does not forget. Brightwing remembers for a long, long time those that hurt the grove.\n\nNow, we must destroy our enemies... so that the grove can be nice and happy forever!\n\nFriend, go to Darkheart Thicket beneath the roots of Shaladrassil.\n\nThere, find the one named Xavius... the one who started it all. Kill him, and bring me his head.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Retrieve the Fragment of Xavius from the Shade of Xavius in Darkheart Thicket." }
WordHunterWoW_QuestEN[42053] = { title = "The War of the Ancients", description = "To free Malorne, we must win the War of the Ancients. A millennia ago, this battle took the combined efforts of the greatest defenders of our world. To win now, we must do the same.\n\nGo upon the battlefield and defeat Legion foes, rescue and revive our allies, and free the innocent who have been caught in the battle. Every enemy defeated and every ally saved will help turn the tide in our favor!", objectives = "Win the War of the Ancients.", completion = "You lead us to triumph today, <name>." }
WordHunterWoW_QuestEN[42054] = { title = "Archimonde, The Defiler", description = "We have turned the battle, {name}! The Burning Legion is greatly weakened.\n\nOnly one task remains. Malorne is locked in battle with Archimonde, the demon that slew him ten thousand years ago.\n\nRemember, {name}, we are trapped in Malorne's nightmare. There is no telling what will manifest here, but we MUST do something.\n\nMay Elune guide us, {name}.", objectives = "Defeat Archimonde.", completion = "<Malorne gazes directly at you. Radiant, soothing energy exudes outward from his body. Suddenly, you feel a serene sense of peace and gratitude envelop your entire being.>" }
WordHunterWoW_QuestEN[42055] = { title = "The Demi-God's Return", description = "<Malorne's voice echoes in your mind.>\n\nMortal you may be, but your valor is worthy of the ancient gods.\n\nNature's spirit lives in you - vibrant, wild, and ferocious. I witness in you the essence of nature's spark - the WILL to survive.\n\nOur triumph here will be spoken of for ages to come, {name}.\n\nReturn to the waking world through this portal. We will speak again when we return to the Dreamgrove.", objectives = "Receive Malorne's blessing.", progress = "Nature's cycle is beautiful, but it can be frail. We must preserve its balance.", completion = "<name>, we elders of the Dreamgrove have spoken and all agree. We would like to see you take leadership of the Dreamgrove.\n\nToday, we grant you the title of Arch <class> of the Dreamgrove, a nomination of the highest honor in our order.\n\nWith it, you now carry the responsibility of our order: to protect the wilds! Lead well, <name>." }
WordHunterWoW_QuestEN[42056] = { title = "Champion: Remulos", description = "", objectives = "We have come a long way together, <name>. At every step, your choices have led the Dreamgrove to victory.\n\nI would give my life to defend Azeroth, and I know you would do the same.\n\nGreat danger still faces us. <name>, take my pledge. We must serve and protect the wilds!" }
WordHunterWoW_QuestEN[42058] = { title = "DEPRECATED: Crumpled Request", description = "Legs broken? Check. Arm broken? Check. Writing hand broken? Nope!\n\nBut seriously, someone please send help. I'm in so much pain right now I think I'm about to pass o...You will receive:", objectives = "Bring 2 Silkweave Splints and 1 Field Pack to the location marked on your map. Treat the Injured Adventurer when you arrive." }
WordHunterWoW_QuestEN[42061] = { title = "Charge Trigger Hit", description = "", objectives = "" }
WordHunterWoW_QuestEN[42062] = { title = "Fight Night: Stitches Jr. Jr.", description = "", objectives = "" }
WordHunterWoW_QuestEN[42063] = { title = "Size Doesn't Matter", description = "", objectives = "" }
WordHunterWoW_QuestEN[42064] = { title = "It's Illid... Wait.", description = "", objectives = "" }
WordHunterWoW_QuestEN[42065] = { title = "The Twilight Master", description = "There is only one more thing that remains, Farseer {name}. We must confront the leader of the Twilight's Hammer and put an end to their sinister plot once and for all.\n\nWithout their so-called master, the remaining cultists will be forced to retreat from Deepholm.\n\nOnly when The Twilight's Hammer has been crushed and Deepholm has been saved, will we have the support of Therazane against the demons of the Burning Legion.", objectives = "Defeat the Mistress of Twilight.", completion = "So, the Mistress of Twilight was actually a dragon... I thought the brood of Sintharia had all been defeated.\n\nI wonder if Zeryxia was not the last of her kind..." }
WordHunterWoW_QuestEN[42067] = { title = "All Howl, No Bite", description = "", objectives = "" }
WordHunterWoW_QuestEN[42068] = { title = "The Return of Twilight", description = "The Twilight's Hammer has reemerged and they are building an army to overthrow my kingdom. A ludicrous fantasy on their part, but one that I cannot take lightly.\n\nI cannot offer the mortal races my aid until the threat to Deepholm has been dealt with. If you truly wish to unite the Elemental Lords to your cause, I would see you prove it.\n\nGo. Uncover the plot that the Twilight's Hammer is hatching and put an end to their scheme!", objectives = "Speak with Muln Earthfury in Deepholm.", completion = "It is good that you have arrived, Farseer <name>. The Twilight's Hammer has built a formidable stronghold here in Deepholm." }
WordHunterWoW_QuestEN[42069] = { title = "Felbats", description = "", objectives = "" }
WordHunterWoW_QuestEN[42070] = { title = "Warden Tower Assault: Starstalker's Point", description = "", objectives = "" }
WordHunterWoW_QuestEN[42071] = { title = "Honoring the Past", description = "", objectives = "" }
WordHunterWoW_QuestEN[42072] = { title = "Boros Tracker", description = "", objectives = "" }
WordHunterWoW_QuestEN[42073] = { title = "Boros Tracker Two", description = "", objectives = "" }
WordHunterWoW_QuestEN[42074] = { title = "Return of the Light", description = "Excellent!\n\nThere is a gateway further down this pathway and like most Legion constructs it is powered by souls.\n\nI think the death of that Inquisitor should be just enough to activate it and open the way back to where it came from.\n\nLet's go see where the path takes us, shall we?", objectives = "Accompany Jace Darkweaver through the portal and obtain T'uure, Beacon of the Naaru.", completion = "It is T'uure! I had thought it was lost to us forever!\n\nWhen I last saw this staff we were escaping from a small world called Niskara. The Legion came upon us unawares, we were only able to escape thanks to a few brave Vindicators who remained behind with T'uure to stall their attack.\n\nI did not think it could be done, but you were able to recover T'uure. You truly walk in the light, <name>. You have my respect, and my thanks." }
WordHunterWoW_QuestEN[42075] = { title = "Botanical Backlash", description = "", objectives = "" }
WordHunterWoW_QuestEN[42076] = { title = "Shadowfen Village", description = "", objectives = "" }
WordHunterWoW_QuestEN[42077] = { title = "Waking Nightmares", description = "", objectives = "" }
WordHunterWoW_QuestEN[42078] = { title = "Ysondre's Seal", description = "", objectives = "" }
WordHunterWoW_QuestEN[42079] = { title = "Masquerade", description = "Our family commands great respect in this city, thanks to my father. Through my network of contacts, we can organize the citizens to prepare Suramar for Thalyssra's return.\n\nYou must walk among the nightborne. You must earn the trust of our friends and foes alike.\n\nYou must become someone else.\n\n<Ly'leth hands you a shimmering party mask.>\n\nPut this on Anarys.", objectives = "Use the Mask of Mirror Image on Anarys Lunastre.", progress = "Not to worry, it will not hurt him.", completion = "My little brother is about to turn over a new leaf, whether he likes it or not." }
WordHunterWoW_QuestEN[42080] = { title = "Bastion of Bradensbrook", description = "", objectives = "" }
WordHunterWoW_QuestEN[42081] = { title = "In With the New", description = "Well, here's your new conduit. Try not to break this one, I really don't feel like making another.\n\nOh, and tell your boss, Deucus, that he owes me big time for this.", objectives = "Bring the newly forged High-Capacity Decoction Conduit to Deucus in Dalaran.", completion = "You're finished? Let's see it!\n\n<Deucus takes the conduit from you and places it against the wall.>\n\nNow that is a good looking decoction conduit. I'm glad I upgraded its strength from that old hunk of junk I had before.\n\nYou might even say Svena did me a favor by destroying that old one." }
WordHunterWoW_QuestEN[42082] = { title = "The Shattered Locus", description = "", objectives = "" }
WordHunterWoW_QuestEN[42083] = { title = "FLAG - Fragile Notice - Phase Controller", description = "", objectives = "" }
WordHunterWoW_QuestEN[42084] = { title = "Selecting a Sixth: Kira", description = "", objectives = "" }
WordHunterWoW_QuestEN[42085] = { title = "Selecting a Sixth: Lulubelle", description = "", objectives = "" }
WordHunterWoW_QuestEN[42086] = { title = "The Feltotem", description = "", objectives = "" }
WordHunterWoW_QuestEN[42087] = { title = "Green Horror", description = "", objectives = "" }
WordHunterWoW_QuestEN[42088] = { title = "Evacuate Snowmane", description = "They just keep coming!\n\nAnd now my scouts report some of the drogbar have managed to sneak around our flank and are attacking Snowmane Village.\n\nGo, help the evacuation. We will hold the line here and try to buy you some time.", objectives = "Evacuate Red Skymane, Tarvim Daywalker, and Old Nefu.", progress = "I knew we should have secured this town better.", completion = "And not a moment too soon. Our scouts report the Underking himself has come." }
WordHunterWoW_QuestEN[42089] = { title = "The Fallen Ones", description = "", objectives = "" }
WordHunterWoW_QuestEN[42090] = { title = "Skittering Subjects", description = "", objectives = "" }
WordHunterWoW_QuestEN[42094] = { title = "Keepers of the Dream", description = "", objectives = "" }
WordHunterWoW_QuestEN[42095] = { title = "Nightmare Dragon", description = "", objectives = "" }
WordHunterWoW_QuestEN[42096] = { title = "Champion: Naralex", description = "", objectives = "I've watched you rise up the ranks for a long time, <name>. With you leading our order, I know we are in good hands.\n\nCount me as one of your champions, Archdruid." }
WordHunterWoW_QuestEN[42097] = { title = "Searching the Archives", description = "The Black Harvest archives contain an immeasurable amount of magical knowledge that has been collected from various sources over time. \n\nIt's reasonable to think that somewhere among the countless scrolls that we'll find something to aid us in our mission to rescue the remaining council members. \n\nThe search may be exhausting, but it is necessary if we plan to rebuild and face the Burning Legion.", objectives = "Interact with the Dreadscar Battle Plans and complete the mission \"Searching the Archives\".", progress = "Have the archives been searched yet?", completion = "Our search of the archives recovered a tome that details the process of creating a demonic gateway. It has the power to access any demon world, assuming we know where to direct it.\n\nWe could use such a gateway to locate and retrieve the remaining council members." }
WordHunterWoW_QuestEN[42098] = { title = "Black Rook Hold: An Unclaimed Soul", description = "In order to create the anchor, we'll need to link something of Shinfel's to an unclaimed soul.\n\nThe soul will act like a beacon, guiding Shinfel through the Twisting Nether, and back to Dreadscar Rift.\n\nShinfel's staff should provide us with the link we need, but the soul will be a bit harder to find. \n\nDwelling within Black Rook hold is an amalgam of souls, some lost and forgotten. Killing this monstrosity should provide us with the soul we need.", objectives = "Collect an Unclaimed Soul from The Amalgam of Souls in the Black Rook Hold dungeon.", progress = "Have you recovered the soul yet?", completion = "You never disappoint, <name>.\n\nThis otherwise forgotten soul will now serve a greater purpose." }
WordHunterWoW_QuestEN[42100] = { title = "Empowering the Soul", description = "Creating the anchor will require more power than our soul shards will be able to provide.\n\nDreadscar's troops are capable of amassing a large amount of soul shards when they defeat enemies while on missions. Once we have enough, I can harvest the supply and use them to craft the anchor.", objectives = "Collect Empowered Soul Shards by completing class hall missions.", progress = "With enough soul shards, we should have the power to create the anchor.", completion = "Your troops have done well. Our soul shard supply is sufficient enough to create the anchor." }
WordHunterWoW_QuestEN[42101] = { title = "Language of the Lost", description = "", objectives = "" }
WordHunterWoW_QuestEN[42102] = { title = "One Who's Worthy", description = "If we wish to successfully summon the sisters, we'll need the help of a warlock who is skilled in summoning greater demons.\n\nWe cannot afford to lose another council member due to inexperience. \n\nThe Broken Isles are swarming with new blood, all hoping to make a name for themselves in this time of chaos. \n\nHopefully among them we can find one worthy of this council.", objectives = "Interact with the Scouting Map and complete the missions, \"One Who's Worthy\".", completion = "Our scouting efforts have hopefully paid off. I have a lead on a <class> who might possess the skills we need to perform the summoning ritual.\n\nWe should follow up as soon as possible." }
WordHunterWoW_QuestEN[42103] = { title = "Let it Feed", description = "We can use the Bloodstone to control the sisters once they are in a weakened state, but first, we'll need to feed it.\n\nThe stone grows in power when consuming the blood of demons. Luckily for us, there's no shortage of demons to kill.", objectives = "Kill demons throughout the Broken Isles and collect their blood.", progress = "We will need to feed the Bloodstone before it will be strong enough to control the eredar sisters.", completion = "This should be more than enough blood to satiate the Bloodstone." }
WordHunterWoW_QuestEN[42104] = { title = "The Underking Comes", description = "Here, I'm too slow to get these laggards to safety. Take my horn and sound the evacuation.\n\nWe need to get the people out of here before the drogbar arrive. The warbraves can take it from there.\n\nFor now just send them over to Spiritwalker Ebonhorn. That fool can watch over them until it is safe.", objectives = "Evacuate Riverbend.", progress = "Well, this is an unexpected pleasure.", completion = "The Underking is coming. Best keep that weapon of yours handy in case this does not go well." }
WordHunterWoW_QuestEN[42105] = { title = "Mixology Mix-up", description = "", objectives = "" }
WordHunterWoW_QuestEN[42106] = { title = "Party Crasher", description = "", objectives = "" }
WordHunterWoW_QuestEN[42107] = { title = "On the Trail of the Great Worm", description = "We need the Gjallarhorn to compel the armies of Odyn's children to join our cause. If the great worm swallowed it, we shall dig through the very earth until we find it in its entrails!", objectives = "Complete the mission \"On the Trail of the Great Worm.\"", completion = "Glory is ours, indeed! The great worm cannot hide from us!" }
WordHunterWoW_QuestEN[42108] = { title = "Rally the Nightwatchers", description = "", objectives = "" }
WordHunterWoW_QuestEN[42110] = { title = "To the Summit!", description = "Your armies have tracked the beast to the highest peak in Highmountain.\n\nIt has nowhere left to run, but it is protected by foul drogbar. You must go there yourself and slay Jorhuttam!", objectives = "Go to Highmountain Summit.", completion = "You're after the great worm? You must be very foolish or very brave\n\nI know these mountains inside and out. Help me avenge my village and I will help you find the foul beast." }
WordHunterWoW_QuestEN[42111] = { title = "Aggressive Reconnaisance", description = "", objectives = "" }
WordHunterWoW_QuestEN[42112] = { title = "The Withered Return", description = "", objectives = "" }
WordHunterWoW_QuestEN[42113] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[42114] = { title = "The Ritual of Tides", description = "Long ago, the first Farseer of the Earthen Ring was given a vision of the elements.\n\nIn the vision she foresaw the arrival of a new Farseer, one who would lead us through a time of terrible crisis and unite the elements.\n\n{name}, I believe that you are the Farseer of this prophecy, called to lead before you were ever born.\n\nThe time has come to fulfill your destiny!\n\nWhen you are ready, we will perform the Ritual of Tides and call upon Neptulon, the first of the four great Elemental Lords.", objectives = "Perform the Ritual of Tides in the Maelstrom.", progress = "The time has come to fulfill your destiny, Farseer <name>.", completion = "I have seen you before, Farseer.\n\n<Lord Neptulon judges you silently for a moment before continuing.>\n\nI sense the potential for great power within you. We shall see if this prophecy holds true..." }
WordHunterWoW_QuestEN[42115] = { title = "Tracking Quest: Chapter 1 Completed", description = "", objectives = "" }
WordHunterWoW_QuestEN[42116] = { title = "Tracking Quest: Chapter 2 Completed", description = "", objectives = "" }
WordHunterWoW_QuestEN[42117] = { title = "Tracking Quest: Chapter 3 Completed", description = "", objectives = "" }
WordHunterWoW_QuestEN[42118] = { title = "Tracking Quest: Chapter 4 Completed", description = "", objectives = "" }
WordHunterWoW_QuestEN[42119] = { title = "A Cleansing Cocktail", description = "", objectives = "" }
WordHunterWoW_QuestEN[42120] = { title = "The Silver Hand", description = "Too many know of its location, the tomb must be closed forever. First, we must reclaim the hammer.\n\nTyrosus has lent us a force to aid in the recovery of the hammer, and some of my order will meet us there as well, but I fear even that may not be enough. I'm glad we'll have you with us.\n\nTake the portal to Dalaran Crater, then fly to Tirisfal Glades and meet us. I've marked the location on your map.", objectives = "Go to Tyr's Fall in Tirisfal Glades and recover the Silver Hand.", progress = "At last it is done.", completion = "I am heartened at your successful quest. We have been waiting for you to return." }
WordHunterWoW_QuestEN[42123] = { title = "Reclaiming Llothien", description = "", objectives = "" }
WordHunterWoW_QuestEN[42124] = { title = "Hags and Hexes", description = "", objectives = "" }
WordHunterWoW_QuestEN[42125] = { title = "Dark Whispers", description = "Felsoul Hold is not far away, but it is well defended. Very tough to get in the normal way, but Calydus can help you sneak in!\n\nThere is a portal that my kind use to haul in treasures, with it you can get in and find the skull!", objectives = "Use Calydus's portal to enter into Felsoul Hold and recover the Skull of the Man'ari.", completion = "Friend was able to get the skull?\n\nYes, Calydus senses it! Keep its gaze turned away from Calydus, friend. I gladly work for you without compulsion." }
WordHunterWoW_QuestEN[42126] = { title = "Archmage Omniara", description = "Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.\n\nThe first task is critical. Archmage Omniara, a renowned summoner, was on her way to the Hall of Guardians when she was attacked.\n\nSend Archmage Kalecgos to help her. He will be uniquely suited to this task.", objectives = "Use the Scouting Map and complete the mission, \"Omniara Needs Help\"", progress = "How is the mission proceeding?", completion = "Your champion did well! Archmage Omniara agreed to join us and is getting situated as we speak." }
WordHunterWoW_QuestEN[42127] = { title = "Building Our Troops", description = "Archmage Omniara is a very powerful arcanist and her skills will be quite an asset to our order.\n\nShe is capable of summoning multiple Water Elementals at the same time! Fortunately, she has agreed to share her knowledge with us.\n\nSpeak to her now, and recruit her elementals.", objectives = "Speak to Archmage Omniara and recruit some of her Water Elementals", progress = "How did the training go?", completion = "Well done. These troops will be invaluable in our fight against the Burning Legion. Deploy them on missions, just as you would with our champions." }
WordHunterWoW_QuestEN[42128] = { title = "Ritual Reagents", description = "The Skull of the Man'ari, oh good choice! It's very powerful and it's held by an even more powerful Dreadlord!\n\nThere is a weakness, the skull has a will of its own! If we can commune with the skull we might be able to convince it to serve you instead!\n\nWe will need reagents from the floating city before we can perform the ritual to commune with it. Dust from a fresh grave, dark oil, and a powerful alcohol catalyst.\n\nOh, and blood! I sense a beast whose blood should be perfect.", objectives = "Search within Dalaran for Grave Dust, a Can of Overheated Oil, an Aged Snowplum Brandy, and a Stag Blood Sample.", progress = "Did you obtain everything, friend?", completion = "Very good! Now, we're ready to begin." }
WordHunterWoW_QuestEN[42129] = { title = "The Pendant of Starlight", description = "To finish my work here, I will need a magical item called the Pendant of Starlight.\n\nFor centuries, the Archdruids of the Dreamgrove passed the pendant down from one guardian to the next. But one day, a naga siren used deception to take it!\n\nThis pendant stores a great amount of arcane power... power I can use to heal the grove.\n\nGet it back, and I will be very grateful!", objectives = "Retrieve the Pendant of Starlight from Abyssal Queen Sha'rathra, who patrols along the coast of Val'sharah.", progress = "Was there much killing?", completion = "Yes, this is it... the pendant of the keepers! Hooray! Vengeance is so fun!" }
WordHunterWoW_QuestEN[42130] = { title = "Building Our Troops", description = "[PH] You can requisition new troops.\n\nGo speak to the trainers of these schools and train our first batch of recruits.", objectives = "Speak to [Recruiter A], [Recruiter B], [Recruiter C] and train new troops." }
WordHunterWoW_QuestEN[42131] = { title = "Unexpected Visitors", description = "Brace yourself, {name}. I am detecting a strange magic forming in the chamber. Something is projecting itself in.", objectives = "Listen to your unexpected visitors.", progress = "Caria and Varedis Felsoul are like a bad copper piece that keeps coming back.", completion = "The two of them are puppets of Kil'jaeden and a bane on our existence. I am glad that you have their warglaives.\n\nThey will be that much easier to kill when we invade their world.\n\nI wonder, do you have a moment to discuss a rather urgent issue?" }
WordHunterWoW_QuestEN[42132] = { title = "Last, But Not Least", description = "I think you already know what I am going to tell you... It is well past time to make Allari and Jace your champions.\n\nThe two of them were instrumental in the planning and preparation for the invasion of Niskara. They have earned it and you would be hard pressed to find better champions anywhere.", objectives = "Recruit Allari the Souleater and Jace Darkweaver as your champions.", completion = "There is just one thing left to do." }
WordHunterWoW_QuestEN[42133] = { title = "Same Day Delivery", description = "I've enchanted these weapons to counter the natural resistances that felhounds have to magic. In addition to that, the metal should splinter their scales on impact, allowing your allies to do increased damage to the demons.\n\nWhile I don't expect the enchantment to decay over time, you should do your best to deliver these weapons to those who will use them immediately. The longer they remain here, the more demons their power will attract.", objectives = "Return to Emmarel Shadewarden at Trueshot Lodge.\n\nProvided item:", completion = "These weapons will work well against Hakkar and his minions. I'll ensure that they are distributed to our allies." }
WordHunterWoW_QuestEN[42134] = { title = "Recruiting More Troops", description = "Our champions acquired the talents of Recruiter Sampson, an extraordinary tracker.\n\nHe has a way with animals, calling them to his side with the utmost ease. In fact, he's already beginning to fill the stables with animals that he has tracked and tamed.\n\nSpeak to him now.", objectives = "Speak to Recruiter Sampson.", completion = "It's my honor to be of service to the Unseen Path. I'll help in any way I can." }
WordHunterWoW_QuestEN[42135] = { title = "Tracking Quest: Chose Strategy C", description = "", objectives = "" }
WordHunterWoW_QuestEN[42136] = { title = "Tracking Quest: Chose Strategy A", description = "", objectives = "" }
WordHunterWoW_QuestEN[42137] = { title = "Champion: Yalia Sagewhisper", description = "", objectives = "Your willingness to help is admirable, and it gives me insight into what kind of leader you will be.\n\nI know you mean to gather priests from all factions and lead them in a battle against the Burning Legion. It's an extraordinary task, but one that you will not have to embark on alone." }
WordHunterWoW_QuestEN[42138] = { title = "Champion: Zabra Hexx", description = "", objectives = "I have a good feelin' about ya, <name>. Dis terrible day really started to turn around when ya showed up.\n\nSome might call it luck, but I think it's fate. We were meant to cross paths.\n\nDis could be da beginnin' a somethin' great." }
WordHunterWoW_QuestEN[42139] = { title = "Rise, Champions", description = "The Uncrowned work behind the scenes, pulling strings here, snipping others there. It's a matter of making the right choices at the right time in the most elegant manner possible.\n\nWe have all decided that you need to recruit some Shadows to send out on our most important missions. People that you can trust, or at least that you can trust to get the job done.\n\nMight I suggest that you start with Garona and Vanessa? It should prove interesting if nothing else considering recent events.", objectives = "Recruit Garona Halforcen and Vanessa VanCleef as your first champions.", completion = "So, I guess I'll be hangin' out with Vanessa here a lot? Don't you worry 'bout nothin'.\n\nShe and I are gonna be besties.\n\nSay, you gotta moment?" }
WordHunterWoW_QuestEN[42140] = { title = "A More Wretched Hive of Scum and Villainy", description = "Word on the street is that you're lookin' to recruit some more, shall we say, unsavory types?\n\nI know just the woman! No, not me... though, I could prolly do it. But not as well as Lonika Stillblade.\n\nYeah, that Lonika. The one who founded the 'School of Roguery' in Shattrath City.\n\nSo, let's send Vanessa there out to Outland and have her make Lonika an offer she can't refuse. Or, you know, give her a legit job and a nicer location for her rogue academy.", objectives = "Use the Scouting Map and complete the mission, \"A More Wretched Hive of Scum and Villainy\".", progress = "So, what'd Lonika say?", completion = "Gold! The rogues, thieves, and cutthroats are gonna start rollin' in.\n\n<Nikki looks over at Vanessa and says in a whisper.>\n\nMaybe we'll even get some unemployed Defias to sign up. Too soon?" }
WordHunterWoW_QuestEN[42141] = { title = "Summoner Morn", description = "Now that we have recruited champions of our order, we can use the Scouting Map to complete vital assignments across the Broken Isles.\n\nThe first assignment is critical. Summoner Morn, a renowned master of the elementals, was on his way to the Heart of Azeroth when he was attacked.\n\nI suggest we send Stormcaller Mylra to help him. She will be uniquely suited to this task.", objectives = "Use the Scouting Map and complete the mission, \"Morn Needs Help\".", progress = "How is the mission proceeding?", completion = "Good, Mylra was successful in her mission! Our recruiting efforts have paid off." }
WordHunterWoW_QuestEN[42142] = { title = "Recruiting The Troops", description = "Our champions acquired the talents of Summoner Morn, a powerful shaman.\n\nHe is known for his strong affinity with earth, and is a valuable addition to our Order. He is already beginning to requisition Lesser Elementals to our cause.\n\nSpeak to him now and train a Lesser Elemental.", objectives = "Speak to Summoner Morn and summon a Lesser Elemental.", progress = "How did the training go?", completion = "Excellent. These troops will be invaluable in our defense of the Broken Isles. Deploy them on missions, just as you would with our champions." }
WordHunterWoW_QuestEN[42143] = { title = "The Champion's Call [WIP]", description = "[PH] Greetings, {class}. Beside me is the Mission Table. From it, you can assign our troops to complete vital assignments across the Broken Isles.\n\nGive it a try now, master. We have received word of a small demon attack on the city of Dalaran. Let us send someone to help repel the enemy.\n\nGaze upon the Mission Table and send a Champion to Dalaran.", objectives = "[PH] Interact with the Mission Table and complete \"The Dalaran Situation.\"" }
WordHunterWoW_QuestEN[42145] = { title = "Out of the Woodwork", description = "", objectives = "" }
WordHunterWoW_QuestEN[42146] = { title = "Dazed and Confused and Adorable", description = "", objectives = "" }
WordHunterWoW_QuestEN[42147] = { title = "First Contact", description = "Time to put your new disguise to the test.\n\nYour first contact is Vanthir, a merchant from the common district. He is in the Grand Promenade today visiting one of his suppliers.\n\nTell Vanthir to pay me a visit regarding a shipment of dusk lily bulbs. He will understand.\n\nBeyond that, we will need time to prepare. You should return to Thalyssra.\n\n<Ly'leth hands you a corked bottle of faintly glowing fluid.>\n\nGive her this, with my regards. We will call upon you soon.", objectives = "Speak with Vanthir in The Grand Promenade.", progress = "Have you made contact with our sympathizers?", completion = "The Lunastre family is well-connected. They will be of great help to us when the time comes." }
WordHunterWoW_QuestEN[42148] = { title = "The Wine's Gone Bad", description = "", objectives = "" }
WordHunterWoW_QuestEN[42149] = { title = "Some Knowledge Shouldn't Be Shared", description = "I noticed that quite a few of the Empyrean Society's books are inscribed with fel magic. That's blasphemous. We must confiscate as many as we can.", objectives = "Collect 5 Empyrean Fel Tomes.", progress = "I hope we've found all of the books.", completion = "You'd better take those back to the Hall of the Guardian for safekeeping, <name>." }
WordHunterWoW_QuestEN[42150] = { title = "Kal'delar Naga Incursion", description = "", objectives = "" }
WordHunterWoW_QuestEN[42151] = { title = "Clear the Skies", description = "", objectives = "" }
WordHunterWoW_QuestEN[42154] = { title = "Help a Whelp", description = "", objectives = "" }
WordHunterWoW_QuestEN[42158] = { title = "The Creator's Workshop", description = "My remote observation relay captured an astonishing amount of data from that tomb.\n\nIf we can download its memory to my core processing systems, I should be able to locate Titanstrike... and that unsavory vrykul who took it.\n\nSince you're here, would you mind helping out? Processing that much information might overload a few failsafe mechanisms here and there, and I know you're the capable sort!", objectives = "Assist Mimiron.", progress = "Remember, anything is science if you write it down!", completion = "The Temple of Storms is close by, so you should get there before that thieving vrykul." }
WordHunterWoW_QuestEN[42159] = { title = "Training with the Nightwatchers", description = "", objectives = "" }
WordHunterWoW_QuestEN[42160] = { title = "Unwelcome Visitors", description = "", objectives = "" }
WordHunterWoW_QuestEN[42165] = { title = "Azsuna Specimens", description = "", objectives = "" }
WordHunterWoW_QuestEN[42166] = { title = "What Is Going On Here?", description = "We don't know much about the Empyrean Society's activities here, but now that you appear to be a new recruit you should be able to ask some questions and take a look around for the strange magic Archmage Vargoth detected. \n\nLet's meet up at the rotunda on the hill.", objectives = "Question 5 Empyrean Society members and investigate their grounds.", progress = "What do you think they are up to?", completion = "They're using fel magic. I knew there was something off about them, but I never suspected this!" }
WordHunterWoW_QuestEN[42167] = { title = "Blood Gather Bit", description = "", objectives = "" }
WordHunterWoW_QuestEN[42168] = { title = "Looking into the Darkness", description = "Friend now is ready to perform the ritual!\n\nRemember, friend, the skull must be convinced that it is in its best interest to be in your possession. If we must force the skull into your servitude, it would be far weaker.", objectives = "Perform the ritual to commune with the Skull of the Man'ari and convince it to tell you its location.", progress = "The ritual circle is ready, friend.", completion = "Yes, Felsoul Hold! Calydus knows where that is!\n\nCalydus can make a path that connects to one of the portals there!" }
WordHunterWoW_QuestEN[42169] = { title = "Left for Dead", description = "", objectives = "" }
WordHunterWoW_QuestEN[42170] = { title = "The Dreamweavers", description = "Assist the Druids of Val'sharah by completing 4 world quests.", objectives = "Complete any 4 world quests in Val'sharah.", completion = "The Dreamweavers thank you." }
WordHunterWoW_QuestEN[42171] = { title = "Final Exit", description = "We've certainly reduced the Empyrean Society's numbers. I don't think they'll be luring any more members to their cause for a while. \n\nThere's only one place we haven't investigated, and I suspect that rune we found is attuned to the door. Let's see what's inside the building.", objectives = "Use the Rune of Opening to unlock the Empyrean Society building door.", progress = "I thought I'd snoop around a bit before I met you at the rotunda. Unfortunately my invisibility spell wore off at an inopportune time. I'm glad you found me! What is this you have found, <name>?", completion = "Thank you for uncovering the truth about the Empyrean Society, <name>!" }
WordHunterWoW_QuestEN[42172] = { title = "Leyhollow Infestation", description = "", objectives = "" }
WordHunterWoW_QuestEN[42173] = { title = "Electrosnack", description = "", objectives = "" }
WordHunterWoW_QuestEN[42174] = { title = "Champions of Elune", description = "", objectives = "" }
WordHunterWoW_QuestEN[42175] = { title = "Growing Power", description = "The Tirisgarde has need of your help now that you have grown in strength, {name}. Meet me in the Hall of the Guardian when you are done with your adventures.", objectives = "Meet Meryl Felstorm in the Hall of the Guardian.", completion = "Good to see you here, <name>. There is much to be done!" }
WordHunterWoW_QuestEN[42176] = { title = "Rise of Skovald", description = "", objectives = "" }
WordHunterWoW_QuestEN[42177] = { title = "Reclaiming Morheim", description = "", objectives = "" }
WordHunterWoW_QuestEN[42178] = { title = "Shock Absorber", description = "", objectives = "" }
WordHunterWoW_QuestEN[42182] = { title = "To Battle!", description = "", objectives = "" }
WordHunterWoW_QuestEN[42183] = { title = "To Battle!", description = "", objectives = "" }
WordHunterWoW_QuestEN[42184] = { title = "Mission: Elemental Diplomacy", description = "The Lord of Tides has united with the Earthen Ring, but the matter of uniting the remaining Elemental Lords still remains.\n\nFor the next step of our campaign, I have organized a diplomatic mission to Skywall.\n\nThe goal of the mission is to ascertain the current political situation in Skywall, following the defeat of Al'Akir the Windlord, and to identify any elementals who would aid our cause.\n\nThe mission is currently waiting your assignment.", objectives = "Successfully complete the \"Elemental Diplomacy\" mission.", completion = "The Earthen Ring champions sent to Skywall have successfully returned to the class hall.\n\nThe plane of air is currently in a state of turmoil, however our champions identified a powerful elemental who may be willing to aid our cause." }
WordHunterWoW_QuestEN[42185] = { title = "Never Hunt Alone", description = "Prustaga is almost certainly on her way to the Temple of Storms, which is where I imbued Titanstrike with the Thunderspark.\n\nIf my deductions are correct, she'll attempt to reverse the process and infuse the spark into herself, thus attaining the godlike power she craves!\n\nHopefully Thorim isn't off cavorting with his hounds again. If Prustaga has the local vrykul on her side, things may get... complicated.", objectives = "Seek out Thorim at the Temple of Storms and recover Titanstrike.", completion = "Brann will hardly believe his ears when I tell him what happened. What an adventure!" }
WordHunterWoW_QuestEN[42186] = { title = "Growing Power", description = "Iron-Body Ponshu has requested your presence.\n\nOur campaign to defend the Broken Isles is getting under way, and we need you back at the Wandering Isle.", objectives = "Speak to Iron-Body Ponshu at the Wandering Isle.", completion = "Thank you for coming, Grandmaster." }
WordHunterWoW_QuestEN[42187] = { title = "Rise, Champions", description = "We are still recovering from the attack at the Peak of Serenity.\n\nTo help us rebuild the order, we should enlist the greatest champions of our class to fight by our side.\n\nI know that the two Stormstouts, Chen and Li Li, would eagerly pledge to join the cause. Speak to them and recruit them as champions, then speak to Master Hsu.", objectives = "Enlist Chen Stormstout and Li Li Stormstout, then speak to Master Hsu.", completion = "Chen and Li Li are two of the greatest monks in recent history.\n\nAs long as they stay out of trouble, they will be great representatives of our order." }
WordHunterWoW_QuestEN[42188] = { title = "Nobundo Awaits", description = "Nobundo and the other champions of the Earthen Ring have gathered down below. They are awaiting your arrival, Farseer.\n\nA great ritual is about to take place and they have requested your presence. Do not worry about your administrative duties for now, I'll take care of things here.\n\nNobundo is waiting for you now. May the elements be with you, Farseer.", objectives = "Speak with Nobundo in the Heart of Azeroth.", completion = "I hear you have been making good progress down among the Broken Isles. Good. We, too, have been busy here at the Maelstrom.\n\nThere are important matters that await us..." }
WordHunterWoW_QuestEN[42189] = { title = "Fire Mage - Flavor Event 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[42190] = { title = "Wildlife Conservationist", description = "", objectives = "" }
WordHunterWoW_QuestEN[42191] = { title = "Tech It Up A Notch", description = "Thanks to you, the Order of the Broken Temple is gradually re-assembling.\n\nHowever, there is much more work to do. As our leader, you can determine the trajectory of our order's future.\n\nSpeak to Number Nine Jia. She will show you the ropes.", objectives = "Speak to Number Nine Jia.", completion = "Excellent work, <name>! I can see that the Order of the Broken Temple is in good hands." }
WordHunterWoW_QuestEN[42192] = { title = "Fire Mage - Flavor Event 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[42193] = { title = "The Gjallarhorn", description = "You have proven yourself most thoroughly time and again, {name}. There can be no doubt that you are the one to lead Odyn's armies into the final battle.\n\nYou must first obtain the Gjallarhorn so that you may signal to our allies that the end times are upon us.\n\nKing Svergan Stormcloak was the last known living guardian of the horn.\n\nSeek his spirit in the Field of Fallen Kings in Stormheim and see what you can learn.", objectives = "Find Svergan Stormcloak.", completion = "What is it you seek? Are you here to pilfer heirlooms like the others?" }
WordHunterWoW_QuestEN[42194] = { title = "Stolen Honor", description = "Safeguarding the Gjallarhorn was my duty, {race}. I will do what is right, but first I must ask for your aid.\n\nMy family was disavowed by the mystics of our time and this grave was ransacked.\n\nI cannot find peace while my family heirlooms are in the hands of the servants of the false God-King.\n\nReturn them to me and I will aid you in finding the Gjallarhorn!", objectives = "Svergan Stormcloak wants you to obtain the Crown of the Forgotten King, the Stormcloak Signet and the Drakerider's Medallion in the Runewood.", progress = "Do you bring back my family's heirlooms, <race>?", completion = "Odyn truly guides your hand, <name>." }
WordHunterWoW_QuestEN[42197] = { title = "Champion: Duke Hydraxis", description = "", objectives = "Lord Neptulon has sent me to aid the Earthen Ring in the defense of Azeroth.\n\nI have been commanded to serve the Farseer of the Earthen Ring with the same loyalty I give to the Lord of Tides. I will fulfill this duty until the Burning Legion is driven from this world and the future of Azeroth is secured.\n\nI am yours to command, Farseer." }
WordHunterWoW_QuestEN[42198] = { title = "Champion: Stormcaller Mylra", description = "", objectives = "Uniting the elements won't be easy, Farseer <name>. You'll be needin' all the help you can get!\n\nAye, These are dark times indeed... but we'll face 'em t'gether, don't you worry.\n\nOl' Mylra has yer back, Farseer.\n\nNow, let's get a move on then! There ain't no time to waste!" }
WordHunterWoW_QuestEN[42200] = { title = "Mission: Investigating Deepholm", description = "In order for the Earthen Ring to bring the four Elemental Lords together in an alliance against the Burning Legion, we will need to convince Therazane the Stonemother to join forces with us.\n\nTherazane has been absent from our negotiations with the elements thus far.\n\nThere have been whispers of a new threat arising from within Deepholm. If these rumors are true, she may have need of our aid.\n\nI have prepared a diplomatic mission to Deepholm to ascertain the situation. It is awaiting your assignment.", objectives = "Successfully complete the \"Investigating Deepholm\" mission.", completion = "The mission to Deepholm was a success. The champions of the Earthen Ring made contact with Therazane, but the situation there is worse than we feared..." }
WordHunterWoW_QuestEN[42202] = { title = "Revenge, Served Cold", description = "My village was razed by a drogbar tribe who worships the very beast you seek. No one was spared.\n\nHelp me avenge my people and I will aid you in your quest to find Jorhuttam.", objectives = "Slay Dogrub the Cruel, Urgrul Skullcleaver and 8 Frostcrag Drogbar in Highmountain Summit.", progress = "You return.", completion = "You have my thanks, <name>." }
WordHunterWoW_QuestEN[42203] = { title = "Ritual Bit", description = "", objectives = "" }
WordHunterWoW_QuestEN[42204] = { title = "Jorhuttam", description = "You upheld your end of your promise. I will do the same.\n\nTake these drogbar drums. Then bang on them to call upon Jorhuttam to feast.\n\nFind the Great Worm's feeding mound and use the drums to lure her out.", objectives = "Use the Frostcrag Drums near Jorhuttam's Feeding Mound and slay Jorhuttam to obtain the Gjallarhorn.", progress = "The Gjallerhorn, <name>.  Is it finally in your possession?", completion = "It is done! The armies of Ulduar are bound by oath to join us now that we're in possession of the Gjallerhorn!" }
WordHunterWoW_QuestEN[42205] = { title = "Entrance Bit", description = "", objectives = "" }
WordHunterWoW_QuestEN[42206] = { title = "The Next Level Has Arrived", description = "The Empyrean Society is certainly much more dangerous than they appear. It's unimaginable that any mage would study fel magic -- that's for warlocks and the Legion!\n\nSince our friend, Ravandwyr, appears to be delayed, it looks like we'll have to deal with this ourselves. We should remove this sect so they can't corrupt anyone else.", objectives = "Kill 10 Empyrean Society members.", progress = "Do you think we've reduced their numbers enough?", completion = "I like you, <name>. You don't hesitate to take action when necessary!" }
WordHunterWoW_QuestEN[42208] = { title = "Return to the Firelands", description = "The time has come to return to the Firelands. I need not tell you how dangerous this will be, Farseer.\n\nRagnaros may be defeated, but the elementals of the Firelands destroy with reckless abandon. Our presence there will surely be seen as an act of aggression.\n\nI have prepared a scouting mission to the Firelands. We should send only our very best champions to make contact with the elements there.\n\nIf the mission is successful, we may find the information we need to bring the Firelands into our fold.", objectives = "Complete the \"Return to the Firelands\" missions.", completion = "It seems that our mission to the Firelands was a success, Farseer. We have much to discuss." }
WordHunterWoW_QuestEN[42209] = { title = "Freeing the Taken", description = "", objectives = "" }
WordHunterWoW_QuestEN[42210] = { title = "Scrolls of Knowledge", description = "Our troops are ready! It's time to test them out in the field, and I have the perfect assignment.\n\nNumber Nine Jia is a well-respected scholar. She has knowledge that can help us improve the order, however, many  of her important scrolls were left behind during the attack on the Peak of Serenity.\n\nSend our champions to retrieve these documents at once!", objectives = "Complete the mission, \"Scrolls of Knowledge.\"", progress = "How did it go?", completion = "It was very lucky that we were able to retrieve those scrolls. Number Nine Jia's help will be invaluable to our order." }
WordHunterWoW_QuestEN[42211] = { title = "Leodrath's Kin", description = "", objectives = "" }
WordHunterWoW_QuestEN[42212] = { title = "Fire Mage - Flavor Event 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[42213] = { title = "Eye of Azshara: The Tidestone of Golganneth", description = "<Now that you have defeated Queen Azshara's Wrath and have the Tidestone in hand, it is time to place it in the Portrait Room of the Chamber of the Guardian in lower Dalaran.>", objectives = "Use the central teleporter in Dalaran and then place the Tidestone of Golganneth in the Portrait Room of the Chamber of the Guardian.", completion = "<Archmage Khadgar has set aside a space here for the Tidestone of Golganneth, as well as the rest of the Pillars of Creation.>" }
WordHunterWoW_QuestEN[42214] = { title = "Knocked for a Loop", description = "While you're focused on murlocs...\n\nMany murlocs are known to wear jewelry to attract a mate. I'm willing to bet that we can use some of the same jewels they use.\n\nCollect some of their jewelry and bring it back to me. The wetter, the better!", objectives = "Collect 10 Salteye Bangles.", progress = "I could see how jewelry on a murloc might make it seem more attractive...", completion = "Oh yes! There are some fine looking jewels here. Let's just scratch the goop off, and..." }
WordHunterWoW_QuestEN[42215] = { title = "DEPRECATED: Singed Letter", description = "I pray this letter makes it into the right hands. Knowing my luck, it'll probably wind up in the stomach of some creature.\n\nIf you're reading this, then please bring something to treat my burns. They really hurt. A lot.You will receive:", objectives = "Bring 3 Silvery Salves and 1 Field Pack to the location marked on your map. Treat the Felburned Scout when you arrive." }
WordHunterWoW_QuestEN[42220] = { title = "Shipwrecked Sailors", description = "<The gilblin and makrura of Mak'rana have captured the forsaken sailors from the nearby shipwreck.>\n\n<It looks like the sailors are being poisoned and worse. Best to put them out of their misery.>", objectives = "Put 10 Queen's Reprisal Sailors out of their misery." }
WordHunterWoW_QuestEN[42221] = { title = "Chief Bitterbrine", description = "", objectives = "" }
WordHunterWoW_QuestEN[42222] = { title = "Empyrean Society Report", description = "I find it hard to believe that Archmage Vargoth would be involved with such a malevolent group! There must be a good explanation for why he's been here... \n\nRegardless, we had best return to the Hall of the Guardian and inform Meryl about what we've uncovered here.", objectives = "Return to the Hall of the Guardian.", completion = "Ravandwyr speaks very highly of how you dealt with the Empyrean Society, <name>." }
WordHunterWoW_QuestEN[42223] = { title = "Scouting the Crimson Thicket", description = "If you are heading east, there is something I would ask of you.\n\nWhile we struck camp some of our caravan left to scout around the city. Lilryia Dawnwind has been gone too long.\n\nI would be most grateful if you would go check on her safety. She said she was going to scout out the ruins of Dawncleft.", objectives = "Find Lilryia Dawnwind in Dawncleft.", completion = "You could not have arrived at a better time, <race>." }
WordHunterWoW_QuestEN[42224] = { title = "Cloaked in Moonshade", description = "I do not know what Theryn found, but I know where he found it. \n\nMoonshade Sanctum, to the west. Beyond the Temple of Fal'adora. \n\nWhatever power altered Theryn's arcane essence... Whatever power allowed Kel'danath to create a spell to soothe the withered... Its source rests there. \n\nI know this as surely as if I had been there myself.", objectives = "Explore Moonshade Sanctum.", completion = "<You recognize the relic from Thalyssra's vision.>" }
WordHunterWoW_QuestEN[42225] = { title = "Breaking the Seal", description = "<As you behold the relic, Thalyssra's voice echoes in your mind.>\n\nYou found it! But it is sealed away tight.\n\nSearch the room for a way to break those seals.", objectives = "Break the Seal of the Tides, Seal of the Earth and Seal of the Sky.", completion = "<As the magical barrier begins to fade, you hear the rustling of leaves and the clattering of mandibles just outside.>" }
WordHunterWoW_QuestEN[42226] = { title = "Moonshade Holdout", description = "<Tampering with the relic has drawn the attention of some hideous creatures from beneath Falanaar.>", objectives = "Slay a Fal'dorei Webslinger, a Fal'dorei Broodcaller, and a Fal'dorei Widowmaker.", completion = "Do you have any idea what you have done?!" }
WordHunterWoW_QuestEN[42227] = { title = "Into the Crevasse", description = "I have protected that seed for ten thousand years. You let it fall into the hands of the fal'dorei.\n\nI should have let you die.\n\nRepay your debt. Help me get the seed back.", objectives = "Follow Valewalker Farodin into the Falanaar Tunnels.", completion = "We must move swiftly." }
WordHunterWoW_QuestEN[42228] = { title = "The Hidden City", description = "Orathiss has underestimated the seed. It is sapping her power - slowing her down.\n\nWe must catch her and get the seed to safety!", objectives = "Follow Orathiss through Falanaar Tunnels and slay her.", completion = "<Energy pulses around the ancient seed.>" }
WordHunterWoW_QuestEN[42229] = { title = "Shal'Aran", description = "The chamber beyond may be the perfect hiding place, now that its guardian has been dealt with.\n\nCome with me.", objectives = "Follow Thalyssra while she explores Shal'Aran.", completion = "Such a temporary home will serve us well." }
WordHunterWoW_QuestEN[42230] = { title = "The Valewalker's Burden", description = "The seed is awakening. Without power it will quickly wither and die.\n\nWe must carry the seed out of here and plant it somewhere safe.\n\nI am not strong enough to bear this burden. But you... you are brimming with power. I can sense it. \n\nPlease take the seed.", objectives = "Activate the Fal'adora Beacon in Temple of Fal'adora.", completion = "<The seed sits perfectly atop the stand and sinks in with a satisfying click.>" }
WordHunterWoW_QuestEN[42231] = { title = "The Mysterious Paladin", description = "It appears we have been afforded a unique opportunity.\n\nA small order of paladins has come forward claiming to know the location of Tyr's tomb. They say they are the protectors of his warhammer, but that the ancient weapon is now imperiled.\n\nI'd like you to speak with Travard, their leader, to find out more about this artifact.", objectives = "Speak with Travard in Dalaran.", completion = "My order guards a powerful secret. We are the keepers of the final resting place of the mighty Tyr!\n\nRecent intrusions have proven his tomb's location to be a secret no longer. We must protect the sacred relic stored there... the Silver Hand!" }
WordHunterWoW_QuestEN[42233] = { title = "Highmountain Tribes", description = "Assist the Tauren of Highmountain by completing 4 world quests.", objectives = "Complete any 4 world quests in Highmountain.", completion = "The Highmountain tribes thank you." }
WordHunterWoW_QuestEN[42234] = { title = "The Valarjar", description = "Assist the Vry'kul of Stormheim by completing 4 world quests.", objectives = "Complete any 4 world quests in Stormheim.", completion = "The valarjar thank you." }
WordHunterWoW_QuestEN[42235] = { title = "Invasion: Westfall", description = "", objectives = "" }
WordHunterWoW_QuestEN[42236] = { title = "Invasion: Northern Barrens", description = "", objectives = "Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[42237] = { title = "Invasion: Tanaris", description = "", objectives = "" }
WordHunterWoW_QuestEN[42238] = { title = "Missing Demon", description = "I seem to have misplaced my imp, Daglop.\n\nIf you see him, tell him to check in.\n\nNormally I would just resummon him but I'm worried blind Marius here will kill him first and ask questions later.\n\nNo vision, that one.", objectives = "Find Daglop in Azsuna.", completion = "Yeah yeah, the new master sent you. I get it. I have to deal with my former master first." }
WordHunterWoW_QuestEN[42239] = { title = "Halls of Valor: The Bear King", description = "", objectives = "" }
WordHunterWoW_QuestEN[42240] = { title = "Halls of Valor: Ponderous Poaching", description = "", objectives = "" }
WordHunterWoW_QuestEN[42241] = { title = "Halls of Valor: A Worthy Challenge", description = "", objectives = "" }
WordHunterWoW_QuestEN[42242] = { title = "Halls of Valor: A Gift for Vethir", description = "", objectives = "" }
WordHunterWoW_QuestEN[42243] = { title = "Halls of Valor: Deeds of the Past", description = "", objectives = "" }
WordHunterWoW_QuestEN[42244] = { title = "Fate of the Queen's Reprisal", description = "<This is the kind of intelligence that should be shared. Perhaps someone at the Windrunner's Sanctuary on Dalaran will know what to do with it.>", objectives = "Take the Captain's Log to Advisor Stillwater at the Windrunner's Sanctuary on Dalaran.\n\nProvided item:", completion = "<The advisor looks down at what you're offering her and then looks around nervously, straining to give you a rictus grin. She continues in hushed tones.>\n\nDo you know what you have here? You have kept the Alliance from getting their grubby little hands on some rather delicate information.\n\nI will see to it personally that this is safely filed away." }
WordHunterWoW_QuestEN[42245] = { title = "DEPRECATED: Singed Note", description = "Please, if you're reading this then there still may be time. I was badly burned fighting the Legion.\n\nI've included a rough sketch of where I am relative to the Crumbled Palace.\n\nPlease hurry, and bring supplies.You will receive:", objectives = "Bring 3 Silvery Salves and 1 Field Pack to the location marked on your map. Treat the Felburned Scout when you arrive." }
WordHunterWoW_QuestEN[42250] = { title = "DEPRECATED: Fevered Plea", description = "I can't take this exhaustion any longer. And the heat of this place is making me see things.\n\nPlease, if someone finds this message, look for me. And bring medicine for Light's sake.\n\nI think I see Deathwing coming...\n\n<The ink on the last letter falls down to the bottom of the note.>You will receive:", objectives = "Bring 3 Field Packs to the location marked on your map. Treat the Fevered Explorer when you arrive." }
WordHunterWoW_QuestEN[42255] = { title = "DEPRECATED: Bloody Note", description = "I'm not sure how much longer I can keep pressure on this wound.\n\nIf you find this note, please bring bandages. Lots and lots of bandages.You will receive:", objectives = "Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Soldier when you arrive." }
WordHunterWoW_QuestEN[42268] = { title = "Shipwrecked Sailors", description = "<The gilblin and makrura of Mak'rana have captured the forsaken sailors from the nearby shipwreck.>\n\n<The sailors are being treated very poorly. It looks like a rescue operation is in order.>", objectives = "Rescue 10 Queen's Reprisal Sailors." }
WordHunterWoW_QuestEN[42269] = { title = "The Soultakers", description = "", objectives = "" }
WordHunterWoW_QuestEN[42270] = { title = "Scourge of the Skies", description = "", objectives = "" }
WordHunterWoW_QuestEN[42271] = { title = "Their Dying Breaths", description = "I have precious little time. As we speak, my troops are defending against an onslaught of withered elves.\n\nThese four whelplings are near death. Their lives are of the utmost importance to our flight, as they may be some of the last whelplings Senegos can rear.\n\nSome cracked ley crystals should bring them back to their senses.", objectives = "Obtain 4 Cracked Ley Crystals, then use them to resuscitate the Mana-Drained Whelplings.", progress = "Oh no...", completion = "Of course they would attack now.\n\nThose withered devils couldn't have chosen a more effective time to strike. My brood already suffers." }
