WordHunterWoW_QuestEN[42303] = { title = "DEPRECATED: Fevered Note", description = "I didn't realize that a harpy's kiss was actually poisonous. Damn vixen tricked me.\n\nI know I'm not supposed to kiss and tell, but if I don't get well soon, I fear this may be my end.\n\nIf someone finds this letter, please bring medical supplies and treat my sickness.You will receive:", objectives = "Bring 3 Field Packs to the location marked on your map. Treat the Fevered Explorer when you arrive." }
WordHunterWoW_QuestEN[42308] = { title = "DEPRECATED: Bloody Plea", description = "I hope I survive this long enough to tell the tale of when I was mauled by a bear.\n\nBut unless this letter finds its way into the proper hands, I may not have long to live.\n\nI'm in desperate need of bandages. Please bring any you can spare.You will receive:", objectives = "Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Soldier when you arrive." }
WordHunterWoW_QuestEN[42309] = { title = "DEPRECATED: Bloody Request", description = "What can I tell ya, I'm satyr hater. Those cursed beasts slashed me up pretty good when I was trying to rescue my comrades in the Sleeper's Barrow. \n\nTo whomever finds this letter, make your way over to the barrow. You'll find me in there, hopefully still alive.\n\n-Satyr HaterYou will receive:", objectives = "Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Soldier when you arrive." }
WordHunterWoW_QuestEN[42323] = { title = "DEPRECATED: Fevered Letter", description = "I'm stuck up on this wretched mountain, freezing to death and to boot I most definitely have the flu.\n\nIt's nice to be in such a cold climate with a fever, but if it doesn't break I'm afraid I may be done for.\n\nTo whomever is reading this, please bring medical supplies.You will receive:", objectives = "Bring 3 Field Packs to the location marked on your map. Treat the Fevered Explorer when you arrive." }
WordHunterWoW_QuestEN[42328] = { title = "Tracking Quest: Lumenstone 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[42329] = { title = "Tracking Quest: Lumenstone 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[42330] = { title = "Tracking Quest: Lumenstone 3", description = "", objectives = "" }
