WordHunterWoW_QuestEN[42332] = { title = "Tracking Quest: Lumenstone 5", description = "", objectives = "" }
WordHunterWoW_QuestEN[42333] = { title = "DEPRECATED: Crumpled Letter", description = "Need medical attention. Arm broken. Probably leg too. Light-forsaken drogbar!\n\nYou'll find me at the base of a large mountain in Highmountain. I'm sure that narrows it down.You will receive:", objectives = "Bring 2 Silkweave Splints and 1 Field Pack to the location marked on your map. Treat the Injured Adventurer when you arrive." }
WordHunterWoW_QuestEN[42334] = { title = "DEPRECATED: Crumpled Note", description = "I'm not sure how, but we managed to survive being dropped off the mountain by harpies.\n\nWe're in bad shape though. Please, if someone finds this note, bring help.You will receive:", objectives = "Bring 10 Silkweave Splints and 5 Field Packs to the location marked on your map. Treat the Injured Adventurers when you arrive." }
WordHunterWoW_QuestEN[42338] = { title = "Azsuna - Treasure 040 - Lothien 03 - Small", description = "", objectives = "" }
WordHunterWoW_QuestEN[42339] = { title = "Azsuna - Treasure 041 - Mountain Top", description = "", objectives = "" }
WordHunterWoW_QuestEN[42340] = { title = "DEPRECATED: Singed Plea", description = "We just barely managed to escape, but not before they rained hell upon us with their demon fire.\n\nI suppose they assumed we'd be consumed by their fire, but we survived.\n\nIf you find this note, bring medical supplies to soothe our burns. Maybe then we can survive a bit longer.You will receive:", objectives = "Bring 9 Silvery Salves and 3 Field Packs to the location marked on your map. Treat the Felsoul Hold Escapees when you arrive." }
WordHunterWoW_QuestEN[42345] = { title = "DEPRECATED: Fevered Prayer", description = "Dear gods whose names I really can't recall, please answer my prayer and send help.\n\nOur party was attacked by satyrs and now we're feverishly sick and could use some aid immediately.\n\nI believe writing this note is the correct way of summoning a god...You will receive:", objectives = "Bring 15 Field Packs to the location marked on your map. Treat the Fevered Val'sharah Refugees when you arrive." }
WordHunterWoW_QuestEN[42350] = { title = "DEPRECATED: Bloody Letter", description = "I know cats can climb trees, so I'm pretty convinced that this nightsaber is just waiting for me to bleed out.\n\nI'm attaching this note to a nearby owl I've nicknamed \"Hooty\". Hopefully he finds someone to help me.You will receive:", objectives = "Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Kirin Tor Guardian when you arrive." }
WordHunterWoW_QuestEN[42351] = { title = "DEPRECATED: Bloody Prayer", description = "This is my last will and testament. To my husband, I leave the kids, the house, and the enormous wealth I've accumulated... wait, no. To my sister, I leave the kids, the house and my estate.\n\nTo my husband, I leave my eternal love. Yes, he'll enjoy having that more.\n\nAlso, if someone finds this and can come find me before I bleed out, I'd appreciate some medical attention.You will receive:", objectives = "Bring 3 Silkweave Bandages and 1 Field Pack to the location marked on your map. Treat the Gravely Wounded Moonfall Defender when you arrive." }
