WordHunterWoW_QuestEN[42476] = { title = "The Deadwind Site", description = "Your research spoke of an experimental site out near Karazhan. I hope there are still materials on this ritual that will aid us there.\n\nYou will need to find the site and bring back anything that will help us recreate the ritual. I will dig deeper here as well.", objectives = "Find and retrieve information on the ritual from Arrexis's campsite near Karazhan.", progress = "I trust you were successful?", completion = "This is better than I hoped. A working ward prototype and the ritual notes as well!\n\nI'm beginning to believe this is possible!" }
WordHunterWoW_QuestEN[42477] = { title = "Daio the Decrepit", description = "That text lists someone named Daio as being instrumental to the demonic ritual. They can't possibly mean Daio the Decrepit!\n\nI never knew he was Kirin Tor. I only know him as an elderly warlock who trains young recruits in the infernal arts. This would certainly explain his change of occupation.\n\nHe most likely holds key information for this to work. Though retired, I believe he is still out in the Tainted Scar in the Blasted Lands. You should seek him out.", objectives = "Fly to the Tainted Scar in the Blasted Lands and get information from Daio the Decrepit.", progress = "Well, what did Daio have to say?", completion = "Our order suffered a great loss that day. It is a shame we chose to hide it instead of study it.\n\nYou have another critical element to the ritual, and we are one step closer." }
WordHunterWoW_QuestEN[42479] = { title = "The Mage Hunter", description = "And with that, we have what we need to recreate the ritual... however flawed it may be. It must be conducted somewhere highly visible so that word reaches our target swiftly.\n\nI've heard reports that the Legion is heavily invested in the Faronaar region of Azsuna. An excellent place to begin a ritual they won't want us to complete.\n\nThe chances of us dying horribly are exceptionally high.", objectives = "Recreate Arrexis' ritual in Faronaar and defeat Balaadur.", progress = "Do you have it?", completion = "Your ability continues to astound me! Balaadur lies dead in his own realm, and you now wield Ebonchill. I look forward to seeing what you will do next." }
WordHunterWoW_QuestEN[42480] = { title = "Assn Rogue - Flavor Event 02 (Alliance)", description = "", objectives = "" }
WordHunterWoW_QuestEN[42481] = { title = "Ritual of Doom", description = "", objectives = "" }
WordHunterWoW_QuestEN[42482] = { title = "Assn Rogue - Flavor Event 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[42483] = { title = "Put It All on Red", description = "All right, I've got one last beasty to send you after. He's a bit far out, but trust me, it'll be worth it. This one I put a huge wager on!\n\nAlong the eastern coast swims a great shark the locals call Steelscale. They say his hide is near impenetrable.\n\nBut you're gonna prove them wrong, aren't ya chum? Bring me his fin, and those tauren will have to fork over a princely sum.", objectives = "Collect Steelscale's Fin from Steelscale in Citrine Bay.", progress = "Hmm...", completion = "<A note from the goblins is left behind, along with an old magnifying glass>\n\nI wish I coulda been there to see the look on your face, but Raz and I got bigger fish to fry!\n\nThanks for the trophies and meat. I'm sure they'll fetch a nice sum on the black market, along with all the goodies we got from those stupid tauren! I'm sure they won't be needing them any more!\n\nSo long sucker!" }
WordHunterWoW_QuestEN[42484] = { title = "The Firstborn Rises", description = "General Nazgrim was one of the finest warriors our world has known, and his loyalty was unsurpassed... even for an orc.\n\nHe deserves the peace of death, but this world cries out to be saved. The time for rest is over...\n\nCome, Deathlord... let us welcome Nazgrim into the arms of the damned.", objectives = "Raise Nazgrim as a Death Knight.", progress = "General Nazgrim will make a fine <class>.", completion = "Well done, Deathlord. One of the Horde's greatest generals in life now serves you in undeath as your first horseman!" }
WordHunterWoW_QuestEN[42485] = { title = "REUSE ME", description = "", objectives = "" }
WordHunterWoW_QuestEN[42486] = { title = "Little One Lost", description = "I'm ready to go home now, but there are still scary men outside...\n\nWill you stay with me? Make sure they don't take me away?\n\nI don't want to go back in the cage...", objectives = "Escort Korine back to her mother Verene at the Waning Crescent.", completion = "Oh my sweet little Korine! Thank you, thank you!" }
WordHunterWoW_QuestEN[42487] = { title = "Friends On the Outside", description = "You have done well for us here, but it is time for you to return to Thalyssra.\n\nThere is a teleporter pad nearby that has gone unused in recent years. See if you can reroute it and return to her that way.\n\nOh, and before you go:\n\n<Vanthir hands you a wrapped bottle of Arcwine.>\n\nTake this to her, with my thanks for sending you. Let her know that your efforts helped replenish our Arcwine supplies and reunited a mother and child.\n\nWe are grateful beyond measure. Farewell for now.", objectives = "Activate the teleporter pad and bring Vanthir's gift to Thalyssra.", progress = "A gift? For me?", completion = "Vanthir is a very pleasant fellow." }
WordHunterWoW_QuestEN[42488] = { title = "Thalyssra's Abode", description = "While you were busy in the city I reached a roadblock in my withered research. \n\nI feel I am close to overcoming this barrier, but I'm afraid I cannot do so without some more advanced tools.\n\nI hid among my possessions an item called an Arcane Amplifier. It does precisely what its name entails.\n\nIt is more than likely that the Magistrix ordered my estate dismantled. If the Amplifier remains, it will be in fragments.\n\nRecover the whole, if you can.", objectives = "Search Thalyssra's estate and collect 3 Amplifier Fragments. Combine them into an Arcane Amplifier.", progress = "Did you find it?", completion = "How lucky we are that it could be recovered... thank you." }
WordHunterWoW_QuestEN[42489] = { title = "Thalyssra's Drawers", description = "Thalyssra's ransacked estate still contains a number of items important to Thalyssra. Collect them and return them to her.", objectives = "Search Thalyssra's estate and collect her belongings.", progress = "What did you find?", completion = "This is a comfort beyond words." }
WordHunterWoW_QuestEN[42490] = { title = "The Arcway: Opening the Arcway", description = "Deep beneath Suramar is a defunct set of tunnels known as the Arcway. They were abandoned when a disaster disrupted the mana collectors operating there. \n\nI know not what awaits you down there, but I do know one thing.\n\nWe are not the only ones interested in this place. Make enough noise and one of the advisors with whom I served under Elisande is sure to appear.\n\nHis name is Vandros. Slay him, if you can.\n\nHis death will be our victory, as we deprive Elisande of one more weapon in her arsenal.", objectives = "Slay Advisor Vandros in the Arcway.", progress = "Is it done?", completion = "Thank you. It is one thing I no longer need to think about." }
WordHunterWoW_QuestEN[42491] = { title = "The Arcway: Long Buried Knowledge", description = "Beneath Suramar City is an ancient network of tunnels known as the Arcway.\n\nThey were abandoned some time ago as part of the cavern became unstable. Since then, who knows?\n\nRegardless of what is currently down there, I believe you will find something essential to our continued success.\n\nLong ago my people took a thorough survey of the ley lines in and around Suramar. This they would have stored in the library in the Arcway. \n\nFind this map for me.", objectives = "Acquire the Suramar Leyline Map from the Arcway.", progress = "Did you find it?", completion = "Excellent! I will study this immediately." }
WordHunterWoW_QuestEN[42492] = { title = "PH: Withered Scenario", description = "PH", objectives = "PHPH" }
WordHunterWoW_QuestEN[42493] = { title = "Impending Dooooooom!", description = "Millhouse attracts trouble, so he's sure to find Archmage Vargoth if he's still here. \n\nOh and if you do find the Nightborne Soulstone, best get it first!", objectives = "Investigate the Nightborne Vault.", progress = "What did you discover?", completion = "It is true, then. Archmage Vargoth has been corrupted by the legion." }
WordHunterWoW_QuestEN[42494] = { title = "More Than Just A Food Vendor", description = "Your champions made a good dent in thinning out the enemy's numbers. They also discovered a number of starving prisoners who could use our help. Your Conjured Mana Pudding or Fritters will be useful in getting them up on their feet. \n\nYou should also dispatch as many of the remaining legion invaders back to the twisting nether as you can!", objectives = "Eradicate 15 demons and give your conjured food to 10 starving prisoners.", progress = "Have you been able to help the prisoners?", completion = "Good job, <name>." }
WordHunterWoW_QuestEN[42495] = { title = "Ashbringer Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[42496] = { title = "Truthguard Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[42497] = { title = "Silver Hand Chosen", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[42501] = { title = "Finishing the Job", description = "Garona set out to assassinate the leaders of a Legion cult some time ago. We haven't heard from her since.\n\nTo make matters worse, she took the Kingslayers with her. She knows they bring out the worst in her!\n\nYour best bet to find Garona is by continuing her work. Our intel points to a warlock by the name of Caden Shadowgaze inducting new recruits at the Altar of Storms in Blasted Lands. See if he has anything useful in his pockets.\n\nOnce he's dead, I mean.", objectives = "Assassinate Cade Shadowgaze at the Altar of Storms in Blasted Lands and search his body for information." }
WordHunterWoW_QuestEN[42502] = { title = "No Sanctuary", description = "We have one other lead that may prove useful. Goes by Felcaller Whitley, another of the cult's elite. He's eluded our agents at every turn.\n\nOur latest reconnaissance report puts him somewhere in the village of Raven Hill in Duskwood. He's sure to have information vital to your search.\n\nYou know what to do.", objectives = "Assassinate Felcaller Whitley at Raven Hill in Duskwood and search his body for information." }
WordHunterWoW_QuestEN[42503] = { title = "Codebreaker", description = "<The coded message you obtained is protected by powerful magic, rendering it indecipherable by conventional means.>\n\n<If you use the cipher you took from Felcaller Whitley you might be able to crack the code, leading you ever closer to both the cult's base of operations and Garona.>", objectives = "Use the Fel Cipher to decrypt the Coded Message and learn where you can find the cultists next." }
WordHunterWoW_QuestEN[42504] = { title = "The Unseen Blade", description = "We can't let Stormwind fall to the Legion, and I don't trust Shaw or his SI:7 goons to take care of the Hand on their own.\n\nThe two of us need to handle this while there's still time.\n\nThe entire city is on edge from murmurs of the cult's activities. They're as likely to turn on you as they are the cultists if you aren't careful.\n\nThe other Shadows spoke highly of your skills. Are you in?", objectives = "Help Garona take out the Veiled Hand cultists in Stormwind.", completion = "Every second I held those blades was torture. They're all yours." }
WordHunterWoW_QuestEN[42505] = { title = "Arcanist Shal'iman", description = "", objectives = "" }
WordHunterWoW_QuestEN[42506] = { title = "Tomes of Yore", description = "", objectives = "" }
WordHunterWoW_QuestEN[42507] = { title = "Assn Rogue - Flavor Event 04", description = "", objectives = "" }
WordHunterWoW_QuestEN[42508] = { title = "Not A Toothless Dragon", description = "The Arcway Vaults have been buried and untouched for thousands of years. We have the legion to thank for it being accessible once again, though I would give much for it to remain hidden.\n\nI think we are not far behind Archmage Vargoth's heels and he may yet be inside the vaults. We should make haste if we hope to intercept him.", objectives = "Ride with Kalecgos to the Arcway Vaults.", completion = "I'll keep them busy outside while you head in." }
WordHunterWoW_QuestEN[42509] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[42510] = { title = "Immortal Soul", description = "Illidan's immortal demon soul is lost somewhere in the vastness of the Twisting Nether. Contacting him risks much, the Nether is full of creatures of unimaginable power and appetites. But, it must be done if we are to move forward.\n\nThe ritual can be performed using the nether crucible. Make the blood offering, {name}.", objectives = "Make the Blood Offering to complete the ritual and contact the soul of Illidan Stormrage.", progress = "All that is left is to make the blood offering. Then, we will see what the future holds for the Illidari.", completion = "We must prepare. There is much to do." }
WordHunterWoW_QuestEN[42511] = { title = "Twisted Souls", description = "", objectives = "" }
WordHunterWoW_QuestEN[42512] = { title = "Highmountain Stands", description = "That will have to do. Dargrul has come and we need every able body on the front line. Go, I will be right behind you.", objectives = "Defeat Dargrul.", completion = "The village. It... it is just... gone. They told me what happened to Riverbend but I figured that was an exaggeration." }
WordHunterWoW_QuestEN[42513] = { title = "Ashamane's Fall", description = "", objectives = "" }
WordHunterWoW_QuestEN[42516] = { title = "Growing Power", description = "Archdruid Rensar Greathoof has requested your presence.\n\nOur campaign to defend the Broken Isles is getting under way, and we need you at the helm.", objectives = "Speak to Archdruid Rensar Greathoof at the Dreamgrove.", completion = "Good. I see you have grown in power." }
WordHunterWoW_QuestEN[42517] = { title = "Ritual of Doom", description = "Your research has granted you access to a very powerful ritual, one that will require the aid of a few friends if you wish to successfully summon a demon.\n\nThe ritual needs to be performed at the summoning platform above. \n\nKeep in mind, this sort of power always comes at a price. Not all who participate in the summoning will survive, so be prepared.", objectives = "Perform the Ritual of Doom at the Summoning Platform within Dreadscar Rift.", progress = "You can begin the ritual on the summoning platform above.", completion = "So I take it things went well then?\n\nA ritual of that magnitude requires a bit of recovery time. You cannot expect to perform it more than once a day." }
WordHunterWoW_QuestEN[42519] = { title = "Rise, Champions", description = "As leader of our order, other hunters will look to you for guidance. Many will be willing to pledge themselves to you, doing whatever is necessary in the name of the Unseen Path.\n\nI know of two within our ranks who are impressed with what they've seen from you so far, and want to help any way they can.\n\nSeek them out, and let them ease the burden of leadership.", objectives = "Recruit Emmarel Shadewarden and Loren Stormhoof.", completion = "Excellent. Emmarel Shadewarden and Loren Stormhoof are worthy champions. We can trust them to carry out any task we ask of them." }
WordHunterWoW_QuestEN[42520] = { title = "A Terrible Loss", description = "I would say I am surprised by this terrible turn of events, but nothing surprises me of late. It is dark times when even the most upstanding of us can fall... \n\nWe had best inform Archmage Khadgar of Vargoth's betrayal.", objectives = "Return to the Hall of the Guardian.", completion = "The loss of Archmage Vargoth from our order is terrible to hear, <name>. These are indeed dark times." }
WordHunterWoW_QuestEN[42521] = { title = "The Enemy of My Enemy...", description = "Millhouse Manastorm has been quite vociferous about his intention to acquire the Nightborne Soulstone. If you find him, you may as well make use of him. \n\nHowever, he is unpredictable at best and you should always watch your back around him, {name}. Use my crystal to contact me once you have located him.", objectives = "Find Millhouse Manastorm.", progress = "Were you able to locate Millhouse?", completion = "I hope you are able to put Millhouse's determination to good use!" }
WordHunterWoW_QuestEN[42522] = { title = "Leader of the Illidari", description = "Illidan has officially placed you in charge, {name}. The Illidari are now yours.\n\nMeet me upstairs. We will let everyone know together.", objectives = "Head upstairs and take your place as the new leader of the Illidari.", completion = "Ready, <name>?" }
WordHunterWoW_QuestEN[42523] = { title = "Making Contact", description = "Now that we have recruited champions for our order, we can use the Scouting Map to complete vital assignments across the Broken Isles.\n\nOver the years our scouts have kept a close eye on hunters that might one day be added to our ranks. One such hunter, Lenara, was on her way to Trueshot Lodge when she was attacked.\n\nI suggest that we send Loren Stormhoof on a mission to rescue her. He may be uniquely suited to this task.", objectives = "Use the Scouting Map and complete the mission, \"Lenara Needs Help.\"", progress = "How is the mission proceeding?", completion = "Good, your champions were successful with their mission! We may be seeing some new faces around here soon." }
WordHunterWoW_QuestEN[42524] = { title = "Recruiting The Troops", description = "Our champions acquired the talents of Recruiter Lenara, an extraordinary archer.\n\nShe can hit the smallest of targets at extended ranges. Her arrows never miss.\n\nSpeak to her now and train a squad of archers.", objectives = "Speak to Recruiter Lenara and train a troop of archers.", progress = "How did the training go?", completion = "Excellent. These troops will be invaluable in our defense of the Broken Isles. Deploy them on missions, just as you would with our champions." }
WordHunterWoW_QuestEN[42525] = { title = "Troops in the Field", description = "It's time to send our newly trained archers out into the field. Look at the Scouting Map and send your champions and troops on a routine scouting mission.", objectives = "Use the Scouting Map and complete the mission, \"Troops in the Field.\"", progress = "How did it go?", completion = "The scouting mission was more successful than we could have imagined, <name>. Your troops were able to rescue Survivalist Bahn, a cunning strategist.\n\nIn thanks, he has agreed to lend his skill to our cause." }
WordHunterWoW_QuestEN[42526] = { title = "Tech It Up A Notch", description = "We are very fortunate to have come across Survivalist Bahn. He spent his younger years living off the land in Pandaria, relying on the native flora and fauna to survive.\n\nHis firsthand experience with building from limited resources could really help shape Trueshot Lodge into something great.\n\nSpeak to him now and see what he can do for us.", objectives = "Speak to Survivalist Bahn in Trueshot Lodge.", progress = "Have you spoken with Survivalist Bahn yet?", completion = "Excellent choice, <name>. Survivalist Bahn has made the lodge his home, so just speak to him when you want to make upgrades." }
WordHunterWoW_QuestEN[42527] = { title = "FLAG - Portal - Guard Station", description = "", objectives = "" }
WordHunterWoW_QuestEN[42528] = { title = "FLAG - Portal - Black Market", description = "", objectives = "" }
WordHunterWoW_QuestEN[42529] = { title = "FLAG - Portal - Inn Entrance", description = "", objectives = "" }
WordHunterWoW_QuestEN[42530] = { title = "FLAG - Portal - Alchemy Room", description = "", objectives = "" }
WordHunterWoW_QuestEN[42531] = { title = "FLAG - Portal - Abandoned Shack", description = "", objectives = "" }
WordHunterWoW_QuestEN[42532] = { title = "FLAG - Portal - Rear Entrance", description = "", objectives = "" }
WordHunterWoW_QuestEN[42533] = { title = "The Ruined Kingdom", description = "So the Lich King has revealed the second of the Four Horsemen... it appears that not even kings may rest as the world burns around them.\n\nSo be it, Deathlord.\n\nI will send Nazgrim and Thassarian to meet you at the fallen kingdom of Stromgarde.\n\nPrince Galen Trollbane holds the key to the tomb of his father, a famous sword known as Trol'kalar. In order to raise the king as the second of the Four Horsemen, we will need to gain entrance to the tomb.\n\nDo what you must to persuade Galen assist us...", objectives = "Speak with Prince Galen Trollbane in Stromgarde.", completion = "For what purpose do you intrude upon my kingdom, <class>? Speak quickly, for I have little patience..." }
WordHunterWoW_QuestEN[42534] = { title = "Our Oldest Enemies", description = "I will grant the Ebon Blade access to my father's tomb. First though, I must ask a favor.\n\nI have taken up the sword and banner of my father. I have reclaimed Stromgarde with its former citizens as my guard. Yet, one task remains.\n\nWitherbark invaders have blockaded themselves in the former mage district of the city. My men have suffered heavy losses at their vile hands.\n\nCut them down to the last! Bring me their heads and I shall give you what you seek.\n\nYou have my word as the King of Stromgarde.", objectives = "Collect 15 Witherbark Troll heads.", progress = "Do you have the heads of my enemies? I want to look upon each and every face...", completion = "Soon the heads of my enemies shall line the walls of my kingdom! These shall be the first of many.\n\nNot even Sylvanas will dare to step foot upon the free kingdom of Stromgarde!" }
WordHunterWoW_QuestEN[42535] = { title = "Death... and Decay", description = "My family has fought the Witherbark trolls for generations... their presence in Arathi has always been a curse upon the land. I want to drive them out of Stromgarde for good!\n\nDestroy their supplies and we shall give them no incentive to return. Blight their supplies... or whatever it is you death knights do to defile things. I care not.\n\nJust make sure that it is done!", objectives = "Blight 10 Witherbark Supplies.", completion = "You have done my kingdom a service, <class>. Stromgarde will not forget the service you have done us this day." }
WordHunterWoW_QuestEN[42536] = { title = "Regicide", description = "Galen Trollbane is a fool if he thinks that he can betray the Ebon Blade.\n\nI have had enough of his games. The fallen prince wastes our time playing the king of a ruined throne, while heroes sacrifice their lives to save this world.\n\nIf Galen Trollbane will not open the tomb of his father, then we must take the sword and do it ourselves.\n\nIf he chooses to resist, so be it.", objectives = "Obtain Trol'kalar from Prince Galen Trollbane.", progress = "We need the sword Trol'kalar to open this tomb. Have you found it?", completion = "We have tarried here long enough, Deathlord. The time has come to open the tomb and raise our champion." }
WordHunterWoW_QuestEN[42537] = { title = "The King Rises", description = "King Thoras was one of the greatest warriors this world has known.\n\nHis people loved him and his enemies feared him. He only ever spoke truth, often saying the words others were afraid to speak.\n\nKing Thoras lived a life of war and he certainly deserves the peace of death. But this is not a man who would sleep peacefully while the world around him burns.\n\nThe time has come, Deathlord, to welcome the last true King of Stromgarde into the arms of the dead and damned.", objectives = "Raise King Thoras Trollbane as a Death Knight.", progress = "King Trollbane was a great man. He will be a powerful ally against the threat of the Burning Legion.", completion = "Today, a great king has risen from the dead to once more take up the sword in the name of liberty.\n\nIt will be an honor to fight at his side against the legions of terror." }
WordHunterWoW_QuestEN[42538] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[42539] = { title = "Cloak and Dagger", description = "<The cultists seem to have a base of operations in Darkshire. At least Althea Ebonlocke is a member, but it is likely that the entire Night Watch has been compromised.>\n\n<The best course of action for now is to retrieve the dark implements for their ritual and make an attempt on Althea's life. Garona will have to wait.>", objectives = "Retrieve the Skull of the Innocent, the Blood of the Innocent, and make an attempt on Althea Ebonlocke's life in Darkshire." }
