WordHunterWoW_QuestEN[42566] = { title = "A Blaze of Starlight", description = "I will deliver the good news of my recently-rediscovered vitality to my brood. You, on the other hand, have a Tidestone to deliver.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Tidestone of Golganneth to Archmage Khadgar in Dalaran." }
WordHunterWoW_QuestEN[42567] = { title = "Cursed to Wither", description = "So Cedonu said he saw nightfallen going into Leyhollow?\n\nI don't like the sound of that.\n\nGrandfather seems to be holding his own, but the archmage and I will keep an eye on him. You go investigate our caves.", objectives = "Find the nightfallen that entered Leyhollow.", completion = "<name>? Is that you, my friend?" }
WordHunterWoW_QuestEN[42568] = { title = "Preparation", description = "<With Althea's escape there is only one place to go: Stormwind.>\n\n<If Garona is keeping a similar pace on the cult's trail, she's bound to be making preparations to enter the city herself.>\n\n<Finding her is paramount before moving into the city.>", objectives = "Find Garona Halforcen outside Stormwind.\n\nProvided item:", completion = "If you're with me, drench your blades with poison now. This is going to get bloody." }
