WordHunterWoW_QuestEN[42583] = { title = "Rise, Champions", description = "The Legion's defeat cannot be accomplished alone.\n\nTo win this war, we must work together, just as we did in ancient times.\n\nTo begin, we must recruit more druids to our aid. Speak to the troll Zen'tabra and the night elf Naralex.\n\nBoth of them are accomplished druids. They will gladly defend the Dreamgrove.", objectives = "Recruit Zen'tabra and Naralex.", completion = "Good. I know Zen'tabra and Naralex, and they will serve the Dreamgrove bravely." }
WordHunterWoW_QuestEN[42584] = { title = "Sister Lilith", description = "We will need more allies on our side before we can be effective, Archdruid. A skilled dryad by the name of Sister Lilith is on her way to the Dreamgrove, but we've received word that she may be in trouble.\n\nSend Zen'tabra to her aid.", objectives = "Use the Scouting Map and complete the mission \"Sister Lilith\".", progress = "Do not delay. Sister Lilith is in trouble.", completion = "Excellent, <name>. Zen'tabra has done well." }
WordHunterWoW_QuestEN[42585] = { title = "Recruiting the Troops", description = "In our champions' travels, they made contact with Sister Lilith, a fearless leader among the Laughing Sisters.\n\nShe is revered among the dryads as a seasoned warrior and a demanding teacher. She will serve as an excellent recruiter.\n\nSpeak to her now, and recruit some Treants.", objectives = "Speak to Sister Lilith and recruit some Treants.", progress = "Additional troops will be very useful for the missions ahead.", completion = "Well done. I knew that Sister Lilith would come through for us." }
WordHunterWoW_QuestEN[42586] = { title = "A Glade Defense", description = "We have a new mission that needs our attention, Archdruid. Deep in the forests of Val'sharah, a small druidic outpost known as Shal'doren Grove is under attack by satyrs.\n\nSend our champions to deal with this threat at once, {name}. We cannot allow these satyr incursions to grow unchecked!", objectives = "Use the Scouting Map and complete the mission,\"A Glade Defense.\"", progress = "The satyrs are growing bolder with every day.", completion = "Not only was the mission a success, but our champions recovered an inscribed leaf of ancient knowledge. These may be of great interest to Leafbeard the Storied, the Ancient of Lore who resides to the north." }
WordHunterWoW_QuestEN[42588] = { title = "Branching Out", description = "Leafbeard is known as the Storied for good reason.\n\nIt is said that he remembers tales from before the Sundering. After examining the inscribed leaf that our champions recovered, he may be able to provide new knowledge and improvements for the grove.\n\nGo take it to him now.", objectives = "Speak to Leafbeard the Storied at the Dreamgrove in Val'sharah.", progress = "It is said that Leafbeard never forgets anything.", completion = "Well done! I see that Leafbeard's advice has already been useful." }
WordHunterWoW_QuestEN[42590] = { title = "Moozy's Reunion", description = "You will never know how thankful we are to you, {race}. Because of you, Moozy and my husband are safe. I won't let either of them out of my sight!\n\nI am sorry to ask one last favor of you, but do you think you could find my mother and bring her here so she can see that her grandchild is safe?\n\nHer name is Ethel, and her home is on the northern bluff of Thunder Totem.", objectives = "Find Ethel Waterwise and reunite her with her family at the Hammer's Cradle in Thunder Totem.", progress = "Thank you for your kindness. Truly.", completion = "Your kindness will not be forgotten. You are a friend to my family, <name>." }
WordHunterWoW_QuestEN[42591] = { title = "Vignette - Hannval the Butcher", description = "", objectives = "" }
WordHunterWoW_QuestEN[42593] = { title = "The Arcane Way", description = "Getting into the Black Temple is going to be tricky. Following the break-in by the Council of the Black Harvest, Akama had his Sha'tari priests erect a holy barrier. It prevents my teleportation.\n\nHowever, I might know a way to bypass those protections and take us directly to the Temple Summit.\n\nLong ago, I had a... liaison with a certain high elf wizard named Lan'dalock. He later joined the Kirin Tor.\n\nIf you were to ask him very nicely, and drop my name, I am certain that he would help.", objectives = "Locate Archmage Lan'dalock at the Violet Citadel in Dalaran.", completion = "The matron mother?\n\n<The archmage's face goes red as he chokes out a cough and looks around surreptitiously.>\n\nYes, of course. Anything for Malevolence." }
WordHunterWoW_QuestEN[42594] = { title = "Move Like No Other", description = "Sorry about the holographic projection... I literally need to be in two places at once these days.\n\nA holy barrier that protects against fel magic, you say? I have just the thing to bypass it and enable Malevolence's teleport.\n\n<The high elf rummages around in his pack, a shocked look quickly coming over his face.>\n\nSneaky! Look there... that imp just made off with it!", objectives = "Chase down the Sneaky Imp and recover the Grimoire of Arcane Ways.", progress = "Did Archmage Lan'dalock prove useful, <name>?", completion = "I'll make sure to give the grimoire to Malevolence so that she can unravel its mysteries.\n\nMeanwhile, we have some Black Temple scouting to conduct." }
WordHunterWoW_QuestEN[42595] = { title = "Shaman Shrine - Azsuna Water 01 - DGK", description = "", objectives = "" }
WordHunterWoW_QuestEN[42596] = { title = "Mountainstrider Round-Up", description = "Stranger! You are the one I have heard of?\n\nWhen the kerfuffle with the drogbar happened, some of the young moose ran off!\n\nI can't chase them down or the others might wander off as well.\n\nCould you bring them back here?", objectives = "Find 3 Frightened Mountainstriders and return them to Liza Galestride's stable.", progress = "The moose are already broken. Just hop in the saddle and you can bring them here to me!", completion = "Thank you, friend to Highmountain." }
WordHunterWoW_QuestEN[42597] = { title = "Odyn's Summons", description = "Odyn would like to speak to you at once, my liege.\n\nHe is convinced that as you have grown in power you are ready to take direct command of his armies and would like to begin preparations.", objectives = "Speak to Odyn in Skyhold.", completion = "It is as I predicted. You continue to grow in power and prove your worth.\n\nThe time has come for you to take command of my armies, <name>." }
WordHunterWoW_QuestEN[42598] = { title = "Champions of Skyhold", description = "You will soon command one of the greatest armies in existence, but before my own Valarjar follow your every command you must prove your ability to lead.\n\nSpeak to the two vrykul champions who ascended into these halls with you and tell them it is time for you to assume your duties as Odyn's chosen.", objectives = "Recruit Ragnvald Drakeborn and Finna Bjornsdottir.", completion = "You are ready to command your forces. Let us begin!" }
WordHunterWoW_QuestEN[42601] = { title = "Tech It Up A Notch", description = "We are very fortunate to have come across Archivist Melinda. She is somewhat of an anomaly, as not many from her race choose our path. What makes her even more unique is her meticulous study of our craft. Her knowledge will be unsurpassed.\n\nSpeak to her now and seek her council. With her help, we can surely strengthen the council.", objectives = "Speak to Archivist Melinda in Dreadscar Rift.", progress = "Archivist Melinda's skills will allow us to make certain upgrades to Dreadscar Rift.", completion = "Excellent choice, <name>. Archivist Melinda will remain within Dreadscar Rift, so just speak to her when you want to upgrade more of the class hall." }
WordHunterWoW_QuestEN[42602] = { title = "Troops in the Field", description = "It's time to send our newly trained imps out into the field. Look at the Dreadscar Battle Plans and send your champions and troops on a routine scouting mission.", objectives = "Use the Dreadscar Battle Plans and complete the mission, \"Troops in Training\".", progress = "How did it go?", completion = "The scouting mission was more successful than we could have imagined, <name>. Your troops were able to rescue Archivist Melinda, a brilliant strategist.\n\nIn thanks, she has agreed to lend her skill to our cause." }
WordHunterWoW_QuestEN[42603] = { title = "Information at Any Cost", description = "Now that you've found other warlocks that are willing to aid your cause, we can use the Dreadscar Battle Plans to complete vital assignments across the Broken Isles.\n\nIf we wish to rebuild the council, we must start by locating its missing members.\n\nLet us send Ritssyn and Calydus to interrogate the Burning Legion's minions. They might have information that will help us locate the missing council members.", objectives = "Use the Dreadscar Battle Plans and complete the mission \"Information at Any Cost\".", progress = "How is the mission proceeding?", completion = "Ritssyn and Calydus were successful in getting information, though we don't know how reliable it is, considering how it was obtained." }
WordHunterWoW_QuestEN[42605] = { title = "Champion: Ragnvald Drakeborn", description = "", objectives = "Odyn's putting you in charge, eh? Count me in. I find it generally unwise to question the gods." }
WordHunterWoW_QuestEN[42606] = { title = "Champion: Finna Bjornsdottir", description = "", objectives = "I will gladly follow you, <name>. I've seen what you're capable of and you have no fear of death." }
WordHunterWoW_QuestEN[42607] = { title = "Captain Stahlstrom", description = "The souls that make it to these halls are brave, yes. That's why they're here after all.\n\nValor alone does not make for an effective army, however. You will need someone who can train those who would be valarjar to fight with discipline.\n\nHave your champions send word to Captain Stahlstrom. Unruly vrykul berserkers may not fear death, but they might fear Hjalmar Stahlstrom enough to make them follow your orders.", objectives = "Use the Eye of Odyn and complete the mission, \"Captain Stahlstrom.\"", progress = "Is it done, <name>?", completion = "Excellent. Hjalmar will have the valarjar whipped into shape in no time." }
WordHunterWoW_QuestEN[42608] = { title = "Rise, Champions", description = "Friend is in a powerful, but lonely position. First of a council whose members are missing.\n\nFriend does not have to be alone though. Others will be drawn to friend's power, willing to follow if friend leads.\n\nFind those who want to help, and accept their pledge of loyalty.", objectives = "Recruit Calydus and Ritssyn Flamescowl.", completion = "It says a lot that Ritssyn would give up his position and look to you for leadership. He must believe that you are the key to rebuilding the council." }
WordHunterWoW_QuestEN[42609] = { title = "Recruiting the Troops", description = "Captain Stahlstrom has arrived. It would be advisable to speak to him and see that the valarjar are armed and ready for battle.\n\nWe'll need more than your two champions if we're to win a full-fledged war against the Legion.", objectives = "Speak to Captain Hjalmar Stahlstrom and train Valarjar Aspirants.", progress = "What can I do for you, <name>?", completion = "We are well underway. Before long you will command an army to be reckoned with." }
WordHunterWoW_QuestEN[42610] = { title = "Troops in the Field", description = "Our enemies' transgressions have gone unchecked for long enough. Now that we have troops to back your champions, you would do well to send them to deal with them.\n\nOne of our own has been taken prisoner by Odyn's sworn nemesis, Helya. If your forces manage to bring back Einar the Runecaster alive he can aid us in using powerful runes to advance the power of your armies.", objectives = "Use the Eye of Odyn and complete the mission, \"Troops in the Field.\"", progress = "I greet you.", completion = "Excellent! With the runecaster's powers your armies will be even stronger!" }
WordHunterWoW_QuestEN[42611] = { title = "Einar the Runecaster", description = "Being a leader is not just about sending your troops to combat. You will also make decisions about how we train and improve our armies.\n\nSpeak to Einar the Runecaster and let him know how you would like development to progress.", objectives = "Speak to Einar the Runecaster.", progress = "Yes, <name>?", completion = "A wise choice, <name>." }
WordHunterWoW_QuestEN[42613] = { title = "Growing Power", description = "Friend is getting stronger, and so is friend's weapon! Come back to Dreadscar. I have more to show you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Felblood Altar to imbue your artifact, then speak to Calydus in Dreadscar Rift." }
WordHunterWoW_QuestEN[42614] = { title = "Champion: Svergan Stormcloak", description = "", objectives = "I spent enough time in the afterlife.  Point me at the enemy and I will end them!" }
WordHunterWoW_QuestEN[42616] = { title = "Champion: Dvalen Ironrune", description = "", objectives = "I was sworn to protect Ulduar and if it wasn't for yer aid, I would've failed that promise.\n\nYe can count on me!" }
WordHunterWoW_QuestEN[42617] = { title = "Champion: King Ymiron", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[42618] = { title = "Champion: Thorim", description = "", objectives = "You showed bravery in Ulduar, <name>.  I will fulfill my oath and answer the call of the Gjallarhorn." }
WordHunterWoW_QuestEN[42619] = { title = "Champion: Hodir", description = "", objectives = "I thank you for aiding me, <name>.  I will gladly fight along your side in Odyn's army." }
WordHunterWoW_QuestEN[42620] = { title = "WANTED: Arcavellus", description = "", objectives = "" }
WordHunterWoW_QuestEN[42622] = { title = "Ceremonial Drums", description = "Those foolish calves!\n\nThey've made off with our ceremonial drums again, treating them as toys... as... common drums!\n\nCan you help me find them? They must be scattered to all corners of Thunder Totem by now, discarded as soon as the fun dries up.", objectives = "Find 4 Large, 4 Medium, and 4 Small Ceremonial Drums in Thunder Totem.", progress = "Can you feel the beat?", completion = "Nice! Got 'em! Feel free to play the drums, but leave them down here, will you? You're alright by me, <name>." }
WordHunterWoW_QuestEN[42623] = { title = "Piracy Doesn't Pay", description = "", objectives = "" }
WordHunterWoW_QuestEN[42624] = { title = "Heads of the Fleet", description = "", objectives = "" }
WordHunterWoW_QuestEN[42627] = { title = "The Unseen Blade", description = "Stormwind is too important to fall to the Legion, and I don't trust Shaw or his SI:7 goons to take care of the Hand on their own.\n\nThe two of us will have to handle this while there's still time.\n\nUse extreme caution. The entire city is on edge from murmurs of the cult's activities, and we're already kill on sight.\n\nThe other Shadows spoke highly of your skills. Are you in?", objectives = "Help Garona take out the Veiled Hand cultists in Stormwind.", completion = "Every second I held those blades again was torture. They're all yours." }
WordHunterWoW_QuestEN[42628] = { title = "Treasure 046 - Dreyrgrot", description = "", objectives = "" }
WordHunterWoW_QuestEN[42629] = { title = "Treasure 047 - Dreyrgrot", description = "", objectives = "" }
WordHunterWoW_QuestEN[42630] = { title = "Bolas Bastion", description = "I received word that a coven of harpies and their rocs plan to attack in force.\n\nThey'll be coming from the mountains to the north.\n\nUse one of the bolas launchers and I'll man the other.\n\nQuick!", objectives = "Slay 42 Coven attackers.", progress = "Let's show those harpies why they shouldn't even think about attacking Thunder Totem!", completion = "That was some nice work you did there, <name>. Thanks for the assist." }
WordHunterWoW_QuestEN[42631] = { title = "WANTED: Inquisitor Tivos", description = "", objectives = "" }
WordHunterWoW_QuestEN[42632] = { title = "Treasure 048 - Dreyrgrot", description = "", objectives = "" }
WordHunterWoW_QuestEN[42633] = { title = "WANTED: Vorthax", description = "", objectives = "" }
WordHunterWoW_QuestEN[42634] = { title = "Confrontation at the Black Temple", description = "The book from Lan'dalock is very enlightening. It describes a technique which will provide a simple and elegant bypass around the Black Temple's holy barriers.\n\nI will need but a moment to summon a gateway. Stand back, please.", objectives = "Use the Gateway to the Black Temple and confront Akama.", completion = "Who would have thought he would be working with us?\n\nWe are now one step closer to taking the fight directly to the Burning Legion on their own worlds." }
WordHunterWoW_QuestEN[42635] = { title = "The Mystery of Dreyrgrot", description = "Well met, good chap!\n\nI was on my way to study the local murlocs when I stumbled upon these most peculiar ruins. Those pirates over yonder arrived first, and it appears they've unleashed some ancient evil.\n\nI would be remiss to let such an evil run rampant, but we should learn more of it before we proceed, lest we end up like those chaps.\n\nI spied the crew bringing back some tablets from the ruins. If you can bring them to me, I may be able to decipher the nature of this evil.", objectives = "Gather 4 Ancient Dreyrgrot tablets from the pirate ships outside of Dreyrgrot.", progress = "How goes the hunt for knowledge?", completion = "Excellent! Luckily I brought a copy of the vrykul cipher that the League procured from Northrend.\n\nI'll get to work on this straightforth! Let us hope the dialects are not too dissimilar." }
WordHunterWoW_QuestEN[42636] = { title = "WANTED: Arcanist Shal'iman", description = "", objectives = "" }
WordHunterWoW_QuestEN[42637] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[42638] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[42639] = { title = "A Stone of Blood", description = "Unfortunately, we may have another problem. That mist seeping out of the ruins has affected the looting pirates. It's driven them quite mad.\n\nOnly one of them seems to be unaffected - a captainly fellow with a very fine hat.  He wears a large ruby amulet, which I believe protects him from the mist. You'll need it if you are to enter the tomb.\n\nHe may not give it up willingly.", objectives = "Collect Broketooth's Ruby Amulet from Captain Broketooth on the ships near Dreyrgrot.", progress = "We will need the amulet's protection to proceed.", completion = "You have the amulet! Most excellent!\n\nOf course, that probably won't help you with the pirates that are already mad as hatters, but small victories, eh chap?" }
WordHunterWoW_QuestEN[42640] = { title = "The Value of Knowledge", description = "This crate is filled with relics from the nearby ruins. The pirates have discarded them, likely thinking they're of little value.\n\nThe Explorers' League would probably appreciate if you retrieved these relics for them to study.", objectives = "Gather 7 Crates of Ancient Relics from the waters outside Dreyrgrot.", progress = "What's this?", completion = "Well that was most noble of you to save these ancient relics from a water-logged fate.\n\nI will be sure that the Explorer's League puts these to good use!" }
WordHunterWoW_QuestEN[42641] = { title = "What the Bonespeakers Buried", description = "Most Fascinating! It would appear that we're dealing with our very own vrykul vampyr!\n\nAll we have encountered have been of blood elven descent, but it has long been theorized that the vrykul have suffered the curse as well. It's too bad he's awake - I would dearly like a subject to study.\n\nOh well, guess there's nothing for it. Take this stake and put it through the old chap's heart. I'm pretty sure that should do the trick.", objectives = "Use the Sharp Wooden Stake to kill Blood-Thane Lucard in Dreyrgrot.", completion = "Oh, the stake didn't work you say?  My apologies, I must've had my immortal evil undead mixed up.\n\nYou're all in one piece though, and the evil has seen its end. Hopefully, at least.\n\nVampyr can die, can't they?" }
WordHunterWoW_QuestEN[42645] = { title = "Spilling Bad Blood", description = "Ending the evil of the Blood Prince will be a boon to this land, but we can't just allow these crazed corsairs to run amok.  I'm afraid there is no choice but to put them to the sword.\n\nCarry out this noble deed, my good fellow, and we will celebrate with a nice warm lager.", objectives = "Kill 8 Blood-Crazed Swashbucklers in Dreyrgrot.", completion = "Good riddance to bad rubbish, I say. \n\nThose louts were ne'er-do-wells before they went crazy. Just imagine what they would do if we let them run rampant!\n\nCheers to your bravery, sir." }
WordHunterWoW_QuestEN[42646] = { title = "Medical Supply Crate", description = "", objectives = "" }
WordHunterWoW_QuestEN[42647] = { title = "Medical Supply Crate", description = "", objectives = "" }
WordHunterWoW_QuestEN[42648] = { title = "Medical Supply Crate", description = "", objectives = "" }
WordHunterWoW_QuestEN[42649] = { title = "Arluin Bribe Tracker 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[42650] = { title = "Break the Bonds", description = "The Bonespeaker mystics used these heirlooms to tie my soul to this world.\n\nUnder their curse, my soul could not enter the Halls of Valor. Find the soul pyre in Haustvald and throw my belongings into the flames.\n\nThe fire that bound my soul through their foul magic will be the same fire that undoes this bond!", objectives = "Throw Svergan's Belongings into the Soul Pyre and complete the Ritual of Unbinding.", progress = "Is it done yet, CONCUSSED?", completion = "I can feel it. My soul is my own again!" }
WordHunterWoW_QuestEN[42651] = { title = "Svergan's Promise", description = "I thank you for doing this for me. I swore an oath to protect the Gjallarhorn with my life, and so I did.\n\nYou must tell Hymdall that his Gjallarhorn was devoured by the great worm, Jorhuttam!\n\nIt devoured an entire army of my men who were swallowed whole trying to fend off the beast. Find Jorhuttam and you will find the horn!", objectives = "Return to Hymdall in Skyhold.", completion = "Jorhuttam! We must track the great worm at once. It will surely be a great battle." }
WordHunterWoW_QuestEN[42652] = { title = "Ancient Exemplars", description = "", objectives = "" }
WordHunterWoW_QuestEN[42653] = { title = "Champion: Akama", description = "", objectives = "I am encouraged that we have come to an understanding. I admired Altruis when he opposed the direction Illidan was taking all those years ago. While the annihilation of the Burning Legion is of paramount importance, in the process, we must not become that which we hope to destroy.\n\nIf you would have me as a champion, I will bring all of my knowledge to bear on the task at hand. With time, I believe that we might even come to trust each other." }
WordHunterWoW_QuestEN[42654] = { title = "Darkheart Thicket: Nightmare Oak", description = "Blacksmith Kyriel is no stranger to the Farstriders. He has forged countless arrows for us in the past, using his knowledge of unique materials to help build better, stronger ammo.\n\nHe's efficient and gifted, making the most of scarce materials.\n\nUsing a single branch from a corrupted ancient, he can craft thousands of arrows.", objectives = "Collect Nightmare Oak from Oakheart within the dungeon, Darkheart Thicket.", progress = "Have you recovered the oak yet?", completion = "A little bit of oak can go a long way when making ammo." }
WordHunterWoW_QuestEN[42655] = { title = "Ore Under the Sea", description = "If we want to bring the fight to Hakkar, my rangers are going to need arrows and ammo that are capable of piercing the thick, magic-resistant hides of his hounds.\n\nThere's a versatile smith in Dalaran who does incredible work with both bows and blades alike.\n\nHe uses azure ore in his creations, which can only be found below sea level.\n\nDue to its proximity to leystone, the ore is often overlooked, but in an expert smith's hands, it can be smelted into something nearly indestructible.", objectives = "Mine Azure Ore from deposits found in the water off the coast of Suramar.", progress = "Have you mined the ore yet?", completion = "This looks like more than enough ore to craft weapons and ammo for our allies." }
WordHunterWoW_QuestEN[42656] = { title = "Azure Weaponry", description = "Take the materials to Blacksmith Kyriel in Dalaran, and he'll use them to craft whatever weapons he can.\n\nAs I mentioned before, he's skilled and efficient, so you shouldn't have to wait long.\n\nWhen his work is complete, speak to Shandris Feathermoon about getting the weapons enchanted.", objectives = "Find Blacksmith Kyriel in Dalaran.", progress = "We will need special weapons if we wish to take down Hakkar and his hounds.", completion = "Halduron's blacksmith does fine work, but these weapons still need to be enchanted before they will work against Hakkar's hounds." }
WordHunterWoW_QuestEN[42657] = { title = "Meeting in Moonclaw Vale", description = "Lyana Stardust still lingers in a vale that has been overrun by demons. Despite its current start of upheaval, she refuses to abandon her home.\n\nThe strength and stubbornness she exhibits in the face of an enemy are also traits that shine through in her enchantments.\n\nWe want our weapons to be as strong and stubborn as she is.\n\nMeet her in Moonclaw Vale, and see if she can work her magic with the weapons that Kyriel has crafted for us.", objectives = "Find Lyana Stardust in Val'sharah.", completion = "The Sentinels told me you would be coming.\n\nI apologize for the state of my home. I've been having some trouble with unwanted guests, recently." }
WordHunterWoW_QuestEN[42658] = { title = "Delicate Enchantments", description = "As I'm sure you've noticed, demons have taken over the vale. Their arrival has forced many of my fellow druids to flee their homes, but I refuse to go down without a fight.\n\nDespite all this, I'm happy to provide enchantments for your weapons, but you should know that it is a delicate process that takes time and concentration, something I have little of lately.\n\nIf you're willing to shelter me from attackers, I will certainly do my best to enchant your weapons.", objectives = "Protect Lyana Stardust while she enchants the azure weaponry.", progress = "Enchanting your weapons will require a great deal of power and concentration.", completion = "I'd get a lot more work done if I could convince you to stay, but I know you have pressing matters elsewhere." }
WordHunterWoW_QuestEN[42659] = { title = "In Defense of Dalaran", description = "We have everything we need to set the trap for Hakkar.\n\nArchmage Khadgar will summon a portal to the Violet Hold. Once inside, he will begin to channel his essence into the arcane vessel at your command.\n\nOur allies will be armed with the weapons you brought them, ready to fight when Hakkar takes the bait.", objectives = "Enter the Violet Hold through Khadgar's portal, and defeat Hakkar the Houndmaster.", completion = "You have no idea how relieved I am to see you!" }
WordHunterWoW_QuestEN[42660] = { title = "Vault of the Wardens: Matters of the Heart", description = "I have made considerable progress with the Bloodstone, thanks in part to your extensive testing.\n\nThe stone feeds on blood to grow in power, but its ability to control a demon comes from consuming a corrupted heart; the more powerful, the better.\n\nWithin the Vault of the Wardens you'll find someone with such a heart.", objectives = "Collect a Felsworn Heart from Cordana within The Vault of the Wardens dungeon.", progress = "The Bloodstone will grow in power after consuming Cordana's heart.", completion = "Once this heart is devoured, the Bloodstone will be strong enough to control the eredar sisters." }
WordHunterWoW_QuestEN[42662] = { title = "Champion: Archmage Kalec", description = "", objectives = "The blue dragonflight has always represented magic on Azeroth, and it is fitting that we work together against the Burning Legion now more than ever. I would be honored to fight for you as your champion in these dark times." }
WordHunterWoW_QuestEN[42663] = { title = "Rise, Champions", description = "The Tirisgarde has been defunct for ages. To defeat the Burning Legion, we must first recruit the greatest champions of our class to fight by our side. Two powerful archmages, Archmage Kalec and Archmage Modera, have come to help us succeed. \n\nSpeak to them and enlist their aid.", objectives = "Recruit Archmage Kalec and Archmage Modera.", completion = "Archmage Kalec and Archmage Modera are two of the greatest mages in Azeroth's present and past. They will be exemplary representatives of our order." }
WordHunterWoW_QuestEN[42664] = { title = "Champion: Shade of Akama", description = "", objectives = "I have always admired Illidan's singular vision. After all, the annihilation of the Burning Legion is of paramount importance. Nothing else matters. Nothing else can be allowed to stand in our way.\n\nYou will take me as your champion. In return, I will bring all of my knowledge and power to bear on the task at hand. In time, we will destroy all of our enemies... perhaps even Akama as well?" }
WordHunterWoW_QuestEN[42665] = { title = "Into Our Ranks", description = "We should make a show of welcoming this Shade of Akama into our ranks. It is important that the others see him treated as one of us, rather than as an outsider.\n\nKor'vas Bloodthorn has proven herself invaluable, time and time again. Her skills in combat are unquestioned and unparalleled. You will find no champion better suited to destroying our enemies.\n\nIt is time to officially raise them up as champions.", objectives = "Recruit the Shade of Akama and Kor'vas Bloodthorn as your champions.", completion = "Up until now, the Illidari have been a fairly exclusive club. Demon hunters only. But, as you have so clearly demonstrated, my dear, if we are to move forward trusting one-another, then bringing Akama in is an important step.\n\nIt gives one hope.\n\nAnd, of course, making Kor'vas one of your champions is the obvious choice. No one fights as well as she does.\n\nWhat's that?" }
WordHunterWoW_QuestEN[42666] = { title = "Return to the Fel Hammer", description = "{name}, Battlelord Gaardoun asked me to retrieve you. He says there is a very important matter that he needs your help with.\n\nHe requests your presence back on the Fel Hammer as soon as possible.", objectives = "Speak with Battlelord Gaardoun on the Fel Hammer.", completion = "Commander. I am glad to see that Asha was able to find you so quickly.\n\nThere is something important that you must attend to as soon as possible." }
WordHunterWoW_QuestEN[42669] = { title = "Preparations for Invasion", description = "We have the Sargerite Keystone. We have most of the forces we will need. We even have a plan.\n\nNow we need to locate the Felsouls and prepare for an invasion of whatever demon world they're hiding out on.\n\nPlease leave it to me. If you will grant me the use of your champions, I and the Scythe of Souls will extract the information by any means necessary from the demons that we question.", objectives = "Use the Scouting Map and complete the \"Preparations for Invasion\" missions.", completion = "And now we know that Caria and Varedis are hiding away on the demon world known as Niskara.\n\nTime to finish this." }
WordHunterWoW_QuestEN[42670] = { title = "Rise, Champions", description = "The matron mother, Lady S'theno, and I have been watching you and the rest of the Illidari. We have something of an outsider's perspective on things, which gives us a degree of objectivity. We have come to a unanimous recommendation: in order to keep the Illidari from splintering, you must begin to recruit champions.\n\nThese exalted few will aid in projecting your power beyond the confines of the Fel Hammer.\n\nOur unanimous recommendations for the first two are Altruis and Asha.", objectives = "Recruit Altruis the Sufferer and Asha Ravensong as your first champions.", completion = "You have selected your first two champions. There are great things ahead of us, <name>." }
WordHunterWoW_QuestEN[42671] = { title = "Rise, Champions", description = "The matron mother, Lady S'theno, and I have been watching you and the rest of the Illidari. We have something of an outsider's perspective on things, which gives us a degree of objectivity. We have come to a unanimous recommendation: in order to keep the Illidari from splintering, you must begin to recruit champions.\n\nThese exalted few will aid in projecting your power beyond the confines of the Fel Hammer.\n\nOur unanimous recommendations for the first two are Kayn and Asha.", objectives = "Recruit Kayn Sunfury and Asha Ravensong as your first champions.", completion = "You have selected your first two champions. There are great things ahead of us, <name>." }
WordHunterWoW_QuestEN[42672] = { title = "Growing Power", description = "I see you have grown in strength. With it, some of the untapped potential within your weapon is released.\n\nCome back to the Hall of the Guardian when you are done with your adventures, and I will show you more.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use The Forge of the Guardians to imbue your artifact, then speak to Meryl Felstorm in the Hall of the Guardian." }
WordHunterWoW_QuestEN[42673] = { title = "Champion: Kor'vas Bloodthorn", description = "", objectives = "It's about time, you big lummox. For a while there, when you chose Asha Ravensong first, I started to doubt your sanity.\n\nNot that there's anything wrong with Asha. But, we both know who the better fighter is.\n\nRight?\n\nAnyway, of course, I'd be honored to be your champion. I accept!" }
WordHunterWoW_QuestEN[42677] = { title = "Things Gaardoun Needs", description = "Battlelord Gaardoun has offered to recruit more broken warriors for the cause. He just needs a few things first. He said something about the right tool for the job, or something like that.\n\nTime to put your new champions to the test. I'm sure it will be a grueling mission.", objectives = "Use the Scouting Map and complete the mission, \"Things Gaardoun Needs\".", progress = "Did they come back already with whatever it is that Gaardoun needs?", completion = "Well, at least we're going to have some fresh faces around here. If a broken's face can ever be called fresh, that is.\n\n<Kor'vas smirks.>" }
WordHunterWoW_QuestEN[42678] = { title = "Black Rook Hold: Into Black Rook Hold", description = "This thing is ancient. Just turning the pages risks them disintegrating in my hands.\n\nHere, I have found it. An entry about the Raven's Eye.\n\n<Valeera traces her finger from left to right above the page. A look of discovery comes over her features, which is quickly replaced by a frown.>\n\nIt says here that the last person to have possession of the eye was Lord Ravencrest himself. You are going to have to go into Black Rook Hold and take it from him.", objectives = "Gather a group and enter Black Rook Hold to take the Raven's Eye from Dantalionax.", progress = "<name>, were you successful? Do you have the Raven's Eye?", completion = "We have it. Finally, we will be able to crack SI:7's coded letter." }
WordHunterWoW_QuestEN[42679] = { title = "Broken Warriors", description = "It's important that we increase our numbers. Trust me, I know these things. Battlelord Gaardoun and his Ashtongue warriors are our best bet to quickly accomplish such a task.\n\nYou should speak with him and let him know just what kind of broken you want trained.", objectives = "Speak with Battlelord Gaardoun and train Ashtongue Warriors.", progress = "How are the new Ashtongue troops coming along?", completion = "Outstanding. These new Ashtongue will give you the flexibility you need to position troops wherever you see fit." }
WordHunterWoW_QuestEN[42680] = { title = "Deciphering the Letter", description = "We have the Raven's Eye. Use it, {name}. Decipher the SI:7 letter.\n\nWe must know what secrets it contains!", objectives = "Use the Raven's Eye to decipher the encrypted SI:7 Letter.", progress = "Why do you hesitate? Decipher the note.", completion = "I must admit, I was not expecting that. Mathias Shaw taken prisoner by the Legion.\n\nThat, at least, explains all of the strange actions SI:7 has been taking lately. They have a dreadlord in charge of them." }
WordHunterWoW_QuestEN[42681] = { title = "Loramus, Is That You?", description = "Belath Dawnblade has given us a strange scouting report from the Felblaze Ingress in Azsuna. The dreadlord, Razelikh the Defiler has returned to the world. That's not the odd part, though.\n\nStrangely, he's sometimes going around killing the other demons and calling himself, Loramus!\n\nLast we knew, our demon hunter brother, Loramus Thalipedes sacrificed himself to defeat Razelikh, whom he'd been possessed by.\n\nYour champions and Ashtongue warriors need to go to Azsuna and find out what is going on.", objectives = "Use the Scouting Map and complete the mission, \"Loramus, Is That You?\".", progress = "Odd. That is all I have to say about the situation.", completion = "They've returned with him. It's Loramus, alright. But, he's trapped within the body of the dreadlord, Razelikh the Defiler!\n\nUntil we can make sure he doesn't pose a danger, I've ordered him kept in one of our demon traps, below." }
WordHunterWoW_QuestEN[42682] = { title = "Additional Accoutrements", description = "I heard a rumor that you are going to attempt to make contact with Illidan's immortal demon soul in the Twisting Nether. You are going to need many magical things.\n\nI have taken the luxury of putting together a potential list for you. I do so hope that it proves helpful, handsome.", objectives = "Use the Scouting Map and complete the mission, \"Additional Accoutrements\".", progress = "Have they come back yet with everything we need for the ritual?", completion = "Do we really need all of these ingredients to contact the Master's soul?" }
WordHunterWoW_QuestEN[42683] = { title = "Demonic Improvements", description = "Having Loramus back will work greatly to our advantage, despite the fact that he's trapped inside Razelikh's body... and also that the demon sometimes takes control.\n\nStill, he was one of our most powerful demon hunters. And now, he also has the knowledge of a dreadlord at his disposal.\n\nI think we should have him share his knowledge and wisdom with us to improve our odds in this war.", objectives = "Listen to Loramus Thalipedes' story and then upgrade your Class Hall.", progress = "What did Loramus the Dreadlord have to say?", completion = "That sounds like good news. He is already contributing to the cause and we are that much stronger for his help.\n\nStill, he is not fully in control of Razelikh. I think it best that we leave him in that trap until we can find him a new body. Don't you?\n\nAnd, if he proves to be too much of a problem, we can take 'other' measures." }
WordHunterWoW_QuestEN[42684] = { title = "Throwing SI:7 Off the Trail", description = "SI:7 is dogging our heels at every turn. We must make certain that they do not catch wind of what we are up to.\n\nTo that end, I have some suggestions for you in the form of missions. Send your champions, assign your forces, it matters little to me. The important thing is that we keep them out of Val'sharah and away from Black Rook Hold.\n\nAt least until we can decipher that damned letter.", objectives = "Use the Scouting Map and complete the \"Throwing SI:7 Off the Trail\" missions.", completion = "Surprisingly nice bit of work there. What I am hearing from our scouts is that the diversions are working perfectly.\n\nAs an added bonus, some of my suspicions about a particular item, which will prove useful in deciphering the SI:7 letter, have come to light in Stormheim." }
WordHunterWoW_QuestEN[42685] = { title = "Champion: Archmage Modera", description = "", objectives = "It is good to see the Tirisgarde rise again, <name>. While not everyone on the Council of Six agrees with me, I believe it is imperative for us to work together and defeat the Burning Legion once and for all!" }
WordHunterWoW_QuestEN[42687] = { title = "Troops in the Field", description = "Our troops are ready! It's time to test them out in the field.\n\nWe've received word of survivors near the Broken Shore, but the area is still crawling with Legion.\n\nSend our troops quickly to help with the rescue!", objectives = "Complete the mission, \"Troops in the Field.\"", progress = "How did it go?", completion = "It was very lucky that we found Chronicler Elrianne among the survivors. A well-respected archivist from the Kirin Tor, she also spent several months studying with the pandaren in their library in Tian Monastery.\n\nHer knowledge of ancient magic will be invaluable to our order." }
WordHunterWoW_QuestEN[42688] = { title = "Mrgls of Endearment", description = "Mrmlgr! Mrglr rlmgrg mlrgr! Mrlgmr...\n\n<Phin shows you a flaw on the side of the pearl.>\n\nMmlrgmlr rlmgr grlmrmlg mglrmglr. Mlrgmrl rmglr? Mlgrmglr!\n\nGmmlrgmrl mlrgmlr lrglrmgrl lrlgllrlm mglrlr grlm-grlm.\n\n<Phin makes a pinching motion with his hand.>\n\nMrlgmlgr mgrlmlgr? Mlrgmlr gmrlmglr Mrgrlilgrl.", objectives = "????", progress = "Mrglmrlg? Mrgmlr. Rmlgrmlrg!", completion = "Mlrgmlr! Rgmrlmg, grmlmglr lmrglmrg mrlgmlglr! Mlrgmlrg grmlgrl." }
WordHunterWoW_QuestEN[42689] = { title = "Knowing Our Enemy", description = "If we hope to gain the upper hand against Hakkar, we need to find out more about these hounds that he's breeding and pinpoint their weaknesses.\n\nI know of a warlock that studies demons extensively. Maybe she has seen some of these hounds, and knows how to defeat them.", objectives = "Speak to Kira Iresoul in Azsuna.", completion = "Faronaar is crawling with demons, some familiar, and some peculiar." }
WordHunterWoW_QuestEN[42690] = { title = "Champion: Altruis the Sufferer", description = "", objectives = "You honor me, <name>. Of course I will serve as your champion and right-hand man. How could I refuse?\n\nWe have only just begun to change the way in which the Illidari operate, but already, you have made great strides. If we are to defeat the Burning Legion, it must be done in concert with everyone working together. Not just the Illidari standing alone.\n\nAnd not standing upon the smoking husk of a world that we have carelessly destroyed while trying to save it." }
WordHunterWoW_QuestEN[42691] = { title = "Leyworm Lure", description = "Felhounds are attracted to magic, young ones especially.\n\nThey get a whiff and go into a feeding frenzy! You're not quite as enticing as a mage, so you'll need to cover yourself in something that can fool a felhound into thinking you're its next magical meal.\n\nLeyworm entrails should do the trick.", objectives = "Collect Leyworm Entrails from worms within Leyhollow in Azsuna.", progress = "Leyworm entrails are filled with flecks of magical material that will be irresistible to a fledgling felhound.", completion = "These entrails are rich with magic. They'll make excellent bait." }
WordHunterWoW_QuestEN[42692] = { title = "Children of Nar'thalas", description = "Hi! {name}, right? The archmages in Dalaran said we might see you down here.\n\nMy brother and I are here on a reconnaissance mission. We're looking for our parents.\n\nWe've lived our entire lives thinking that our family was killed in Azsuna several thousand years ago, but look around! Most of the elves here are ghosts.\n\nOlothil's been searching through books for clues as to why, but we could use some help.", objectives = "Find three Ancient Highborne Tomes in the Ruins of Nar'thalas.", progress = "We've hit a dead end here. Any luck out there?", completion = "This Prince Farondis opposed Queen Azshara, so she got mad and blew everything up? That's awesome!\n\nHey Olothil, listen to this!" }
WordHunterWoW_QuestEN[42693] = { title = "You Never Know Until You Scry", description = "In order to find the spirits of our family, I will need materials to scry their location.\n\nThe naga carry magical trinkets imbued with ley energy that is better-attuned to this land than anything we have in Dalaran. If I had a few of those, I could do some real scrying.", objectives = "Obtain 3 Hatecoil Glyptics.", progress = "I would have brought my own spell foci if SOMEONE hadn't been rushing me...", completion = "Perfect. Let's get this ritual started, shall we?" }
WordHunterWoW_QuestEN[42694] = { title = "Back from the Dead", description = "<Olothil sighs.>\n\nMy sister tries my patience sometimes.\n\nNo matter. I've identified a few locations that our parents might be. I shall search in this area with Kallistia. You've already helped us so much... would you help us look to the east?\n\nYou can use my scrying orb to see the locations that our ritual has uncovered.", objectives = "Use the Scrying Orb to determine potential locations of night elf spirits, then go rescue them.", progress = "Thank you for your aid, <class>.", completion = "After over ten thousand years... to see mother and father again...\n\n<The elven mage is at a loss for words.>\n\nThank you, <name>. Thank you." }
WordHunterWoW_QuestEN[42695] = { title = "Champion: Kayn Sunfury", description = "", objectives = "An honor, <name>. Of course I will serve as your champion and second-in-command. Could it have been any other way?\n\nWe have only just begun to move forward with the master's plan, but already, you have made great strides. If we are to defeat the Burning Legion, we must remain vigilant. Any other goal pales in comparison. The fate of everything hangs in the balance.\n\nAt the end of the day, we will stand victorious... no matter the cost!" }
WordHunterWoW_QuestEN[42696] = { title = "Tech It Up A Notch", description = "Thanks to you, the Hall of the Guardian is gradually re-assembling.\n\nHowever, there is much more work to do. As our leader, you can determine the trajectory of our order's future.\n\nSpeak to Chronicler Elrianne. She will show you the ropes.", objectives = "Speak to Chronicler Elrianne", progress = "Our future is in your hands.", completion = "Excellent work, <name>! I can see that the Hall of the Guardian is in good hands." }
WordHunterWoW_QuestEN[42697] = { title = "Champion: Asha Ravensong", description = "", objectives = "You want me to be one of your champions?\n\n<Asha thoughtfully ponders your request a moment.>\n\nI accept, but on one condition. I want you to put me into field duty. While I am of use here on the Fel Hammer, my talents will be put to better use back on Azeroth.\n\nBeyond that, I trust that the plan is still to bring the Burning Legion to its knees?" }
WordHunterWoW_QuestEN[42698] = { title = "Selia, Master of Balefire", description = "", objectives = "" }
WordHunterWoW_QuestEN[42699] = { title = "Coura, Master of Arcana", description = "", objectives = "" }
WordHunterWoW_QuestEN[42700] = { title = "Quin'el, Master of Chillwind", description = "", objectives = "" }
WordHunterWoW_QuestEN[42701] = { title = "Champion: Matron Mother Malevolence", description = "", objectives = "What a rare honor. To be one of the Illidari, instead of a servant. I must admit, I was worried you wouldn't choose me as one of your champions.\n\nBut now you have, and I could just kiss you!\n\nIt never made any sense to me that all worlds should be purged in flame when there are so many delicious playthings to have fun with. Sargeras can be such a bore. Together, we will bring the Burning Legion to its knees and make them grovel in the dirt." }
WordHunterWoW_QuestEN[42702] = { title = "Champion: Millhouse Manastorm", description = "", objectives = "Your Hall here isn't too shabby, <name>. I'm sure there are lots of nifty secrets I can uncover here. I think I'll stay! Er, if you don't mind, of course." }
WordHunterWoW_QuestEN[42703] = { title = "Technical Wizardry", description = "Now that you have your first two champions, there is an abundance of work they can do to help us.\n\nArchmage Melis has been hard at work getting our command room up and running. Head downstairs and ask her to show you what needs to be done.", objectives = "Talk to Archmage Melis.", completion = "Greetings, <name>. The fires of Azeroth give us the power to see beyond ourselves." }
WordHunterWoW_QuestEN[42704] = { title = "Champion: Arcane Destroyer", description = "", objectives = "<The Arcane Destroyer makes a high pitched, quizzical chirp and looks at you expectantly.>" }
WordHunterWoW_QuestEN[42705] = { title = "Champion: Ravandwyr", description = "", objectives = "I have been Archmage Vargoth's apprentice for far too long. Perhaps it is time for me to serve a new master. I would be honored if you would accept me as your champion, <name>." }
WordHunterWoW_QuestEN[42706] = { title = "Champion: Esara Verrinde", description = "", objectives = "You and I have proven to be quite successful together. I'd be happy to lend you my swords and spells against the Burning Legion anytime, <name>." }
WordHunterWoW_QuestEN[42707] = { title = "Eye of Azshara: A Magical Affliction", description = "Archmage Vargoth's betrayal is an unimaginable loss to our cause, {name}. We will have to deal with him, but first Meryl's condition has become dire. \n\nUnfortunately it is not an illness at all, but a magical attack of fel origin. It may be his old nemesis Kathra'natir is behind it. We need to buy him time.\n\nThe Eye of Azshara contains a vast store of arcane energy from Queen Azshara herself. If we could obtain a vial of water from the Wrath of Azshara's body, that will sustain him for a while.", objectives = "Fill a vial with arcane water from the Wrath of Azshara.", progress = "Have you obtained a vial of arcane water yet?", completion = "Good -- you're back just in time! This will sustain Meryl while we search for his attacker." }
WordHunterWoW_QuestEN[42708] = { title = "A Personal Request", description = "If you have a moment, Deathlord... there is a personal matter I would like to speak with you about.\n\nSome time ago, a brother of the Ebon Blade was imprisoned beneath the ruins of Lordaeron by the Dark Lady.\n\nSylvanas has refused all attempts to negotiate his release. Now, our world faces destruction and the time for diplomacy has passed.\n\nKoltira Deathweaver cannot fight the Burning Legion in chains.\n\nSo we will break them.", objectives = "Rescue Koltira Deathweaver from Undercity.", progress = "The time has come to release Koltira Deathweaver from captivity.", completion = "Sylvanas will not be pleased with our actions, but we have more to worry about than offending the Dark Lady." }
WordHunterWoW_QuestEN[42711] = { title = "The Eternal Mages", description = "", objectives = "" }
WordHunterWoW_QuestEN[42712] = { title = "Eye of Azshara: Termination Claws", description = "", objectives = "" }
WordHunterWoW_QuestEN[42713] = { title = "Eye of Azshara: Slug It Out", description = "", objectives = "" }
WordHunterWoW_QuestEN[42714] = { title = "Darkheart Thicket: Mythana", description = "", objectives = "" }
WordHunterWoW_QuestEN[42715] = { title = "Frost DK - Highmountain Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[42716] = { title = "Frost DK - Val'sharah Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[42717] = { title = "Frost DK - Stormheim Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[42718] = { title = "Frost DK - Azsuna Event", description = "", objectives = "" }
WordHunterWoW_QuestEN[42719] = { title = "Eye of Azshara: Cleansing the Dreamway", description = "Brightwing has lots of friends. I like friends!\n\nBut you know who isn't Brightwing's friend? Scary monsters from the nightmare!\n\nThey hurt Brightwing's allies, and they made the grove all yucky!\n\nThis place needs to be cleansed, but I'm all out of magic.\n\nCan you bring Brightwing some purified water to help? You'll have to go far, far away... to the Eye of Azshara where the naga live.", objectives = "Collect 25 Rarefied Water from the naga in the Eye of Azshara, and defeat the Wrath of Azshara.", progress = "Poor, poor flowers...", completion = "Oh! Clean water, so pure and magical! Thank you, hero!" }
WordHunterWoW_QuestEN[42721] = { title = "Vignette: Unused", description = "", objectives = "" }
WordHunterWoW_QuestEN[42722] = { title = "Friends in Cages", description = "<Korine stomps her foot and refuses to move.>\n\nThey put my friends in cages!\n\nMake the bad men stop hurting them! They take them out the garden and they never come back!\n\n<Korine gestures stubbornly toward the door.>\n\nI am not going home until they do!", objectives = "Release 3 Nightborne Citizens from their captivity.", progress = "Did you let them out?", completion = "You let them go? I'm glad. I didn't like being in a cage either..." }
WordHunterWoW_QuestEN[42723] = { title = "Eye of Azshara: A Tough Shell", description = "", objectives = "" }
WordHunterWoW_QuestEN[42724] = { title = "Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[42725] = { title = "Sharing the Wealth", description = "Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. \n\nI imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine.\n\nWith the presence of the demons came rationing. There are many who do not have enough to sustain themselves.\n\nBring me as much Arcwine as you can carry. I will see that it gets to the right people.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 20 Bottles of Arcwine." }
WordHunterWoW_QuestEN[42726] = { title = "Brutal Gladiator's Battlegear", description = "", objectives = "" }
WordHunterWoW_QuestEN[42727] = { title = "Transition to Forge Quests", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[42728] = { title = "A Mlrglrmg For Grlmrgl", description = "Mrglm, rmgrlg mrlgmrl.\n\nGrmrglmrl mlrmglrgr mlrmlgr! Rglrmgl rmglrgmlr mlmlglr mglgrgrlm - grlgmr, mlgr - lrgmlrgr rmgrmlg mlrg! Mlrgr?\n\nMrlgmrlgmrl rmglrmglr!\n\n<Pearlhunter Phin makes a stabbing motion.>", objectives = "????", completion = "Mrrgml... mlrgmlrg. Mlrmglrg gmrlr!" }
WordHunterWoW_QuestEN[42729] = { title = "Challenger's Armaments", description = "", objectives = "" }
WordHunterWoW_QuestEN[42730] = { title = "Noggenfogger's Reasonable Request", description = "Oh, the gall of that little green twerp! Marin Noggenfogger is blackmailing us. He says that if we do not meet his \"very reasonable requisition request\", he is going to close off access to the crucible.\n\nMarin's asking for a hefty amount of Aethril. He said something about you recently holding a blade to his throat and that he's simply returning the favor.\n\nOf course, if you would rather, I can eliminate him.", objectives = "Collect 20 Aethril.", progress = "Heya, <name>, you have those reagents I requested? You scratch my back, and well... I'll pay someone to scratch yours.", completion = "No hard feelings, right? Business is business, baby, and business is good. I saw an opportunity and I took it, just like you.\n\nTo show my continued allegiance with your little organization, and as a gesture of goodwill, here's a little sample of the product. It's magic. Bottoms up!" }
WordHunterWoW_QuestEN[42731] = { title = "Working With the Wardens", description = "As much as we might not like it, we need the aid of the Wardens if we're to locate the Sargerite Keystone. They took it from you when we were all imprisoned in the vault.\n\nWith Maiev missing, their current leader is Sira Moonwarden. On your behalf, I have agreed that we will assist them in tracking down some of the more powerful creatures that escaped from the Vault of the Wardens. In return, she will direct us to where we need to go to get the Keystone.", objectives = "Use the Scouting Map and complete the \"Working With the Wardens\" missions.", progress = "Is Sira happy with our progress? Not that I care, but we do need her help.", completion = "Well, we did everything that she asked, but that wasn't enough for Sira Moonwarden.\n\nShe's asking for one more thing and she wants you to deal with it personally." }
WordHunterWoW_QuestEN[42732] = { title = "Deadlier Warglaives", description = "Loramus has researched a way to make our warglaives even deadlier, especially against demons.\n\nIf he's to be trusted, he says that all he needs is an amount of Obliterum. Normally, the substance is used to improve the protection of armor, but Loramus insists he can use it for our warglaives.\n\nI am certain we will all benefit from their increased deadliness on the battlefield.", objectives = "Collect 1 Obliterum, which can be obtained either from your Forge of Fate in Dalaran's Magus Commerce Exchange or from the Auction House.", progress = "Have you obtained the Obliterum?", completion = "That stuff's hard to get and expensive. Impressive! I can't wait to see the results.\n\nReady for the next big task? No rest for the wicked." }
WordHunterWoW_QuestEN[42733] = { title = "A Very Special Kind of Fuel", description = "All Legion constructs, including the Fel Hammer, are powered by souls. If we are going to take the command center to Niskara, we are going to need some very powerful souls, indeed!\n\nYou are a very creative person, {name}. I am certain that you will find a way to get what we need from the right sorts of creatures.", objectives = "Collect 15 Sovereign Souls from bosses in Legion dungeons.", progress = "<name>, do you have what Allari asked you to harvest for fuel?", completion = "Of course. Like all Legion constructs, the Fel Hammer is powered by souls. You have collected some of the most powerful souls around.\n\nThey should be enough to take us anywhere you want to go." }
WordHunterWoW_QuestEN[42734] = { title = "Into the Oculus", description = "I fear Kathra'natir is behind the attack on Meryl. We have little time to act. \n\nI suspect Archmage Vargoth's involvement is no coincidence. While it greatly pains me to destroy an archmage of his caliber and worse, someone I once called friend, we cannot permit his betrayal to stand unpunished. \n\nIt is time to follow him into the Oculus.", objectives = "Talk to Archmage Khadgar when you are ready to travel to the Oculus.", completion = "You have done the unimaginable, <name>.We are all in your debt. I am proud to henceforth name you Archmage <name>!" }
WordHunterWoW_QuestEN[42735] = { title = "Malace in Vrykul Land", description = "I did some recon in Stormheim. What I discovered is that the Tideskorn are a tribe of vrykul who have been cut-off from the sea by their kvaldir brethren. Many of the Tideskorn have pledged their services to the Legion and become Felskorn.\n\nMalace Shade was last seen heading toward the Felskorn Warcamp. It is likely that she was captured.\n\nI have arranged a flight to Stormheim for you. When you are ready, you can use the gateway to travel to Dalaran and speak with Aludane Whitecloud at Krasus' Landing.", objectives = "Grab a flight from Aludane Whitecloud and find Malace Shade in Stormheim.", completion = "<name>, is that you? This is a rather odd turn of events, don't you think?\n\nYou're free and now I am the prisoner." }
WordHunterWoW_QuestEN[42736] = { title = "Rune Ruination", description = "A cage wasn't enough to hold me, so the vrykul ensorcelled these runestones to trap me in here. Each is powered by a different Felskorn rune.\n\nUnfortunately, they gave the runes to different guardians, who have all scattered to different places around Stormheim.\n\nSo, if Sira said that you could have your precious keystone back, you're first going to have to get me out of here.\n\nThen, we'll see.", objectives = "Deactivate the three runestones to set Malace free.", completion = "I guess I underestimated you. Good. I like to learn and grow.\n\nUp to helping me out with one more little thing?" }
WordHunterWoW_QuestEN[42737] = { title = "Rune Ruination: Runeskeld Rollo", description = "<Collect the rune from Runeskeld Rollo to deactivate this runestone.>", objectives = "Collect Rollo's Rune.", progress = "<The runestone thrums with fel-corrupted power. Disable it with its corresponding rune.>", completion = "<The runestone begins to vibrate as you approach, rune in hand.>" }
WordHunterWoW_QuestEN[42738] = { title = "Rune Ruination: Runelord Ragnar", description = "<Collect the rune from Runelord Ragnar to deactivate this runestone. If you do not already have one, obtain a grapple launcher in order to scale the walls of Hrydshal.>", objectives = "Collect Ragnar's Rune.", progress = "<The runestone is keeping Malace Shade imprisoned. Use Ragnar's rune to shut it down.>", completion = "<Ragnar's rune grows warm as you approach the runestone.>" }
WordHunterWoW_QuestEN[42739] = { title = "Rune Ruination: Runesage Floki", description = "<This runestone is entrapping Malace Shade. It can only be destroyed by using Runesage Floki's rune upon it.>", objectives = "Collect Floki's Rune.", progress = "<Who knows how long the Felskorn vrykul will leave Malace Shade alive? Best to deal with the runestone sooner rather than later.>", completion = "<The rune and the runestone begin to glow and thrum with increased power.>" }
WordHunterWoW_QuestEN[42740] = { title = "The Battle for Broken Shore", description = "This is your vessel, {name}. She's a fine ship; been through many a campaign. Speak with the ship's captain when you're ready to depart.\n\nGood luck out there. We've received few reports about what's happening at the Broken Shore, but I'd wager King Varian has matters well in hand.", objectives = "Take the third fleet ship to the Broken Shore.", completion = "Ah, <name>, you're up! I'm relieved you made it out of that bloodbath alive. We lost so many good women and men down there...\n\n\n\nDamn the Horde for serving us up to the Legion!" }
WordHunterWoW_QuestEN[42741] = { title = "Legion Expansion Started Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[42742] = { title = "Darkheart Thicket: Rage Rot", description = "", objectives = "" }
WordHunterWoW_QuestEN[42743] = { title = "Darkheart Thicket: Kudzilla", description = "", objectives = "" }
WordHunterWoW_QuestEN[42744] = { title = "Darkheart Thicket: Preserving the Preservers", description = "", objectives = "" }
WordHunterWoW_QuestEN[42745] = { title = "Darkheart Thicket: A Burden to Bear", description = "", objectives = "" }
WordHunterWoW_QuestEN[42746] = { title = "Eye of Azshara: Dread End", description = "", objectives = "" }
WordHunterWoW_QuestEN[42747] = { title = "Where the Wildkin Are", description = "Owlbeasts are often charged with protecting places of importance to Elune. But if her influence over them wanes or is cut off, the creatures can become dangerous.\n\nThese wildkin, unfortunately, must be dealt with. The recent disturbances in Val'sharah have driven these creatures to madness.\n\nOnce an individual is lost, there is only one way to address the problem.\n\nI cannot bring myself to kill one of Elune's creations, but I know what must be done.", objectives = "Slay 10 Owlbeasts and 8 Undulating Boneslimes within Lostlight Grotto.", completion = "I wish it did not have to come to this, truly." }
WordHunterWoW_QuestEN[42748] = { title = "Emerald Sisters", description = "The owlbeasts here are disconnected from Elune.\n\nA contingent of dryads went into their territory to find out what went wrong, but none of them have returned.\n\nI fear the worst, and I believe they are  in need of rescue.\n\nWhile I try to learn if the owlkin can be saved, I would appreciate your help in freeing any Sisters you find in the grotto.", objectives = "Rescue 6 Sisters of the Moon in Lostlight Grotto.", completion = "The owlbeasts are... melting the dryads down and using their bones to create minions?! How... how could this even be?" }
WordHunterWoW_QuestEN[42749] = { title = "Strange Bedfellows", description = "The reason why I came out here was to capture or kill a fel lord named, Lochaber. I am no longer in a capturing mood.\n\nI'll grab my weapon and then head up to the bridge in front of the Gates of Valor. That place is a scary mess full of Felskorn vrykul and demons.\n\nHow do you think I got caught?\n\nSo, I'd rather not go back in there. But, I think I know a way to get the demon to come out to us.", objectives = "Meet Malace Shade on the bridge at the Gates of Valor and then slay Lochaber." }
WordHunterWoW_QuestEN[42750] = { title = "Dreamcatcher", description = "I cannot hold on for much longer...\n\nI brought a dreamcatcher with me. I was to use it to steal the magic from owlbeast totems.\n\nIt is the only way to break the barrier where they hold Keeper Remulos.\n\nPlease help where I have failed.", objectives = "Charge the dreamcatcher using owlbeast totems in Lostlight Grotto.", progress = "Leirana? Oh no...", completion = "I knew Leirana... she was one of Remulos' favored, and kindhearted soul. If he has been captured as she believes, we have no time to mourn her passing." }
WordHunterWoW_QuestEN[42751] = { title = "Moon Reaver", description = "We must not delay! If Keeper Remulos is in danger, he must be protected.\n\nWith the dreamcatcher, we should be able to enter the lair of the owlbeast Boneflux.\n\nIt must be defeated so Keeper Remulos can break free!", objectives = "Defeat Boneflux and rescue Keeper Remulos in The Undergorge.", completion = "My wounds are great, and my magic has been severely drained. I must recover from this enervation and return to the Dreamgrove.\n\nThe owlkin here are beyond saving by mortal hands, but perhaps Elune will one day shine her light upon them again.\n\nThank you, <name>. May your path be blessed." }
WordHunterWoW_QuestEN[42752] = { title = "Vault of the Wardens: Vault Break-In", description = "<All that is left now is to travel to the Isle of the Watchers off of southwest Azsuna. There, you will need to break back in to the Vault of the Wardens and descend down into its lowest recesses where once you were imprisoned.>\n\n<Within the so-called Vault of the Betrayer, where the Wardens once held Illidan's corpse, the Sargerite Keystone awaits.>", objectives = "Retrieve the Sargerite Keystone.", progress = "Were you successful, <name>? Have you recovered the Sargerite Keystone?", completion = "Finally, revenge against Cordana Felsong for all of the demon hunters whom she tempted into becoming Felsworn. Cyana, Tirathon, Glayvianna, Cailyn, Illysanna, and more.\n\nHer death has been a long time coming.\n\nThe Sargerite Keystone is once more in our possession. Now, to look to the future." }
WordHunterWoW_QuestEN[42753] = { title = "Vault of the Wardens: Vault Break-In", description = "The Wardens made good on the deal. All that's left is to travel to the Isle of the Watchers off of southwest Azsuna. There, you'll need to break back in to the Vault of the Wardens and descend down into its lowest recesses where we were once imprisoned.\n\nWithin the so-called Vault of the Betrayer, where the Wardens once held the Master's corpse, you'll find Sargerite Keystone.\n\nGood luck, {name}.", objectives = "Retrieve the Sargerite Keystone.", progress = "Were you successful, <name>? Have you recovered the Sargerite Keystone?", completion = "Finally, revenge against Cordana Felsong for all of the demon hunters whom she tempted into becoming Felsworn. Cyana, Tirathon, Glayvianna, Cailyn, Illysanna, and more.\n\nHer death has been a long time coming.\n\nThe Sargerite Keystone is once more in our possession. Now, to look to the future." }
WordHunterWoW_QuestEN[42754] = { title = "Jump-Capable", description = "While it is true that the Fel Hammer is powered, sadly, its jump engines are non-functional. If we are going to invade a demon world, we're going to have to make the command center jump-capable.\n\nWe need some replacement parts.\n\nLuckily for us, the Legion brought a couple of command centers and soul engines along with them to the Broken Isles. You will find them at Faronaar in Azsuna, and at Felsoul Hold in Suramar.", objectives = "Collect a Fel Engine Injector, a Soul Configuration Matrix, a Fel Engine Ignition, and a Vile Spirit Converter.", progress = "It's vile the way this thing operates. The whole thing is powered by souls... you do NOT want to know what happens to them.", completion = "These will do nicely. We couldn't have asked for better.\n\nTell me, were the demons angry when you stole their precious parts?" }
WordHunterWoW_QuestEN[42755] = { title = "Eye of Azshara: Azsunian Pearls", description = "", objectives = "" }
WordHunterWoW_QuestEN[42756] = { title = "Hunger's End", description = "I am weak. The hunger is devastating, my friend. I understand now why your dragon rests in these pools.\n\n<cough, cough>\n\nI came to warn you but... it looks like I was too late.\n\nI hear him outside now. Ael'Yith... is... here...", objectives = "Kill Ael'Yith and his construct.", completion = "Hah! Ha ha ha haaaa!\n\nI haven't felt this alive in YEARS!\n\nWhat you've done, <name> - not only to replenish my mana pools, but also to save my brood - will not be forgotten. The blues of Azsuna are ever in your debt." }
WordHunterWoW_QuestEN[42757] = { title = "Maw of Souls: Menace of the Seas", description = "", objectives = "" }
WordHunterWoW_QuestEN[42758] = { title = "You're Gonna Need A Bigger Boat!", description = "Sharks. They be the biggest threat to us pirates. Well... after scurvy, ninjas, and the judicial system. Luckily, we only have to deal wit' sharks today.\n\nGo pull some teeth out of their ugly faces 'n bring 'em back to me. I needs a new necklace!", objectives = "Pull 33 Razor-Sharp Shark Teeth.", progress = "I require thirty-three Razor-Sharp Shark Teeth. Do not try to short me, lad.", completion = "Blimey! This one still has blood on it! Looks like he got a good bite on ye good, lad!" }
WordHunterWoW_QuestEN[42762] = { title = "The Wanderer's Companion", description = "Fu Zan... a wise choice. If the legends are true, its powers will be essential to our cause.\n\nWe believe that the staff possessed by the Monkey King could be fabled Fu Zan, yet no one has seen him with the weapon for over a year.\n\nThe Monkey King was last spotted at Tian Monastery. Be prepared for anything! He is known for being... less than forthcoming with his answers.\n\nTak-Tak, a hozen kite-master, is skulking around west of the temple. Speak to him without delay.", objectives = "Speak to Tak-Tak to fly to Tian Monastery and meet with the Monkey King.", completion = "You seek my staff? You make me laugh!\nYou say you want my help and time?\nOkay then, wikket, hear this rhyme:\n\nThree new riddles will I ask,\nThree true answers are your task.\nProve you're smart, show you're worth it.\nAnswer the King and we'll unearth it!" }
WordHunterWoW_QuestEN[42763] = { title = "Dalaran Hidden Demon 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[42764] = { title = "Court of Stars: Wraith in the Machine", description = "", objectives = "" }
WordHunterWoW_QuestEN[42765] = { title = "The Trial at the Temple", description = "My staff was strong and mighty without peer, but since I not its master, in time it would soon disappear.\n\nThe staff was a gift from the Jade Serpent, Yu'lon, but for only a single task. With my work finished, to her again it has passed.\n\nYu'lon be the staff's keeper, holding it for those who are blessed. To her we now go now, to announce your request.", objectives = "Accompany the Monkey King to the Temple of the Jade Serpent and obtain Fu Zan, the Wanderer's Companion.", completion = "I knew you'd succeed, <name>. I'm honored to be at your service." }
WordHunterWoW_QuestEN[42766] = { title = "The Riddle of the Barrel", description = "My weapon is great when in a fight,\nIt's even handy when you sit for a bite.\n\nMy favorite flask I've tied on it, hanging from a cord,\nThe brews within are some of the best that I've ever scored.\n\nIf you truly seek my weapon then bring me something nice to put into my belly,\nA powerful brew is what I want, something strong and smelly.", objectives = "Search for the objects the Monkey King has described in his riddle.", progress = "Ah, it returns. Has the wikkit brought what I'm looking for?", completion = "Them greenies were really curious about this smelly brew. It's powerful and smelly, I wonder if it's delicious too?" }
WordHunterWoW_QuestEN[42767] = { title = "The Riddle of the Land", description = "My weapon is strong but not for attacking, \nProtecting the weak is what it's enacting.\n\nIn the valley are people who till the land from dawn to night,\nThe fruits of their labor, you must show me tonight.\n\nSacks of grain are what I require,\nNot just any will do, only those kissed by a fire.\n\nBring me what I seek.", objectives = "Search for the objects the Monkey King has described in his riddle.", progress = "Ah, it returns. Has the wikkit brought what I'm looking for?", completion = "For this grain, the wikkets work real hard. They toil and struggle so they do not starve.\n\nWith these bags safe from the greenies, we should do the right thing and give them back.\n\nOkay, maybe we take a bit for ourselves, probably just one sack." }
WordHunterWoW_QuestEN[42768] = { title = "The Riddle of Purity", description = "Do you seek my weapon? Then you better answer my question.\n\n  \"I seek something curvy and bendy but with no spine,\n\n   It rushes and rushes leaving chaos behind.\n\n   Sometimes it brings life, sometimes it brings death:\n\n   A little is good, but a lot steals your breath.\n\n   It's as common as dirt, but this part's obscure:\n\n   This stuff comes from a pool that's known to be pure.\"\n\nBring me what I seek.", objectives = "Search for the object the Monkey King has described in his riddle.", progress = "Ah, it returns. Has the wikkit brought what I'm looking for?", completion = "This splashie spirit core holds far more water than you might think. Enough to fill a big bowl or a small sink!\n\nI bet we can find some good use for it, like squeezing it out to make ookin' excellent slerp!" }
WordHunterWoW_QuestEN[42769] = { title = "Court of Stars: Bring Me the Eyes", description = "", objectives = "" }
WordHunterWoW_QuestEN[42770] = { title = "Seeking Guidance", description = "Highlord Tirion may be gone, but the Ashbringer is still out there somewhere. Its power would devastate the Legion. We must find it!\n\nI wish it were as simple as returning to where Tirion fell. It could be anywhere on that infernal landscape by now.\n\nI believe an old friend can help us find the blade. I ask that you place your faith in me and journey to Uther's tomb in the Plaguelands. We will seek answers there.", objectives = "Meet Lord Maxwell Tyrosus at Uther's Tomb in Western Plaguelands.", completion = "These brave watchers require our aid. The Light may well ignore our prayers if we choose not to help our brethren." }
WordHunterWoW_QuestEN[42771] = { title = "Keeping the Peace", description = "The lost souls roaming the cemetery grounds have been drawn to the realm of the living in the wake of the Light's disturbance. In truth, they merely seek comfort... as we all do in these dark times since Highlord Tirion's passing.\n\nHowever, their unrest threatens the very sanctity of the tomb we have sworn to protect. If we are to restore peace here, then they must be exorcised.", objectives = "Exorcise 9 spirits.", progress = "Your aid is greatly appreciated.", completion = "Those poor souls are finally at peace. Thank you." }
WordHunterWoW_QuestEN[42772] = { title = "Sacred Ground", description = "We must ensure that those buried here are never again disturbed. Their spirits' very presence only further perturbs the Light.\n\nThis cannot continue.\n\nI must maintain this barrier to ensure none of the wayward souls enter the Lightbringer's resting place. If you can purify the graves themselves, this madness can finally cease.", objectives = "Purify the graveyards in Sorrow Hill.", progress = "Have the graveyards been purified?", completion = "Good. Given time, the last few lingering souls will make their way home." }
WordHunterWoW_QuestEN[42773] = { title = "The Light Reveals", description = "We seek aid not from a living friend, but one who passed long ago.\n\nUther the Lightbringer was more attuned to the subtleties of the Light than any paladin I've ever known. If we reach out to him, he may be able to help us find the Ashbringer.\n\nThe ceremony has been prepared. Approach the tomb when you are ready.", objectives = "Commune with Uther the Lightbringer.", progress = "We must do whatever it takes.", completion = "Tirion... could it be?" }
WordHunterWoW_QuestEN[42774] = { title = "Hope Prevails", description = "Tirion... still alive! We have to save him.\n\nLight's Hope Chapel is not far from here. We must rally our forces and leave at once for the Broken Shore.", objectives = "Meet Lord Maxwell Tyrosus at Light's Hope Chapel.\n\nProvided item:", completion = "We're ready to depart when you are." }
WordHunterWoW_QuestEN[42775] = { title = "The Crux of the Plan", description = "We have Akama. Cordana Felsong has been eliminated. And, we have the Sargerite Keystone.\n\nEverything is falling into place.\n\nThe honor is all yours, {name}.", objectives = "Place the Sargerite Keystone above the Scouting Map.", progress = "No demon world is beyond our reach now.", completion = "With the Sargerite Keystone in our hands, all that we have to do is prepare our forces and formulate an invasion plan." }
WordHunterWoW_QuestEN[42776] = { title = "Two Worthies", description = "As our forces grow, and our reach extends ever outward, you have need of more trusted companions to handle the most important of missions.\n\nThe time has come for you to elevate two worthies into the ranks of your champions. \n\nIt's my opinion that you should consider recruiting Belath and Malevolence. They have both proven themselves indispensable.", objectives = "Recruit Belath Dawnblade and Matron Mother Malevolence as your champions.", completion = "You now have six champions, all of the Illidari and its forces, as well as a growing army of troops, all willing to make the ultimate sacrifice to bring down the Burning Legion.\n\nTime to prepare for the endgame." }
WordHunterWoW_QuestEN[42777] = { title = "Champion: Belath Dawnblade", description = "", objectives = "You are choosing me as one of your champions?\n\n<Belath looks both surprised and pleased.>\n\nThis is a great distinction. I pledge myself to you again, <name>. I will see to it that the enemies of the Illidari are dealt with in your name." }
WordHunterWoW_QuestEN[42778] = { title = "Scarlet Crusader", description = "", objectives = "" }
WordHunterWoW_QuestEN[42779] = { title = "The Sleeping Corruption", description = "", objectives = "" }
WordHunterWoW_QuestEN[42780] = { title = "Maw of Souls: From Hell's Mouth", description = "", objectives = "" }
WordHunterWoW_QuestEN[42781] = { title = "Court of Stars: Disarming the Watch", description = "", objectives = "" }
WordHunterWoW_QuestEN[42782] = { title = "To Be Prepared", description = "Allies from across Azeroth have come to Stormwind to support our efforts against the Burning Legion.\n\nBefore you ship out, you should pay them a visit. Every bit of preparation helps!", objectives = "Visit Alliance forces in Stormwind Harbor.", progress = "The Light protects those who protect themselves!", completion = "It's good to see you've prepared yourself. You never know what you'll be facing out there.\n\nWe've commissioned these rings for high-ranking members of the Alliance. May this one protect you in the battle to come." }
WordHunterWoW_QuestEN[42783] = { title = "Court of Stars: They Bloom at Night", description = "", objectives = "" }
WordHunterWoW_QuestEN[42784] = { title = "Court of Stars: The Deceitful Student", description = "", objectives = "" }
WordHunterWoW_QuestEN[42785] = { title = "DANGER: Den Mother Ylva", description = "", objectives = "" }
WordHunterWoW_QuestEN[42786] = { title = "Grotesque Remains", description = "These grotesque remains are an amalgamation of jelly-like ooze and what appear to be dryad bones.\n\nGuviena Bladesong would be interested in seeing these.", objectives = "Speak to Guviena Bladesong at the Whispering Bluffs.\n\nProvided item:", completion = "These remains... this is horrible! They are turning dryads into mindless piles of ooze!" }
WordHunterWoW_QuestEN[42787] = { title = "Deal With It Personally", description = "The way I see it, the Wardens owe us for all of those years we were imprisoned. Unfortunately, their new leader, Sira Moonwarden doesn't agree with my assessment.\n\nEven though your champions have already dealt with several of their escaped bounties, she wants more. In fact, as a sign of good faith, she's asking that you deal with it personally.\n\nYou'll have to extinguish the flames of the kobold candles to summon forth the Devouring Darkness. The other two should be more straightforward.", objectives = "Kill the Devouring Darkness in Highmountain, Hertha Grimdottir in Suramar, and Theryssia in Val'sharah.", progress = "How go your efforts to convince the Wardens to tell us where the Sargerite Keystone is located?\n\nIf she doesn't tell us soon, I think we should consider other options where Sira Moonwarden is concerned.", completion = "The Wardens should have cooperated with us much sooner than this. Still, we now know that we need to go find the Warden, Malace Shade, in Stormheim. She was the one entrusted with safeguarding the Sargerite Keystone.\n\nThat information, combined with some scouting I did on my own, will point you in the right direction.\n\nWe'll have the Keystone before you know it, <name>." }
WordHunterWoW_QuestEN[42788] = { title = "Maw of Souls: Return of the Beast", description = "", objectives = "" }
WordHunterWoW_QuestEN[42792] = { title = "Make Your Mark", description = "While you were out, I asked around.\n\nYou are looking for Overseer Durant. Turns out he lives near the Shimmershade Garden.\n\nI can help you confront him, but you will need help. There are three individuals with the necessary skills, and they serve our cause.\n\nTell Cyrille that the owl hoots at dusk.\n\nInform Lorin that the saber prowls the plaza.\n\nMention to Sylessa that the cruel caskmaster has breathed his last.\n\nThey will know what to do. \n\nSpeak to Vanthir when the deed is done.", objectives = "Recruit Sylessa, Cyrille, and Lorin and slay Overseer Durant.", completion = "They will not so easily dismiss the Dusk Lily now. Well done." }
WordHunterWoW_QuestEN[42795] = { title = "WANTED: Sanaar", description = "", objectives = "" }
WordHunterWoW_QuestEN[42796] = { title = "WANTED: Broodmother Shu'malis", description = "", objectives = "" }
WordHunterWoW_QuestEN[42797] = { title = "DANGER: Scythemaster Cil'raman", description = "", objectives = "" }
WordHunterWoW_QuestEN[42798] = { title = "DANGER: Huntress Estrid", description = "", objectives = "" }
WordHunterWoW_QuestEN[42799] = { title = "DANGER: Oglok the Furious", description = "", objectives = "" }
WordHunterWoW_QuestEN[42800] = { title = "Champion: Valeera Sanguinar", description = "", objectives = "Of course I will serve as your champion. In for a copper in for a gold as they say.\n\nWe work well together. I bring out the best in you." }
WordHunterWoW_QuestEN[42801] = { title = "Back in Black", description = "Before you head into the Black Temple, we need more information. The last thing we want is for you to teleport into a trap.\n\nWe must discern their force structure, patrol schedule, new defenses, and what Akama eats for breakfast.\n\n<Belath grins.>\n\nI suggest you send our broken warriors to handle this. They can blend in with the rest of Akama's Ashtongue forces inside the temple. We'll get what we need to know from the ones that make it back.\n\nA champion handler or two can scout outside the temple.", objectives = "Use the Scouting Map and complete the mission, \"Back in Black\".", progress = "Any word from your troops that we sent to infiltrate the Black Temple?", completion = "Belath is such a dear. Very thoughtful of him to arrange for some scouting.\n\nI do hope that not too many of the broken died to get us this information.\n\nIn any case, I now have the means and the perfect location within the Black Temple to make our grand entrance." }
WordHunterWoW_QuestEN[42802] = { title = "Securing Mardum", description = "There has been increased demonic activity below on Mardum. There are still demons leftover down there from when we first invaded.\n\nTo eliminate any threat to the Fel Hammer, it's time that they were destroyed.", objectives = "Use the Scouting Map and complete the mission, \"Securing Mardum\".", completion = "Ariana Fireheart?! I thought she died the first time we were here. How horrible that she's been down there all this time. But, what an amazing survivor!\n\nI remember her being an excellent trainer of demon hunters. We should put her talents to good use immediately." }
WordHunterWoW_QuestEN[42803] = { title = "Invasion: Dun Morogh", description = "", objectives = "" }
WordHunterWoW_QuestEN[42804] = { title = "Invasion: Azshara", description = "", objectives = "" }
WordHunterWoW_QuestEN[42805] = { title = "Invasion: Hillsbrad Foothills", description = "", objectives = "" }
WordHunterWoW_QuestEN[42806] = { title = "DANGER: Fjorlag, the Grave's Chill", description = "", objectives = "" }
WordHunterWoW_QuestEN[42807] = { title = "Demon Commander", description = "", objectives = "" }
WordHunterWoW_QuestEN[42808] = { title = "Green Adepts", description = "As much as I would love us to finesse our way to victory, the cold, hard reality is that we need more powerful forces.\n\nWe are already straining Gaardoun's ability to recruit more broken.\n\nBut now that we have Ariana Fireheart, she can train new demon hunters for us.", objectives = "Speak with your Illidari recruiter, Ariana Fireheart.", completion = "Glad to hear that Ariana has recovered and is ready to train up our first new demon hunters.\n\nIt's been awhile since we had some fresh blood in our ranks." }
WordHunterWoW_QuestEN[42809] = { title = "The Invasion of Niskara", description = "Everything is in place. All systems are operational and we have plenty of fuel. The Fel Hammer's jump engines are ready.\n\nCaria and Varedis know that you are coming for them. Belath's intelligence indicates that they have retreated to the demon prison world of Niskara.\n\nIt's time to begin the invasion and finish this once and for all.", objectives = "Activate the Fel Hammer's control console and complete the scenario, \"The Invasion of Niskara\".", progress = "Finally, our plan of taking the fight directly to the demons is coming to fruition.\n\nYou are making it all happen, <name>.", completion = "We've won the day! Caria and Varedis are no more, and we've sent a clear message to the Burning Legion that they are vulnerable, even on their own worlds.\n\nIt's about time that we celebrated, but first..." }
WordHunterWoW_QuestEN[42810] = { title = "A Final Offer", description = "What was that? Sounds like something's outside.\n\nSomething big...\n\nYou'd better get up there, {name}!", objectives = "Investigate whatever is happening outside of the Fel Hammer.", progress = "What happened?", completion = "Kil'jaeden?! If that's not the gauntlet being thrown down, I don't know what is.\n\nCan we survive this, <name>?" }
WordHunterWoW_QuestEN[42811] = { title = "We Meet at Light's Hope", description = "We must put Highlord Tirion to rest.\n\nThere is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel.\n\nPaladins the world over will join us for the ceremony. I know Tirion would want you there most of all.", objectives = "Join the other paladins at Light's Hope Sanctum beneath Light's Hope Chapel in Eastern Plaguelands.", completion = "It is fitting that you are here.\n\nTime and again, you have fought to save our world. Now, I fear I must ask you to undertake an even greater act of service." }
WordHunterWoW_QuestEN[42812] = { title = "We Meet at Light's Hope", description = "Before we march on the Broken Isles, {name}, we must put Highlord Tirion to rest.\n\nThere is but one place suitable for a paladin of his caliber... Light's Hope Sanctum, a secret bastion of the Light hidden beneath our chapel here.\n\nPaladins the world have gathered below for the ceremony. They await your arrival to begin the ceremony.", objectives = "Join the other paladins at Light's Hope Sanctum beneath Light's Hope Chapel in Eastern Plaguelands.", completion = "It is fitting that you are here.\n\nTime and again, you have fought to save our world. Now, I fear I must ask you to undertake an even greater act of service." }
WordHunterWoW_QuestEN[42813] = { title = "Dalaran Hidden Demon 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[42814] = { title = "An Important Mission", description = "Champion! I bear an urgent message from Danath Trollbane.\n\nHe requests that you join him at Krasus' Landing. He has an urgent mission that requires your expertise!", objectives = "Speak with Danath Trollbane at Krasus' Landing in Dalaran.", completion = "I am relieved you survived the Broken Shore when so many brave heroes were lost.\n\n<Danath hangs his head in a moment of silence.>\n\nI have been recalled from Honor Hold to aid the Alliance in its darkest hour. It is crucial that we learn from our mistakes.\n\nDo you have time to speak?" }
WordHunterWoW_QuestEN[42815] = { title = "Return to the Broken Shore", description = "If I'm to assist in this war, I need firsthand information. I will fly to the Broken Shore and see the battlefield for myself.\n\nYour record as a proven commander is unquestioned, and you were there. I could use your insight.\n\nWill you accompany me to the Broken Shore? I don't anticipate engaging the enemy, but that close to the Fel Storm, one can never be sure.", objectives = "Take Danath's spare mount to the Broken Shore and provide assistance.", completion = "Welcome to the Halls of Valor, hero. Normally one must die to gain entrance, but times have changed." }
WordHunterWoW_QuestEN[42816] = { title = "Val'sharah Hidden Demon 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[42817] = { title = "Val'sharah Hidden Demon 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[42818] = { title = "The Scarlet Assault", description = "The High Inquisitor of the Scarlet Crusade?!\n\nYou will not find High Inquisitor Whitemane listed in the annals of history alongside the names of fallen heroes.\n\nStill... despite her madness and zealotry she held a bond to the Light unmatched by even the greatest paladins.\n\nThere are few scarlet crusaders left on this world, but Scarlet Monastery is far from abandoned. The monastery now houses the most zealous and crazed crusaders the order has left.\n\nSuccess will require a full blown assault.", objectives = "Speak with Thassarian in Scarlet Monastery.", completion = "It is good that you are here, Deathlord <name>. The battle has already begun." }
WordHunterWoW_QuestEN[42819] = { title = "Pocket Wizard", description = "", objectives = "" }
WordHunterWoW_QuestEN[42820] = { title = "DANGER: Aegir Wavecrusher", description = "", objectives = "" }
WordHunterWoW_QuestEN[42821] = { title = "Raising an Army", description = "We underestimated the number of scarlet crusaders still residing in the monastery. The battle for control of the cathedral is taking too long.\n\nIt's time to take a more resourceful approach to the battle...\n\nRaise the fallen crusaders as ghouls and send them back into the battle against their brothers and sisters.\n\nThe Scarlet Crusade will not be able to hold back the tide of undeath for long.", objectives = "Raise 12 Festering Ghouls from the corpses of Scarlet Crusaders.", progress = "Have you completed your mission?", completion = "Soon, the Scarlet Crusade shall be overrun, Deathlord <name>. This battle is nearly finished..." }
WordHunterWoW_QuestEN[42822] = { title = "The Banner of the Ebon Blade", description = "Although the Scarlet Crusade are murderous zealots, the monastery is still blessed by the Light. This places us at a disadvantage.\n\nThe battle for the Scarlet Cathedral will be hard fought, Deathlord.\n\nWith you fighting alongside our brothers and sisters of the Ebon Blade, they will surely be inspired to victory.\n\nTake up the banner of our order and place it near our troops to empower them.\n\nNot even the Light will stop us from our goal!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Place 8 Banners of the Ebon Blade to inspire your troops." }
WordHunterWoW_QuestEN[42823] = { title = "The Scarlet Commander", description = "There is only one more obstacle standing between us and the tomb of Sally Whitemane.\n\nHigh Commander Goodchilde guards the path to the tomb. Although he is a zealot and a murderer, he is still a hardened knight who has dedicated his life to the eradication of our kind.\n\nHe should not be underestimated...\n\nSlay him and our work here will be nearly done.", objectives = "Slay High Commander Goodchilde.", progress = "Has High Commander Goodchilde been slain?", completion = "Our path is clear now, Deathlord. The time has come for us to offer Sally Whitemane the opportunity for redemption." }
WordHunterWoW_QuestEN[42824] = { title = "The Zealot Rises", description = "Sometimes the line between hero and villain is nothing more than perception. As High Inquisitor, Sally Whitemane saw herself as a champion of humanity in the war against the scourge. Yet under her leadership the Scarlet Crusade slew the living along with the undead.\n\nDeath can bring a silent peace to the soul, but not for Sally Whitemane. Her death is one of regret and unrest.\n\nWe will offer her the chance to atone for her crimes. The price will be high, but I have little doubt she will pay it.", objectives = "Raise Sally Whitemane as a Death Knight.", completion = "I have heard that the battle at Scarlet Monastery was a success, thanks to you.\n\nInitiate Whitemane has already begun her training as a <class>. She shows much promise, and I have no doubt she will make a formidable horseman." }
WordHunterWoW_QuestEN[42825] = { title = "Azsuna Hidden Demon 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[42826] = { title = "Highmountain Hidden Demon 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[42827] = { title = "Ancient Mana Chests 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[42828] = { title = "Moths to a Flame", description = "No doubt you have noticed our guests.\n\nI have watched them for a time and seen how they are attracted to the tree. I do not know if they are harmful to our sapling, but we cannot take that chance.\n\nCollect a handful of the insects and bring them to me. I will examine them and determine if they are to be left alone.", objectives = "Collect 4 Underglow Locusts.", progress = "Have you acquired a sufficient sampling?", completion = "Hmm, yes. It is as I suspected." }
WordHunterWoW_QuestEN[42829] = { title = "Make an Entrance", description = "I need you to infiltrate the Twilight Vineyards and bring back something to deal with these insects.\n\nTo do that, you will need a way to bypass the guards that keep the orchards secure.\n\nLy'leth will be able to help us there. I will arrange to have her meet you near the entrance.\n\nGo quickly!", objectives = "Meet with Ly'leth Lunastre outside the Twilight Vineyards.", progress = "Can I help you?", completion = "Let me show you around, then." }
WordHunterWoW_QuestEN[42830] = { title = "Pest Management", description = "", objectives = "" }
WordHunterWoW_QuestEN[42831] = { title = "Vignette: Shal'an", description = "", objectives = "" }
WordHunterWoW_QuestEN[42832] = { title = "The Fruit of Our Efforts", description = "It is my job to maintain appearances here.\n\n<Margaux smiles apologetically.>\n\nYou will have to endure a little showmanship while I walk with you through the vineyard. It is the only way to avoid suspicion.\n\nI will try to help you as I can, but only when it is safe to do so.\n\nCome with me- our first stop is the tasting pavilion. There you can sample some of our work.", objectives = "Taste the Honeyed Infusion, Supple Nectar, and Unctuous Draught.", progress = "Enjoying yourself?", completion = "You may want to cleanse your palate - we craft some strong flavors here!" }
WordHunterWoW_QuestEN[42833] = { title = "How It's Made: Arcwine", description = "<Margaux speaks in a hushed tone.>\n\nWhile we walk through the Vineyard, we may find time to exchange information.\n\nTry not to look alarmed at what you see, hm?\n\n<Margaux flashes a vacant, forced smile.>\n\nShall we press on?", objectives = "Follow Margaux through the Vineyard. Exchange information where possible.", completion = "Welcome, enjoying your tour?" }
WordHunterWoW_QuestEN[42834] = { title = "Intense Concentration", description = "This is a rare treat, I hope you know. Not just anyone is allowed to stand on this hallowed ground.\n\n<Sylverin adjusts his cuffs in a dignified fashion.>\n\nTo participate in the demonstration, simply take up an energy vessel and wade into the pool beside us. \n\nCatch the delicate dewdrops of Nightwell energy in the bowl as they fall- this is the only way one can safely manage its essence.\n\nOnce your vessel is full, proceed to our demonstration cask and gently pour the amalgamation into it.\n\nEnjoy!", objectives = "Catch 15 drops of Nightwell Essence using an Energy Vessel.", progress = "Having trouble?", completion = "Simple, no?" }
WordHunterWoW_QuestEN[42835] = { title = "The Old Fashioned Way", description = "While you experienced the raw majesty that is Nightwell Infusion, Margaux was busy preparing another demonstration for you.\n\nHead across the bridge and to the left, then again across a bridge and to your right. You will find her on the juicing veranda.\n\nEnjoy the remainder of your tour!\n\n<Sylverin offers an intensely fake smile.>", objectives = "Participate in a juicing demonstration.", progress = "Having fun?", completion = "I will be certain to have a bottle of your arcwine prepared for you before you leave." }
WordHunterWoW_QuestEN[42836] = { title = "Silkwing Sabotage", description = "Moths. Who ever heard of something so... barbaric!\n\nThey are eating our crop and the mana wyrms do nothing to deter them.\n\nYou. You seem capable. Deter these creatures so we can complete our harvest on schedule.\n\nAhem. Please.", objectives = "Slay 8 Tattered Silkwings.", progress = "Are you sure you took care of this situation?", completion = "Much better. You have my thanks." }
WordHunterWoW_QuestEN[42837] = { title = "Balance to Spare", description = "Our tour is just about over. I will let you loose to 'walk the orchard', as is proper at this stage.\n\nWhile you are there, you will notice a large number of mana wyrms floating about.\n\nI am certain the vineyard would not miss a handful of them.\n\nGood luck with your insect problem, friend.\n\n<Margaux smiles warmly at you.>", objectives = "Collect 8 Shadescale Flyeaters.", completion = "I will have these... ah... souvenirs... boxed for you." }
WordHunterWoW_QuestEN[42838] = { title = "Reversal", description = "<Sylverin regards you uneasily.>\n\nI was meant to meet you and Margaux here so I could escort you from the Vineyard. \n\nMy mistress Margaux is never late. I fear that something terrible may have happened.\n\nPlease find her and make sure she is well.", objectives = "Locate Margaux.", progress = "How did your trip to the Vineyard go?", completion = "Margaux... no!" }
WordHunterWoW_QuestEN[42839] = { title = "Seek the Unsavory", description = "This is just... unspeakable.\n\nMargaux risked everything to get these mana wyrms to us. I cannot let it end this way.\n\nI need you to find someone who can make this right. Someone who will do whatever it takes to see Overseer Durant slain.\n\nSpeak with Vanthir. I am certain he will know exactly who we need.", objectives = "Speak to Vanthir.", completion = "Steel yourself, <name>.\n\nMargaux's loss is regrettable, but not likely to be the last in this effort. Far from it, I fear." }
WordHunterWoW_QuestEN[42840] = { title = "If Words Don't Work...", description = "Unless you have something worth risking my life for, I will not budge.\n\nVanthir must have told you that my services do not come cheap.\n\nLet's say... enough mana to sustain me for a month.\n\n<Arluin looks smug, as if you could never agree to this request.>", objectives = "Bribe Arluin with 800 Ancient Mana.", progress = "My price will not change. Do we have a deal?", completion = "Glad to know you understand the value of my services, partner." }
WordHunterWoW_QuestEN[42841] = { title = "A Big Score", description = "I'm not rich in anything but information, but maybe that can be of use to someone with your skills. You helped me, now you can help yourself.\n\nThe Magistrix receives a daily shipment of arcwine, which travels to the palace with a heavy escort. I can share the location, provided you leave me a cut of the goods.\n\nOne of my men has infiltrated the group and will hold up the delivery long enough for you to strike.", objectives = "Attack the Magistrix's arcwine shipment and bring Arluin his cut of the stolen goods.", progress = "Where's my cut?", completion = "Pleasure doing business with you." }
WordHunterWoW_QuestEN[42842] = { title = "Ancient Mana Cap 01 Kel'danath's Flask", description = "", objectives = "" }
WordHunterWoW_QuestEN[42844] = { title = "Growing Power", description = "Lord Maxwell Tyrosus has requested your presence back at the Sanctum of Light.\n\nOur campaign to defend the Broken Isles is getting under way, and we need you at the helm.", objectives = "Speak to Maxwell Tyrosus at the Sanctum of Light.", completion = "Thank you for coming so quickly, Highlord." }
WordHunterWoW_QuestEN[42846] = { title = "The Blood Matriarch", description = "I am but the first of many; you must find the holiest of paladins to champion our order.\n\nThere is one other I believe deserves such an honor - Lady Liadrin, Matriarch of the Blood Knights.\n\nGo speak to her now.", objectives = "Enlist Lady Liadrin as a champion of the Order of the Silver Hand.", completion = "Excellent. Both Lord Tyrosus and Lady Liadrin will serve proudly." }
WordHunterWoW_QuestEN[42847] = { title = "Dark Storms", description = "Greetings, Highlord.\n\nBeside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.\n\nThe first task is critical - the storms above the Tomb of Sargeras are intensifying. We should send our champions to keep an eye on that region, and scour the area for possible survivors.", objectives = "Use the Scouting Map and complete the mission, \"Dark Storms.\"", progress = "How is the mission proceeding?", completion = "Maxwell Tyrosus has returned with important news. First, he did recover some survivors. They are recovering in the chapel now. Among them was Commander Ansela, a veteran <class> and trainer.\n\nAs for the second, I will let Sir Tyrosus tell you himself." }
WordHunterWoW_QuestEN[42848] = { title = "Recruiting the Troops", description = "Commander Ansela is a grizzled war veteran and seasoned teacher. Many of our most valiant knights once trained under her.\n\nGo speak to her now, and recruit a squad of Squires.", objectives = "Speak to Commander Ansela and recruit a squad of Squires.", progress = "Additional troops will be very useful for the missions ahead.", completion = "Good. These squires will fight well." }
WordHunterWoW_QuestEN[42849] = { title = "Wrath and Justice", description = "A new mission requires our attention, Highlord {name}. Hearthglen has come under attack by a small demon army.\n\nNo doubt, they are testing our strength... and our patience.\n\nStrength we have in bounds, but my tolerance wears thin. I suggest we send our champions and troops to deal with this threat.", objectives = "Use the Scouting Map and complete the mission, \"Wrath and Justice.\"", progress = "We will show the enemy who they are dealing with.", completion = "Our mission was a success! Not only did we defeat the enemy, but we recruited Alamande Graythorn, a noted scholar from the Hearthglen archives." }
WordHunterWoW_QuestEN[42850] = { title = "Tech It Up a Notch", description = "Alamande Graythorn is well known among scholars of the Light.\n\nHe has long since retired from battle, but his mind is sharp as ever. I wouldn't be surprised if he could take a bout or two in a duel, either.\n\nSpeak to him and see if he has any knowledge to share regarding the improvement of our order hall.", objectives = "Speak to Alamande Graythorn and choose a class hall upgrade.", progress = "Did you learn anything?", completion = "Excellent. I knew Sir Graythorn would come through." }
WordHunterWoW_QuestEN[42851] = { title = "Champion: Vindicator Boros", description = "", objectives = "Highlord, I cannot thank you enough for both saving my life, and opening my eyes.\n\nIt is true I harbor great hatred against the Burning Legion, but you have reminded me that my choices define the path I take.\n\nI choose to live a path of righteousness, and I will follow your leadership and guidance, Highlord." }
WordHunterWoW_QuestEN[42852] = { title = "Champion: Justicar Julia Celeste", description = "", objectives = "For years I have heard of your deeds, Highlord. Now that I have fought at your side, I can say the stories were true.\n\nAllow me to represent the Order of the Silver Hand as a champion of the light, <name>. I will fight justly and bravely, and carry out your orders to the end." }
WordHunterWoW_QuestEN[42853] = { title = "Champion: Aponi Brightmane [NYI]", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[42854] = { title = "Champion: Maximillian of Northshire [NYI]", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[42855] = { title = "Champion: Arator the Redeemer [NYI]", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[42856] = { title = "Champion: Lord Commander Leothraxion [NYI]", description = "", objectives = "You will learn:" }
WordHunterWoW_QuestEN[42857] = { title = "Moist Around the Hedges", description = "These fruit appear to be food to grell.\n\nOld Grizzleback might appreciate it if they were removed from the village.", objectives = "Collect 5 Moist Grizzlecombs  in Grizzleweald.", progress = "You have found a fruit that might be of interest to me?", completion = "Ah yes, this is the grell food supply. Perhaps I can use this to lure them away. Thank you." }
WordHunterWoW_QuestEN[42858] = { title = "Stormheim Hidden Demon 01", description = "", objectives = "" }
WordHunterWoW_QuestEN[42859] = { title = "A Draught of Hope", description = "", objectives = "" }
WordHunterWoW_QuestEN[42860] = { title = "Tracking - God-King Scene", description = "", objectives = "" }
WordHunterWoW_QuestEN[42861] = { title = "DANGER: Boulderfall, the Eroded", description = "", objectives = "" }
WordHunterWoW_QuestEN[42862] = { title = "Highmountain Hidden Demon 02", description = "", objectives = "" }
WordHunterWoW_QuestEN[42863] = { title = "Highmoutain Hidden Demon 03", description = "", objectives = "" }
WordHunterWoW_QuestEN[42864] = { title = "DANGER: Captain Dargun", description = "", objectives = "" }
WordHunterWoW_QuestEN[42865] = { title = "Grell to Pay", description = "The ringleader of the grell must be sent to his final rest.\n\nYou will know him by the white of his skin and the bite of his tongue.", objectives = "Defeat Enderkind in Grizzleweald.", progress = "I miss the days when grell kept to themselves and played tricks on the night elves.", completion = "I don't know if grell have mothers, but I hope that one never kissed his mother with his mouth." }
WordHunterWoW_QuestEN[42866] = { title = "A Sign From The Sky", description = "Greetings, Highlord. I have important news to share with you.\n\nDuring my expedition to the Broken Shore, I saw with my own eyes an extraordinarily luminescent object emerge from the Felstorm. It fell down towards the coast of Suramar, cutting a swath through the tempest itself!\n\nFrom it I felt an incredible surge of power, before it vanished beyond the horizon.\n\nWe need to bring news of this immediately to Archmage Khadgar.", objectives = "Speak to Archmage Khadgar in Dalaran.", completion = "I see that you have an urgent message for me. What is it?" }
WordHunterWoW_QuestEN[42867] = { title = "Meeting of the Silver Hand", description = "The Light's Heart will be safe within our order's walls, but it bears dark tidings.\n\nWe should gather the leaders of our order for a council.\n\nGo and speak to Lady Liadrin, Vindicator Boros, Justicar Julia Celeste, Arator the Redeemer, and Aponi Brightmane. We should seek their wisdom for the days ahead.", objectives = "Speak to Lady Liadrin, Vindicator Boros, Justicar Julia Celeste, Arator the Redeemer, and Aponi Brightmane.", progress = "Have you gathered the council?", completion = "Thank you for gathering everyone together." }
WordHunterWoW_QuestEN[42868] = { title = "The Monkey King's Challenge", description = "You can roll, you can hit, even shoot flaming spit...\nBut can your training you heed? Tasty brew's what I need!\nThe goodies you've gathered are what you must mix,\nThe instructions to follow will come from my lips.\nJust pass this final brewing lesson,\nAnd I will point you to my weapon.", objectives = "Help the Monkey King to complete his brew.", progress = "Ah! This brew is grand! It's fit for a King!", completion = "This brew be excellent! Its taste be the best!\n\nYou've proved yourself well, now I'll tell you where my staff rests." }
WordHunterWoW_QuestEN[42869] = { title = "Eternal Vigil", description = "<Kor'vas glances at your glaives, her eyes widening.>\n\nI'm excited to see what those can do in person! Maybe we can spar a bit before heading out on the next hunt?\n\nWhile you were gone we built a camp just off of this landing to help us watch over the Legion's movements. We should head there right away - Jace needed your help with something. It sounded big!", objectives = "Glide to Illidari Redoubt off of Krasus' Landing.", completion = "I have exciting news to share with you, <name>." }
WordHunterWoW_QuestEN[42870] = { title = "DANGER: Kathaw the Savage", description = "", objectives = "" }
WordHunterWoW_QuestEN[42871] = { title = "Tome of Illusions - Azeroth", description = "", objectives = "" }
WordHunterWoW_QuestEN[42872] = { title = "Securing the Way", description = "I was able to make contact with our forces on Mardum - they secured the Fel Hammer after our departure all those years ago and have held it ever since!\n\nMalevolence has utilized the ship's warp systems to transport the bulk of our forces aboard, but doing so greatly taxes what little power remains.\n\nI believe there to be a better way.\n\nYour glaives carry a piece of the power of Kil'jaeden - you should be able to use them to open a permanent gateway to the Fel Hammer.", objectives = "Use your glaives to rip open a gateway to the Fel Hammer in Mardum.", progress = "Soon our forces will flow freely between the here and the Fel Hammer.", completion = "I look forward to joining the rest of our forces." }
WordHunterWoW_QuestEN[42873] = { title = "Tome of Illusions - Outland", description = "", objectives = "" }
WordHunterWoW_QuestEN[42874] = { title = "Tome of Illusions - Northrend", description = "", objectives = "" }
WordHunterWoW_QuestEN[42875] = { title = "Tome of Illusions - Cataclysm", description = "", objectives = "" }
WordHunterWoW_QuestEN[42876] = { title = "Tome of Illusions - Elemental Lords", description = "", objectives = "" }
WordHunterWoW_QuestEN[42877] = { title = "Tome of Illusions - Pandaria", description = "", objectives = "" }
WordHunterWoW_QuestEN[42878] = { title = "Tome of Illusions - Secrets of the Shado-Pan", description = "", objectives = "" }
WordHunterWoW_QuestEN[42879] = { title = "Tome of Illusions - Draenor", description = "", objectives = "" }
WordHunterWoW_QuestEN[42880] = { title = "Meeting their Quota", description = "", objectives = "" }
WordHunterWoW_QuestEN[42881] = { title = "Champion: Lady Liadrin", description = "", objectives = "Good tidings, <name>. I am told that you seek to stop the demon's reign of terror. Is this true?\n\nThe Legion has hunted our people across countless worlds... taken countless lives. With each of our paladins that falls the Light reels in pain.\n\nI have had enough - I will fight by your side." }
WordHunterWoW_QuestEN[42882] = { title = "The Scarlet Massacre", description = "We have a single purpose here, to raise Sally Whitemane as a Death Knight of the Ebon Blade. Such is our goal and we will see it through.\n\nHowever, the Scarlet Crusade has terrorized the people of Azeroth long enough. Therefore, our work here this day will not be done until every crusader has fallen, every stone has crumbled, and every banner burned.\n\nCome, Deathlord, let us bring ruin upon the Scarlet Crusade.", objectives = "Slay 16 Scarlet Crusaders.", progress = "The Scarlet Crusade shall burn.", completion = "The Scarlet Crusade will pay for their crimes. Soon the monastery shall fall, and with it so too does the Scarlet Crusade's last hope for survival." }
WordHunterWoW_QuestEN[42883] = { title = "All Grell Broke Loose", description = "The grell are in a frenzy, attacking my brethren and destroying our village!\n\nPlease, stranger, help us send these wicked miscreants to the soil.", objectives = "Slay 8 Wildeyed Undergrell in Grizzleweald.", progress = "The grell can sometimes be a terrible nuisance.", completion = "Thank you, <name>. You are welcome in our village anytime." }
WordHunterWoW_QuestEN[42884] = { title = "Grassroots Effort", description = "When I arrived at my home, the front door was barred by magical roots.\n\nI was able to remove them, but few of my tribe possess the necessary ability to do so themselves.\n\nTake my staff. Its powers will easily disentangle the obstructing roots.", objectives = "Use Old Grizzelback's Staff to destroy 5 snarled brambles in Grizzleweald.", progress = "My old bones need more rest than I would care to admit.", completion = "The grell trapped our young within the huts. They are no longer at risk, thanks to your generous efforts." }
WordHunterWoW_QuestEN[42885] = { title = "The Highlord's Command", description = "Tracking down the dreadlord Balnazzar is our highest priority. Let us send defenders of our order to pinpoint his recent movements.", objectives = "Complete the mission, \"The Highlord's Command: Nemesis.\"", progress = "Were you able to find anything?", completion = "Good. This intel will prove vital to our operations." }
WordHunterWoW_QuestEN[42886] = { title = "To Faronaar", description = "We are keeping a close eye on Legion movements at Faronaar in Azsuna.\n\nOur intel suggests that a high-ranking lieutenant, possibly the dreadlord Balnazzar himself, masterminds the attacks in that region.\n\nThis may be our chance to strike a blow at the Legion's leadership.\n\nVindicator Boros commands our forces at the front. He would welcome your help, Highlord.", objectives = "Speak to Vindicator Boros along Old Coast Path.", completion = "Excellent, Highlord. You've arrived." }
WordHunterWoW_QuestEN[42887] = { title = "This Is Retribution", description = "Anger seethes within me like smoldering coals.\n\nOne stoke, and that anger will flare into a roaring flame.\n\nThe Legion's attack on Exodar was just the motivation I needed, Highlord. I've watched my brethren die for the last time.\n\nNow, I will be the one who does the killing. I WILL have justice! Help me, Highlord, and slay any demons you encounter in lower Faronaar.", objectives = "Kill 20 demons in lower Faronaar.", completion = "Glorious." }
WordHunterWoW_QuestEN[42888] = { title = "Communication Orbs", description = "We have important work at hand, Highlord.\n\nSpread out across the legion camp are orbs that are vital to the Legion's planning and strategy.\n\nDestroying them will severely damage their efforts. I will go with you, Highlord, to see this through.", objectives = "Destroy 3 Legion Orbs.", progress = "Without a means of communicating, our enemy will be crippled.", completion = "No... we underestimated the enemy." }
WordHunterWoW_QuestEN[42889] = { title = "The Way Back Home", description = "Hello? This is Chief Telemancer Oculeth. I see you have emerged safely!\n\nI am locking in your location as we speak. I will need you to activate the beacon on your end so we can establish a teleportation link.\n\nGot it? Good.", objectives = "Activate the beacon.", completion = "When you suddenly vanished from our awareness we thought the worst.\n\nI do not know what to make of your adventures... I will need time to process this tragedy.\n\nRegardless, I am glad you are back safe and sound." }
WordHunterWoW_QuestEN[42890] = { title = "The Codex of Command", description = "Boros is in serious trouble.\n\nThe fel lord, Jarvox, guards the pit to the west. Boros is trapped in there, too.\n\nWe need to defeat Jarvox, take the Codex of Command that he carries, and rescue Vindicator Boros.\n\nI am with you, Highlord!", objectives = "Collect 1 Codex of Command and rescue Vindicator Boros.", progress = "Highlord, you have returned.", completion = "Our mission to Faronaar was successful, no thanks to me.\n\nI let my anger get out of control, and I would have paid for it dearly were it not for you.\n\nThank you, Highlord." }
