WordHunterWoW_QuestEN[42911] = { title = "Drowned Mana", description = "How did you end up out here?  Ah well, that's neither here nor there at this point.  What matters is that I need your help!\n\nI see you have some experience fishing. Think you could put that skill to use for me?", objectives = "Fish up a Drowned Mana for Conjurer Margoss.", progress = "Any bites out there?", completion = "That's it! This will do nicely. Please bring me as many of these as you can!" }
