WordHunterWoW_QuestEN[42914] = { title = "Champion: Meryl Felstorm", description = "", objectives = "I have been fighting the Burning Legion for an eternity, <name>. I would be honored to impart my wisdom to you as you lead the fight against them once again. I believe I have picked up a few tricks they will not expect!" }
WordHunterWoW_QuestEN[42915] = { title = "LFGDungeons - Legion - Dungeon Heroic - 1st", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[42916] = { title = "LFGDungeons - Legion - Dungeon Heroic - Nth", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[42917] = { title = "Champion: Archmage Vargoth", description = "", objectives = "You have saved my reputation, not to mention my life! Without your persistence, I would still be hanging above the Nexus yet, <name>. I hope you will accept my everlasting gratitude." }
WordHunterWoW_QuestEN[42918] = { title = "Demonic Runes", description = "Hodir valiantly went through that demonic portal. He should've earned an honorable death, but instead was taken prisoner by Legion scum.\n\nWe always imagined the battles of the end days to take place here in Azeroth, but we shall bring the fight to the enemy if it means sparing one of our own that terrible fate.\n\nHymdall thinks that with the right power source, he can reactivate and redirect the Legion's own gateways. Gather demonic runestones from the Legion and let the final conflict begin!", objectives = "Obtain 30 Demonic Runes from demons in the Broken Isles.", progress = "You bring the demonic runestones, <name>?", completion = "Excellent! The Legion will rue the day they set their sights on Azeroth!" }
WordHunterWoW_QuestEN[42919] = { title = "The Scion's Legacy", description = "The leaders of the Silver Hand have gathered. Listen to their counsel.", objectives = "Listen to the leaders of the council.", progress = "Our next steps will be very important.", completion = "Our mission is clear, but what are our next steps?" }
WordHunterWoW_QuestEN[42920] = { title = "The Invasion of Niskara", description = "Everything is in place. All systems are operational and we have plenty of fuel. The Fel Hammer's jump engines are ready.\n\nCaria and Varedis know that you are coming for them. Belath's intelligence indicates that they have retreated to the demon prison world of Niskara.\n\nIt's time to begin the invasion and finish this once and for all.", objectives = "Activate the Fel Hammer's control console and complete the scenario, \"The Invasion of Niskara\".", progress = "Finally, Illidan's plan of taking the fight directly to the demons is coming to fruition.\n\nYou are making it all happen, <name>.", completion = "We have won the day! Caria and Varedis are no more, and we have sent a clear message to the Burning Legion that they are vulnerable, even on their own worlds.\n\nIt is about time that we celebrated, but first..." }
WordHunterWoW_QuestEN[42921] = { title = "Confrontation at the Black Temple", description = "The book from Lan'dalock is very enlightening. It describes a technique which will provide a simple and elegant bypass around the Black Temple's holy barriers.\n\nI will need but a moment to summon a gateway. Stand back, please.", objectives = "Use the Gateway to the Black Temple and confront Akama.", completion = "Who would have thought he would be working with us?\n\nWe are now one step closer to taking the fight directly to the Burning Legion on their own worlds." }
WordHunterWoW_QuestEN[42922] = { title = "Vault of the Wardens: Startup Sequence", description = "", objectives = "" }
WordHunterWoW_QuestEN[42924] = { title = "Vault of the Wardens: A Grim Matter", description = "", objectives = "" }
WordHunterWoW_QuestEN[42926] = { title = "Vault of the Wardens: How'd He Get Up There?", description = "", objectives = "" }
WordHunterWoW_QuestEN[42927] = { title = "DANGER: Malisandra", description = "", objectives = "" }
WordHunterWoW_QuestEN[42928] = { title = "Silkweave Bandages", description = "", objectives = "Have you brought us supplies?", progress = "Have you brought us supplies?", completion = "Thank you, <name>.\n\nThese bandages will help heal our injured allies." }
WordHunterWoW_QuestEN[42929] = { title = "Highmountain Salmon", description = "", objectives = "Have you brought us supplies?", progress = "Have you brought us supplies?", completion = "Thank you, <name>.\n\nThese salmon will help nourish our tribe." }
WordHunterWoW_QuestEN[42930] = { title = "Big Gamy Ribs", description = "", objectives = "Have you brought us supplies?", progress = "Have you brought us supplies?", completion = "Thank you, <name>.\n\nThis meat will help strengthen our troops." }
WordHunterWoW_QuestEN[42931] = { title = "Where the Hammer Falls", description = "You saved us all, shaman! Thank you!\n\nThrall wants to dive right into the Maelstrom and retrieve the Doomhammer, but I worry - he was badly wounded in that last fight, and that demon Geth'xun may still be alive down there. We should go with him.\n\nHop on Stormbeak when you're ready and we'll track down that artifact!", objectives = "Use Stormbeak to fly into the Maelstrom with Thrall and Mylra.", completion = "The Doomhammer could be anywhere here. And that demon is still alive." }
WordHunterWoW_QuestEN[42932] = { title = "What the Stonemother Knows", description = "We must split up. I am still badly wounded from my encounter with Geth'xun, and I don't want to appear weak before the Stonemother. This task falls to you.\n\nTravel to Therazane's Throne and speak to Therazane herself. Find out if she has seen the Doomhammer.\n\nHelp her if she asks. She is dangerous and mercurial, but this is her realm, and without her aid we will find nothing.", objectives = "Travel to Therazane's Throne and speak with Therazane the Stonemother.", completion = "You there! What is this nonsense falling into my domain? Green fire raining from the Maelstrom! Are you surface dwellers behind this?\n\n<You explain everything to the Stonemother.>\n\nA missing artifact, hm? I have not seen it, but I know where to start. You help the Stonemother, yes, and she will help you." }
WordHunterWoW_QuestEN[42933] = { title = "The Troggs that Fel to Earth", description = "\"Demons\" you say? A \"Burning Legion?\" Hrmph! Nothing burns here but for my ire, shaman, and if these monsters think to corrupt my domain, they will be crushed beneath my dainty beautiful feet!\n\nI have not seen this hammer of yours, but the stone troggs witnessed everything that fell from the sky. Moreover, they've been running amok in the Pale Roost ever since the green fire landed near their home.\n\nBe a dear and lay waste to the Felrock Troggs west of here. Perhaps you can get one of them to talk.", objectives = "Slay 25 Felrock Troggs in the Pale Roost.", progress = "Well? Have you given them a solid thrashing?", completion = "Troggs. So tiresome. Pebbles for brains. Easily swayed by any cult, demon, or dragon that tries to interfere with my rule. Thank you for giving them a solid whomping." }
WordHunterWoW_QuestEN[42934] = { title = "Illusion - Nightmare", description = "", objectives = "" }
WordHunterWoW_QuestEN[42935] = { title = "Stone Drake Rescue", description = "When that demon of yours fell into my realm he must have done something to the troggs. They were never a threat to my beloved stone drakes before.\n\nNow they're loose all over the Pale Roost, subduing drakes on the ground. Put a stop to this insult at once, and free those drakes! They may be of use to us later.", objectives = "Rescue 6 Stone Drakes in the Pale Roost by defeating the troggs that torment them.", progress = "What of my precious little drakes, hm?", completion = "Very very good, <class>. The cavern is once more filled with their delightful wails." }
WordHunterWoW_QuestEN[42936] = { title = "Clutch Play", description = "I confess the stone drake broodmother and I have had a rocky relationship in the past. She supported Deathwing during the Cataclysm, you know. But Aeosera has been put back in her place and it is my responsibility to protect her.\n\nThe problem is that she refuses to abandon her eggs, even in the midst of a trogg attack.\n\nYou're a shaman! Use your natural magnetism to reassemble fallen Opalescent Guardians in the Pale Roost. Escort them to Aeosera so they can carry her eggs to safety of my bosom.", objectives = "Escort 5 Opalescent Guardians to Aeosera.", progress = "Step to it, <class>! Reassemble those guardians and take them to Aeosera!", completion = "How delightful! Aeosera is very pleased with you, <class>. As am I.\n\nNow then, it's time to find that artifact of yours. Thanks to your efforts, the stone drakes will help us." }
WordHunterWoW_QuestEN[42937] = { title = "Needlerock Beatdown", description = "The troggs saw where your hammer fell, and I expect those cowards told the Legion where to find it. Hmph!\n\nThe leader of the stone troggs since the Cataclysm has been \"Borlock,\" a thick-headed little dirt-grubber who's about to get what's coming to him. Find him at Needlerock Spire and beat the information out of him.\n\nTake Aeosera with you. Her and her brood have their own score to settle with those belligerent little beasts.", objectives = "Fly with Aeosera to Needlerock Spire and defeat Borlock of the Deeps.", progress = "Oh I so love to see Aeosera in action.", completion = "Oh ho ho ho! I heard the cavern shake from here, <name>! It's good to rattle some stones and remind everyone who's the boss down here, I must say.\n\nNow about that hammer of yours. Your companions have come up empty, but I think you know where to go next, hm?" }
WordHunterWoW_QuestEN[42938] = { title = "Illusion - Chronos", description = "", objectives = "" }
WordHunterWoW_QuestEN[42939] = { title = "Tracking Down Uthalesh", description = "The logbook contains the latest information on Uthalesh. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", objectives = "Take the logbook to Calydus in Dreadscar Rift.The logbook contains the latest information on Uthalesh. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[42940] = { title = "When There's a Will, There's a Way", description = "The Oculus appears to have fallen to the Burning Legion and is heavily shielded. We will need to figure out a way to get you inside. \n\nI suspect your champions can help us out quite a bit.", objectives = "Ask your champions to find a way into the Oculus.", completion = "Your champions have done well. I think I should be able to get you into the Oculus now." }
