WordHunterWoW_QuestEN[42952] = { title = "Tracking Down the Skull", description = "The logbook contains the latest information on the Skull of the Man'ari. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", objectives = "Take the logbook to Calydus in Dreadscar Rift.The logbook contains the latest information on the Skull of the Man'ari. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[42953] = { title = "DANGER: Soulbinder Halldora", description = "", objectives = "" }
WordHunterWoW_QuestEN[42954] = { title = "A Small Favor", description = "Meryl's illness is troubling. I have seen something similar before, but I cannot think of its name...\n\nTalk to my friend. I call her Ari. She has lived here in the Hall of the Guardian since it was last in use. If a tome on magical afflictions is to be found here, she would know where to look.", objectives = "Talk to Ari.", completion = "Books on magical illnesses? I might know where such a thing exists..." }
WordHunterWoW_QuestEN[42955] = { title = "The Proper Way of Things", description = "Archmage Khadgar is my friend. That he trusts you means much. \n\nI know of the book in which you seek, but it does not want to be found. It is old and angry and thirsts for power. We will have to convince it to emerge from hiding in the proper way. Perhaps if you bring it a gift of nightwell energy from the nightborne elves in Suramar City it will be mollified.", objectives = "Siphon 50 phials of nightwell energy from the nightborne in Suramar City.", progress = "Have you found enough nightwell energy yet?", completion = "Power in its purest form. It is a lovely color, is it not? A fitting gift for a book of healing. Will you come out old one, now that you are no longer lost and forgotten?" }
WordHunterWoW_QuestEN[42956] = { title = "Ari's Package", description = "Look! It was right here under our noses. \"Arcanists Guide to Rare Diseases.\" Sheepish thing. Most books just want to be dusted off and read from time to time. We will leave the phials of nightwell energy and it will go with you meekly enough.\n\nHere. I have packaged the book up for you to bring to Khadgar. I wrapped it in moth's wings to keep it soothed and light-hearted. And there is a gift for you. Just a small thing, really.", objectives = "Bring Ari's package to Archmage Khadgar.\n\nProvided item:", completion = "Ari found just the book I needed! And she included a ring for you as well." }
WordHunterWoW_QuestEN[42957] = { title = "Journey to the East", description = "My riddles you've solved but your job is not complete.\n\nCome, meet me at the Jade Serpent Temple for the answers you seek.", objectives = "Meet with the Monkey King at the Temple of the Jade Serpent within the Jade Forest.\n\nProvided item:", completion = "Ah, there the wikket is. Now, we see how well you can brew!" }
WordHunterWoW_QuestEN[42958] = { title = "Azsuna - Treasure 042 - Felblaze Ingress - Small", description = "", objectives = "" }
WordHunterWoW_QuestEN[42959] = { title = "Three Is a Lucky Number", description = "Ari is much more than she appears, you know. She was once one of the most powerful archmagi on Azeroth and a member of the Council of Tirisfal. Unfortunately her mind was badly damaged and she has not left the Hall of the Guardian since.\n\nShe must like you very much to have given you a gift. If you bring her something special in return, I suspect she will surprise you. She prefers things in threes.", objectives = "Bring Ari 3 special gifts. These gifts can be found on powerful enemies in dungeons.", progress = "Have you found anything special for Ari yet?", completion = "These are wonderful! I couldn't keep them for myself, of course. But... Can you hear the bees humming in the honey brew? They sing so sweetly... Oh! What a lovely idea! Thank you, little friends." }
