WordHunterWoW_QuestEN[42964] = { title = "DANGER: Lagertha", description = "", objectives = "" }
WordHunterWoW_QuestEN[42966] = { title = "The Highlord's Command", description = "Good decision, Highlord. We should be bolstering our forces by increasing recruitment efforts. Let us send our champions to carry out these orders.", objectives = "Complete the mission, \"The Highlord's Command: Holy Allies.\"", completion = "Excellent work." }
WordHunterWoW_QuestEN[42967] = { title = "The Highlord's Command", description = "Well said, Highlord. The Legion is not one individual enemy - it is a massive beast with many heads.\n\nTo defeat them, we will need to stay vigilant on all fronts.\n\nLet us send our champions to deal with the Legion incursions as they come.", objectives = "Complete the mission, \"The Highlord's Command: Legion Defense.\"", completion = "Well done. That should halt the Legion attacks for a while." }
WordHunterWoW_QuestEN[42968] = { title = "The Highlord's Command", description = "You are right, Highlord. Our military efforts cannot succeed without solid logistics.\n\nThat means we need a steady supply of weapons, food, medicine, and other provisions.\n\nLet us send our champions to establish a supply line.", objectives = "Complete the mission, \"The Highlord's Command: Procuring Supplies.\"", completion = "Excellent. Our paladins will be well equipped for battle." }
WordHunterWoW_QuestEN[42969] = { title = "A Spy in Our Midst", description = "", objectives = "" }
WordHunterWoW_QuestEN[42970] = { title = "The Diamond King", description = "Me brother Magni, once King o' Ironforge, got changed into a diamond statue by a titan ritual. He's stood frozen in the belly o' the city fer years.\n\nBut I just got word that he's up and around... sayin' he knows somethin' 'bout how to beat the Legion!\n\nLook, {name}, I dunno if Magni's crazy, or if that's even really him. But if there's even a chance he kin help us...\n\nI'm told he muttered the name Ulduar. That's where I'm headed! I'd be obliged if you an' Khadgar were ta join me.", objectives = "Go with Brann and Khadgar to Ulduar and hear Magni Bronzebeard's message.", completion = "Magni's information was crucial to our efforts against the Legion. And it was good to see him again.\n\nNow to find that tome about the Pillars of Creation..." }
WordHunterWoW_QuestEN[42971] = { title = "Controlling the Elements", description = "Come closer, {race}.\n\nRagnaros in the Firelands, Al'Akir in his Throne of the Four Winds, and Neptulon in Throne of the Tides. They have been thorns in my hide since the world was new.\n\nProve to me your strength over the weaker elements, and I shall teach you how to display your power for all to see.", objectives = "Retrieve Remnants of Fire, Water, and Air, and reach Revered status with Therazane.", progress = "Prove your mastery over magic and the elements, <race>.", completion = "Now the other elements will truly fear you." }
WordHunterWoW_QuestEN[42972] = { title = "Illusion - Poisoned", description = "", objectives = "" }
WordHunterWoW_QuestEN[42973] = { title = "Illusion - Rune of Razorice", description = "", objectives = "" }
WordHunterWoW_QuestEN[42974] = { title = "The Fate of Hodir", description = "It is time, {name}. Go to Azsuna and use the captured gateway to travel to Niskara and find Hodir.\n\nThe Legion will regret they set foot on Azeroth!", objectives = "Join your forces at Felblaze Ingress and Complete the Fate of Hodir scenario.", progress = "You've returned, <name>. What news do you bring?", completion = "I thank you, <name>. Without your help, one of Azeroth's mightiest guardians would have fallen into the hands of the Legion.\n\nYou have proven you are capable of leading my armies and defeating the Legion in their own territory." }
WordHunterWoW_QuestEN[42975] = { title = "Wild Combatant's Chain Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[42976] = { title = "Mage Ch 3 Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[42977] = { title = "Servant of the Windseeker", description = "The elemental lords must be united,  but there has been no Windlord to lead the air elementals since the death of Al'Akir.\n\nOnce, there was an heir to the Throne of Four winds named Prince Thunderaan, but the prince was defeated in the mortal realm and still awaits rebirth. Only one man holds the knowledge necessary to complete the prince's rebirth.\n\nThere is a servant of Thunderaan who wanders the sands of Silithus. Find him, and he will show you the way.", objectives = "Speak with Highlord Demitrian in Silithus.", completion = "What does the Earthen Ring want with an old servant of the Windseeker?" }
WordHunterWoW_QuestEN[42978] = { title = "A Royal Audience", description = "{name},\n\nMy father lived by the sword, as you do. He taught me that if we truly want peace for our kingdom then we must be willing to fight to preserve it, as you have fought.\n\nYou have demonstrated valor of the highest order - bravery unsurpassed in the ranks of the Alliance. Valor that must be recognized.\n\nPlease join me in Stormwind Keep at once so that you can be properly rewarded for your service.\n\n- King Anduin Wrynn", objectives = "Report to King Anduin Wrynn in Stormwind Keep.", completion = "It's an honor, <name>." }
WordHunterWoW_QuestEN[42980] = { title = "Tracking Quest: Lumenstone 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[42981] = { title = "Pure Water", description = "I may have discovered the key to restoring the pillar's magical energy.\n\nFirst, we will require a great deal of Pure Water. It is not easy to find, however I have heard that the naga in the Eye of Azshara are known to carry large quantities of this concentrated essence.\n\nIt will be not be easy, but if you can collect enough of the essence, we may be able to restore the pillar.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 10 Pure Water from naga and water elementals in the Eye of Azshara dungeon." }
WordHunterWoW_QuestEN[42982] = { title = "The Victor's Spoils", description = "It takes a true hero to put their life on the line day after day in defense of their home so that others do not have to.\n\nYou have dutifully safeguarded the people and interests of the Alliance, never faltering in your courage or devotion.\n\nAs a small token of our appreciation for your valiance, please turn to the gathered heroes before you, raise your weapon high, and be recognized.", objectives = "Raise your weapon and be recognized in Stormwind Keep.", progress = "Thank you, <name>. Thank you for everything.", completion = "Well-earned, <name>." }
WordHunterWoW_QuestEN[42983] = { title = "Mistral Essence", description = "To restore the Maelstrom Pillar, we will need to infuse it with the essence of air.\n\nA large quantity of Mistral Essence will be required to do this.\n\nMistral Essence can be found on many of the elementals in Vortex Pinnacle.\n\nIf you can return to me with a ready supply of elemental essence, I will be able to continue my restoration work on the Maelstrom Pillar.", objectives = "Collect 100 Mistral Essences from wind elementals in Vortex Pinnacle. Travel to the Vortex Pinnacle through the portal in the Heart of Azeroth.", progress = "Were you able to collect the necessary amount?", completion = "Excellent. You have exactly the right amount of Mistral Essence necessary to restore the pillar!" }
WordHunterWoW_QuestEN[42984] = { title = "Eye of Azshara: The Scepter of Storms", description = "The element of air can be difficult to contain. We will need a way to magically anchor it to the pillar.\n\nAir, no matter how capricious, cannot resist a good storm.\n\nIn the Eye of Azshara, the naga sorceress known as Lady Hatecoil possesses a powerful relic known as the Scepter of Storms.\n\nRetrieve the scepter, and we will use it to bind the elements of air to the Maelstrom Pillar.", objectives = "Collect the Scepter of Storms from Lady Hatecoil in the Eye of Azshara dungeon.", progress = "I hope it was easy to convince Lady Hatecoil to part with her scepter.", completion = "Yes, this is it! With this, I will be able to bind the element of air nicely. And, maybe do some impressive tricks at future festivities." }
WordHunterWoW_QuestEN[42985] = { title = "A Royal Audience", description = "{name},\n\nThose who do not stand with the Horde stand against it. You, champion, have cut down such enemies in droves.\n\nI admire your dedication. It is through you that we will rise up, more powerful than ever, and put the Alliance in their place once and for all.\n\nJoin me in the Undercity at once. Your victories must be met with due reward.\n\n- Warchief Sylvanas Windrunner", objectives = "Report to Warchief Sylvanas Windrunner in the Undercity.", completion = "The pleasure is mine, <name>." }
WordHunterWoW_QuestEN[42986] = { title = "Enemies of Air", description = "Windlord Thunderaan has retaken the Vortex Pinnacle, but not all of his subjects have taken to his leadership kindly.\n\nIn his kingdom there is still unrest, and it appears there are four viziers who have risen up against him: Mistius, Zeph, Alacris, and Tulmos.\n\nWe will let Thunderaan focus on the war against the Burning Legion while we send our champions to aid Skywall against its enemies.", objectives = "Complete 4 \"Thunderaan's Enemies\" missions.", progress = "How are the missions going?", completion = "Excellent work, Farseer. With events in his realm calmed, Windlord Thunderaan can focus his efforts on the war effort." }
WordHunterWoW_QuestEN[42987] = { title = "The Victor's Spoils", description = "We will never be dominated so long as you stand at the front of our lines. Together we will slaughter anyone who stands in our way.\n\nYou have sacrificed as much as any in the name of the Horde. I will not let your dedication go unnoticed.\n\nFace your fellow champions, {name}. Face them, and be recognized.", objectives = "Raise your weapon and be recognized in the Undercity.", progress = "You have pleased me this day.", completion = "You have impressed me, <name>. No simple feat.\n\nBe sure you continue to do so." }
WordHunterWoW_QuestEN[42988] = { title = "Worldmender", description = "The elements have gathered, and though the Firelands have yet to unite with us, we have more strength on our side than ever before.\n\nHowever, the war with the Burning Legion still rages, and for now we must turn our gaze to the Broken Isles.\n\nWhen we have dealt sufficiently with the immediate threats of the war, we will turn our attention to uniting the Firelands to our cause.", objectives = "Complete 10 World Quests.", progress = "How does the situation look?", completion = "Impressive, truly impressive, Farseer! Everything I believed about your prowess has been proven true.\n\nYou have helped mend the rift caused by our enemies on the Broken Isles. We can rest easier, knowing what we have accomplished." }
WordHunterWoW_QuestEN[42989] = { title = "Ma'haat the Indomitable", description = "In order to imbue the Maelstrom Pillar with the essence of earth, we will need one of the rarest fossils found on Azeroth - an egg.\n\nThe Egg of Gaiath is no ordinary egg; it contains the remnants of an unborn earthen primal, perfectly preserved in stone. There may be a means by which to revive it, but more on that later.\n\nFirst, we must find that egg!\n\nThe Earthen Ring has heard of an ancient being who possesses such an item, but he will require payment in blood!", objectives = "Speak to Ma'haat the Indomitable in Deepholm to acquire a Fossilized Egg. He will require Blood of Sargeras in trade.", completion = "<Ma'haat the Indomitable speaks with a low, rumbling voice>\n\nWhat... do you ask... of the earth?" }
WordHunterWoW_QuestEN[42990] = { title = "Neltharion's Lair: The Earthen Amulet", description = "That you were even able to acquire the Egg of Gaiath  is an incredible feat in itself, but the next step may well be impossible. Still... it is our only hope.\n\nFor the ritual to work, we will need to awaken the latent elemental energy resting inside of this egg.\n\nThere is an item that just may have the ability to do this - a relic known as the Earthen Amulet, rumored to have been created by Loken himself.\n\nIt was lost many ages ago, and has fallen into the hands of Dargrul the Underking.", objectives = "Retrieve the Earthen Amulet from Dargrul the Underking in Neltharion's Lair.", progress = "Neltharion collected many valuable relics. The Earthen Amulet was one of them.", completion = "Yes, this is exactly what we need! I can get to work at once!" }
WordHunterWoW_QuestEN[42991] = { title = "DANGER: Runeseer Sigvid", description = "", objectives = "" }
WordHunterWoW_QuestEN[42992] = { title = "Wild Combatant's Chain Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[42993] = { title = "Wild Combatant's Ringmail Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[42994] = { title = "Wild Combatant's Ringmail Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[42995] = { title = "A Taste For Blood", description = "Such an egg is quite precious, fleshling. Yet, my hunger gnaws so deep...\n\nSuch a barter will cost you... greatly.\n\nBring me 3 Blood of Sargeras, and I will give you the egg.", objectives = "Such an egg is quite precious, fleshling. Yet, my hunger gnaws so deep...\n\nSuch a barter will cost you... greatly.\n\nBring me 5 Blood of Sargeras, and I will give you the egg.", progress = "Such an egg is quite precious, fleshling. Yet, my hunger gnaws so deep...\n\nSuch a barter will cost you... greatly.\n\nBring me 5 Blood of Sargeras, and I will give you the egg.", completion = "<Ma'haat the Indomitable guzzles the Blood of Sargeras down his throat as he speaks.>\n\nYesh... thish ish... just what I wanted. The egg ish... yoursh!" }
WordHunterWoW_QuestEN[42996] = { title = "The Maelstrom Pillar: Air", description = "Elementalist Janai was looking for you earlier, Farseer. It appears that her study of the Maelstrom Pillar has been most enlightening.\n\nIf you have a moment, you should go and meet with her to discuss her progress.", objectives = "Speak to Elementalist Janai at the Heart of Azeroth.", completion = "It is good to see you, Farseer. We have much to discuss!" }
WordHunterWoW_QuestEN[42997] = { title = "The Maelstrom Pillar: Earth", description = "Elementalist Janai has been hard at work restoring the Maelstrom Pillar. As of late, she has been focusing her research on the element of earth.\n\nYou should speak with her when you have a chance. I have heard that she is close to a breakthrough.", objectives = "Speak to Elementalist Janai at the Heart of Azeroth.", completion = "Ah, good timing Farseer! I was hoping you would come by." }
WordHunterWoW_QuestEN[42998] = { title = "Tracking Quest: Return to Firelands 2 Mission Completed", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
