WordHunterWoW_QuestEN[43001] = { title = "Tracking Quest: Return to Firelands 5 Mission Completed", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[43002] = { title = "Blessed Blade of the Windseeker", description = "So the Earthen Ring wishes to resurrect my master?\n\n<Highlord Demitrian laughs maniacally.>\n\nI knew this day would come! At last, humanity understands the power of the Windseeker!\n\nWhen Prince Thunderaan was slain at the hands of treacherous mortals, his soul was trapped within the sacred blade Thunderfury.\n\nTo resurrect my master you will need to find his sword and return it to Skywall. Last I heard, the betrayer who stole my master's sword traveled to the Broken Isles to fight demons.", objectives = "Locate the lost blade of the Windseeker.", progress = "Have you found the key to resurrecting Thunderaan?", completion = "This blade could indeed be the key to resurrecting the Windseeker. However, it has been damaged and the elemental soul within has diminished in power.\n\nTime may very well be running out..." }
WordHunterWoW_QuestEN[43003] = { title = "Return to Janai", description = "<Ma'haat the Indomitable speaks to you with a low, rumbling voice.>\n\nHere... is the Egg of Gaiath. It is yours now.\n\nGo... in peace.", objectives = "Return to Elementalist Janai at the Heart of Azeroth.\n\nProvided item:", completion = "It's true! The Egg of Gaiath does exist... right before my very eyes!" }
WordHunterWoW_QuestEN[43004] = { title = "Wild Combatant's Dreadplate Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[43005] = { title = "Wild Combatant's Dreadplate Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[43006] = { title = "Wild Combatant's Scaled Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[43007] = { title = "Return to the Chamber of Shadows", description = "Lord Jorach Ravenholdt sent me out to find you, {name}. He wants your counsel on some matter of importance.\n\nHe requests your presence back at the Chamber of Shadows.", objectives = "Speak with Lord Jorach Ravenholdt in the Chamber of Shadows.", completion = "It is good that Valeera was able to find you so quickly.\n\nThere is something important that you must immediately attend to." }
WordHunterWoW_QuestEN[43008] = { title = "Wild Combatant's Scaled Armor", description = "", objectives = "" }
